  <String, dynamic>{'id': "A1-U01-L36", 'level': 'A1', 'title': "Comprendre What does this mean?", 'subtitle': "Sous-chapitre 1 • Leçon 36/50", 'explanation': "What does this mean? signifie « Qu’est-ce que cela signifie ? ». Après does, le verbe principal reste à sa forme de base : mean.", 'example': "What does “brave” mean? = Que signifie « brave » ?", 'french': "Que signifie « brave » ?", 'question': "Complète : What does this ___?", 'options': <String>["means", "mean", "meaning"], 'answer': 1, 'correction': "Après does, on utilise mean, sans -s.", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U01-L37", 'level': 'A1', 'title': "Répondre avec yes et no", 'subtitle': "Sous-chapitre 1 • Leçon 37/50", 'explanation': "Yes signifie oui et no signifie non. Pour être plus précis, on ajoute souvent une réponse courte qui reprend l’auxiliaire de la question.", 'example': "Yes, I do. = Oui ; No, I don’t. = Non, pour une question avec do.", 'french': "Oui ; No, I don’t. = Non, pour une question avec do.", 'question': "Quel mot signifie non ?", 'options': <String>["Yes", "No", "Please"], 'answer': 1, 'correction': "No signifie non ; la réponse complète dépend de la question.", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U01-L38", 'level': 'A1', 'title': "Faire une réponse courte polie", 'subtitle': "Sous-chapitre 1 • Leçon 38/50", 'explanation': "Ajoute please ou thank you pour rendre une réponse plus polie. Le ton de voix aide aussi à exprimer le respect.", 'example': "Yes, please. = Oui, s’il vous plaît ; No, thank you. = Non, merci.", 'french': "Oui, s’il vous plaît ; No, thank you. = Non, merci.", 'question': "Quelle réponse refuse poliment ?", 'options': <String>["No, thank you.", "No!", "Go away."], 'answer': 0, 'correction': "Thank you adoucit le refus.", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U01-L39", 'level': 'A1', 'title': "Reconnaître I’m et you’re", 'subtitle': "Sous-chapitre 1 • Leçon 39/50", 'explanation': "I’m est la contraction de I am ; you’re est la contraction de you are. Ces formes sont fréquentes dans la conversation.", 'example': "I’m happy. = Je suis content ; You’re ready. = Tu es prêt.", 'french': "Je suis content ; You’re ready. = Tu es prêt.", 'question': "You’re signifie…", 'options': <String>["You is", "You are", "Your are"], 'answer': 1, 'correction': "You’re = you are ; your est un possessif.", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U01-L40", 'level': 'A1', 'title': "Prononcer I am et I’m", 'subtitle': "Sous-chapitre 1 • Leçon 40/50", 'explanation': "I am est la forme complète ; I’m est la contraction fréquente à l’oral. Les deux ont le même sens.", 'example': "I am a student. = Je suis étudiant ; I’m a student. = Je suis étudiant.", 'french': "Je suis étudiant ; I’m a student. = Je suis étudiant.", 'question': "Quelle contraction de I am ready est correcte ?", 'options': <String>["I’m ready.", "I ready.", "I’m be ready."], 'answer': 0, 'correction': "I’m remplace I am ; n’ajoute pas un autre verbe be.", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U01-L41", 'level': 'A1', 'title': "Compter de onze à vingt", 'subtitle': "Sous-chapitre 1 • Leçon 41/50", 'explanation': "Les nombres 11 à 19 ont des formes particulières ; 20 se dit twenty. Attention à eleven, twelve, thirteen et fifteen.", 'example': "eleven 11 ; twelve 12 ; thirteen 13 ; fifteen 15 ; twenty 20.", 'french': "eleven 11 ; twelve 12 ; thirteen 13 ; fifteen 15 ; twenty 20.", 'question': "Que signifie fifteen ?", 'options': <String>["13", "15", "50"], 'answer': 1, 'correction': "Fifteen signifie quinze ; fifty signifie cinquante.", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U01-L42", 'level': 'A1', 'title': "Compter par dizaines jusqu’à cent", 'subtitle': "Sous-chapitre 1 • Leçon 42/50", 'explanation': "Les dizaines comprennent twenty, thirty, forty, fifty, sixty, seventy, eighty et ninety. Attention : forty ne prend pas de u.", 'example': "twenty 20 ; thirty 30 ; forty 40 ; fifty 50 ; one hundred 100.", 'french': "twenty 20 ; thirty 30 ; forty 40 ; fifty 50 ; one hundred 100.", 'question': "Comment écrit-on 40 ?", 'options': <String>["fourty", "forty", "fourteen"], 'answer': 1, 'correction': "L’orthographe correcte est forty.", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U01-L43", 'level': 'A1', 'title': "Dire son âge", 'subtitle': "Sous-chapitre 1 • Leçon 43/50", 'explanation': "Pour donner son âge, utilise I am ou I’m + nombre + years old. En anglais, on ne dit pas I have 16 years pour exprimer l’âge.", 'example': "I’m sixteen years old. = J’ai seize ans ; She is ten. = Elle a dix ans.", 'french': "J’ai seize ans ; She is ten. = Elle a dix ans.", 'question': "Comment dire « J’ai 12 ans » ?", 'options': <String>["I have twelve years.", "I am twelve years old.", "I twelve years."], 'answer': 1, 'correction': "L’âge se construit avec be, pas have.", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U01-L44", 'level': 'A1', 'title': "Comprendre les numéros de téléphone", 'subtitle': "Sous-chapitre 1 • Leçon 44/50", 'explanation': "On lit généralement les chiffres d’un numéro de téléphone un par un. Zero est clair pour les débutants ; certains anglophones disent aussi oh dans certains contextes.", 'example': "My number is 555-0142. = Mon numéro est 555-0142 (exemple fictif).", 'french': "Mon numéro est 555-0142 (exemple fictif).", 'question': "Comment lit-on habituellement un numéro de téléphone ?", 'options': <String>["Comme un seul grand nombre", "Chiffre par chiffre", "Seulement par dizaines"], 'answer': 1, 'correction': "Les chiffres séparés sont plus faciles à comprendre au téléphone.", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U01-L45", 'level': 'A1', 'title': "Donner son numéro lentement", 'subtitle': "Sous-chapitre 1 • Leçon 45/50", 'explanation': "Annonce My phone number is… puis prononce les chiffres par petits groupes. Demande confirmation si nécessaire ; les exercices utilisent uniquement des numéros fictifs.", 'example': "My phone number is 555-0142. = Mon numéro est 555-0142 (fictif).", 'french': "Mon numéro est 555-0142 (fictif).", 'question': "Quelle phrase introduit un numéro de téléphone ?", 'options': <String>["My phone number is…", "My phone is number age…", "I number phone…"], 'answer': 0, 'correction': "Cette structure annonce clairement le numéro.", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U01-L46", 'level': 'A1', 'title': "Nommer des pays courants", 'subtitle': "Sous-chapitre 1 • Leçon 46/50", 'explanation': "Les noms de pays prennent une majuscule. Pour parler de son origine, utilise I’m from + pays.", 'example': "I’m from Canada. = Je viens du Canada ; I’m from the United States. = Je viens des États-Unis.", 'french': "Je viens du Canada ; I’m from the United States. = Je viens des États-Unis.", 'question': "Complète : I’m ___ Canada.", 'options': <String>["at", "from", "on"], 'answer': 1, 'correction': "I’m from indique l’origine.", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U01-L47", 'level': 'A1', 'title': "Dire les langues parlées", 'subtitle': "Sous-chapitre 1 • Leçon 47/50", 'explanation': "Pour parler des langues, utilise I speak + langue. Les noms de langues prennent une majuscule : English, French, Swahili.", 'example': "I speak English and French. = Je parle anglais et français ; She speaks Swahili. = Elle parle swahili.", 'french': "Je parle anglais et français ; She speaks Swahili. = Elle parle swahili.", 'question': "Comment dire « Je parle anglais » ?", 'options': <String>["I speak English.", "I am speak English.", "I speaks English."], 'answer': 0, 'correction': "Avec I, utilise speak sans -s ; les langues prennent une majuscule.", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U01-L48", 'level': 'A1', 'title': "Remplir une présentation courte", 'subtitle': "Sous-chapitre 1 • Leçon 48/50", 'explanation': "Une présentation simple peut contenir le prénom, le pays, les langues et un goût. Utilise des phrases courtes et vérifie les majuscules.", 'example': "Hi! I’m Alex. I’m from Canada. I speak English. I like football. = Salut ! Je suis Alex. Je viens du Canada. Je parle anglais. J’aime le football.", 'french': "Salut ! Je suis Alex. Je viens du Canada. Je parle anglais. J’aime le football.", 'question': "Quelle phrase indique l’origine ?", 'options': <String>["I like football.", "I’m from Canada.", "I’m happy."], 'answer': 1, 'correction': "I’m from + pays indique l’origine.", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U01-L49", 'level': 'A1', 'title': "Écouter une présentation", 'subtitle': "Sous-chapitre 1 • Leçon 49/50", 'explanation': "Pendant l’écoute, repère le prénom, le pays, les langues et les goûts. Il n’est pas nécessaire de comprendre chaque mot pour saisir l’idée générale.", 'example': "Hi, I’m Mia. I’m from the US. I speak English. I like music. = Salut, je suis Mia. Je viens des États-Unis. Je parle anglais. J’aime la musique.", 'french': "Salut, je suis Mia. Je viens des États-Unis. Je parle anglais. J’aime la musique.", 'question': "Dans cet exemple, qu’est-ce que Mia aime ?", 'options': <String>["Football", "Music", "Cooking"], 'answer': 1, 'correction': "I like music signifie « J’aime la musique ».", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U01-L50", 'level': 'A1', 'title': "Révision : première rencontre", 'subtitle': "Sous-chapitre 1 • Leçon 50/50", 'explanation': "Cette leçon réunit les salutations, les présentations, la demande de répétition et les formules de politesse. Réutilise les expressions dans un dialogue, plutôt que de mémoriser des phrases isolées.", 'example': "Hello! I’m Alex. Nice to meet you. — Nice to meet you too. Can you repeat your name, please? = Bonjour ! Je suis Alex. Ravi de te rencontrer. — Moi aussi. Peux-tu répéter ton nom, s’il te plaît ?", 'french': "Bonjour ! Je suis Alex. Ravi de te rencontrer. — Moi aussi. Peux-tu répéter ton nom, s’il te plaît ?", 'question': "Quelle phrase demande poliment de répéter un nom ?", 'options': <String>["Can you repeat your name, please?", "How old your name?", "You name repeat!"], 'answer': 0, 'correction': "La structure Can you + verbe de base permet de faire une demande ; please ajoute de la politesse.", 'unit': 1, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L01", 'level': 'A1', 'title': "Ordre sujet-verbe-complément", 'subtitle': "Sous-chapitre 2 • Leçon 1/50", 'explanation': "En anglais, une phrase affirmative simple suit généralement Sujet + Verbe + Complément. Le sujet est souvent obligatoire, même quand le français peut l’omettre.", 'example': "I like music. = J’aime la musique. / She reads books. = Elle lit des livres.", 'french': "Elle lit des livres.", 'question': "Quelle phrase suit l’ordre anglais habituel ?", 'options': <String>["I music like.", "I like music.", "Like I music."], 'answer': 1, 'correction': "Le sujet I vient avant le verbe like, puis le complément music.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L02", 'level': 'A1', 'title': "Pronoms I et you", 'subtitle': "Sous-chapitre 2 • Leçon 2/50", 'explanation': "I signifie je ou j’ ; il s’écrit toujours avec une majuscule. You signifie tu, vous ou toi selon le contexte.", 'example': "I am ready. = Je suis prêt. / You are my friend. = Tu es mon ami.", 'french': "Tu es mon ami.", 'question': "Quel pronom signifie « je » ?", 'options': <String>["I", "You", "They"], 'answer': 0, 'correction': "I désigne la personne qui parle et prend toujours une majuscule.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L03", 'level': 'A1', 'title': "Pronoms he et she", 'subtitle': "Sous-chapitre 2 • Leçon 3/50", 'explanation': "He désigne généralement une personne masculine ; she une personne féminine. Le choix du pronom suit la personne dont on parle.", 'example': "He is my brother. = C’est mon frère. / She is my sister. = C’est ma sœur.", 'french': "C’est ma sœur.", 'question': "Quel pronom correspond à une sœur ?", 'options': <String>["He", "She", "It"], 'answer': 1, 'correction': "She est le pronom personnel sujet habituel pour une femme ou une fille.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L04", 'level': 'A1', 'title': "Pronom it pour choses et animaux", 'subtitle': "Sous-chapitre 2 • Leçon 4/50", 'explanation': "It sert souvent à parler d’une chose, d’un objet ou d’un animal quand son sexe n’est pas pertinent. Pour une personne, on utilise normalement he ou she selon le contexte.", 'example': "It is a book. = C’est un livre. / The dog is small. It is cute. = Le chien est petit. Il est mignon.", 'french': "Le chien est petit. Il est mignon.", 'question': "Quel pronom convient pour un téléphone ?", 'options': <String>["He", "It", "We"], 'answer': 1, 'correction': "Un objet se reprend normalement avec it.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L05", 'level': 'A1', 'title': "Pronoms we et they", 'subtitle': "Sous-chapitre 2 • Leçon 5/50", 'explanation': "We signifie nous ; they signifie ils ou elles. We inclut la personne qui parle ; they désigne d’autres personnes ou choses.", 'example': "We are students. = Nous sommes élèves. / They are at school. = Ils sont à l’école.", 'french': "Ils sont à l’école.", 'question': "Quel pronom signifie « nous » ?", 'options': <String>["They", "We", "You"], 'answer': 1, 'correction': "We inclut le locuteur ; they parle d’un groupe distinct.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L06", 'level': 'A1', 'title': "Remplacer un nom par un pronom", 'subtitle': "Sous-chapitre 2 • Leçon 6/50", 'explanation': "Pour éviter de répéter un nom, utilise un pronom sujet adapté. Le pronom doit correspondre à la personne ou à la chose dont tu parles.", 'example': "Anna is here. She is happy. = Anna est ici. Elle est contente.", 'french': "Anna est ici. Elle est contente.", 'question': "Remplace “Tom” dans “Tom is tired” par le pronom approprié.", 'options': <String>["He", "It", "We"], 'answer': 0, 'correction': "Tom est un prénom masculin dans cet exemple ; on le reprend avec he.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L07", 'level': 'A1', 'title': "Sens et usages de to be", 'subtitle': "Sous-chapitre 2 • Leçon 7/50", 'explanation': "To be signifie être. Au présent, ses formes sont am, is et are. Il sert notamment à donner une identité, un état ou une description.", 'example': "I am a student. = Je suis élève. / They are happy. = Ils sont contents.", 'french': "Ils sont contents.", 'question': "Quelle phrase utilise correctement to be ?", 'options': <String>["She are happy.", "She is happy.", "She am happy."], 'answer': 1, 'correction': "Avec she, la forme au présent est is.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L08", 'level': 'A1', 'title': "Utiliser am avec I", 'subtitle': "Sous-chapitre 2 • Leçon 8/50", 'explanation': "Avec le sujet I, le verbe be au présent devient am. La forme contractée I’m est très courante à l’oral.", 'example': "I am tired. = Je suis fatigué. / I’m ready. = Je suis prêt.", 'french': "Je suis prêt.", 'question': "Complète : I ___ happy.", 'options': <String>["is", "are", "am"], 'answer': 2, 'correction': "I prend toujours am dans la phrase affirmative au présent de be.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L09", 'level': 'A1', 'title': "Utiliser is avec he, she et it", 'subtitle': "Sous-chapitre 2 • Leçon 9/50", 'explanation': "Au présent, he, she et it sont suivis de is. La contraction is peut s’attacher au sujet : he’s, she’s, it’s.", 'example': "He is tall. = Il est grand. / It’s cold. = Il fait froid.", 'french': "Il fait froid.", 'question': "Complète : She ___ my friend.", 'options': <String>["am", "is", "are"], 'answer': 1, 'correction': "Avec she, on utilise is.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L10", 'level': 'A1', 'title': "Utiliser are avec you, we et they", 'subtitle': "Sous-chapitre 2 • Leçon 10/50", 'explanation': "Au présent de be, are accompagne you, we et they. Les contractions you’re, we’re et they’re sont fréquentes.", 'example': "You are kind. = Tu es gentil. / We’re ready. = Nous sommes prêts.", 'french': "Nous sommes prêts.", 'question': "Complète : They ___ here.", 'options': <String>["is", "am", "are"], 'answer': 2, 'correction': "They est suivi de are.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L11", 'level': 'A1', 'title': "Phrase affirmative avec to be", 'subtitle': "Sous-chapitre 2 • Leçon 11/50", 'explanation': "Pour faire une phrase affirmative avec be, place le sujet puis am, is ou are, puis l’information. Le complément peut être un nom, un adjectif ou un lieu.", 'example': "I am a student. = Je suis élève. / They are at home. = Ils sont à la maison.", 'french': "Ils sont à la maison.", 'question': "Quelle phrase est affirmative et correcte ?", 'options': <String>["He is a teacher.", "He are teacher.", "Is he a teacher."], 'answer': 0, 'correction': "Une affirmation suit sujet + be + information.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L12", 'level': 'A1', 'title': "Négation avec not", 'subtitle': "Sous-chapitre 2 • Leçon 12/50", 'explanation': "Pour nier une phrase avec be, place not après am, is ou are. Les formes contractées isn’t et aren’t sont courantes.", 'example': "I am not tired. = Je ne suis pas fatigué. / She isn’t here. = Elle n’est pas ici.", 'french': "Elle n’est pas ici.", 'question': "Complète : He is ___ ready.", 'options': <String>["not", "no", "doesn’t"], 'answer': 0, 'correction': "Avec be, la négation se forme avec not après le verbe.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L13", 'level': 'A1', 'title': "Contractions isn’t et aren’t", 'subtitle': "Sous-chapitre 2 • Leçon 13/50", 'explanation': "Isn’t signifie is not ; aren’t signifie are not. Ces contractions rendent la conversation plus naturelle et sont fréquentes à l’écrit informel.", 'example': "She isn’t busy. = Elle n’est pas occupée. / They aren’t late. = Ils ne sont pas en retard.", 'french': "Ils ne sont pas en retard.", 'question': "Que signifie aren’t ?", 'options': <String>["are not", "am not", "is not"], 'answer': 0, 'correction': "Aren’t est la contraction de are not.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L14", 'level': 'A1', 'title': "Question avec to be", 'subtitle': "Sous-chapitre 2 • Leçon 14/50", 'explanation': "Pour poser une question avec be, place am, is ou are avant le sujet. La structure devient Verbe + Sujet + complément ?", 'example': "Are you ready? = Es-tu prêt ? / Is she at home? = Est-elle à la maison ?", 'french': "Est-elle à la maison ?", 'question': "Comment former une question avec le verbe to be ?", 'options': <String>["You are ready?", "Are you ready?", "Do you are ready?"], 'answer': 1, 'correction': "Avec be, on inverse le verbe et le sujet ; on n’ajoute pas do.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L15", 'level': 'A1', 'title': "Réponse courte à Are you…?", 'subtitle': "Sous-chapitre 2 • Leçon 15/50", 'explanation': "À une question avec Are you…?, réponds Yes, I am ou No, I’m not. La réponse courte reprend be et le sujet adapté.", 'example': "Are you ready? — Yes, I am. = Es-tu prêt ? — Oui.", 'french': "Es-tu prêt ? — Oui.", 'question': "Quelle réponse courte est correcte ?", 'options': <String>["Yes, I do.", "Yes, I am.", "Yes, I are."], 'answer': 1, 'correction': "La question utilise be, donc la réponse courte utilise am.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L16", 'level': 'A1', 'title': "Réponses Yes, I am et No, I’m not", 'subtitle': "Sous-chapitre 2 • Leçon 16/50", 'explanation': "Pour une réponse affirmative courte, dis Yes, I am. Pour une réponse négative, dis No, I’m not. Évite Yes, I’m dans une réponse courte standard.", 'example': "Are you a student? — Yes, I am. / No, I’m not.", 'french': "Are you a student? — Yes, I am. / No, I’m not.", 'question': "Quelle est la réponse négative correcte ?", 'options': <String>["No, I don’t.", "No, I’m not.", "No, I aren’t."], 'answer': 1, 'correction': "La réponse reprend le verbe be de la question.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L17", 'level': 'A1', 'title': "Reconnaître les noms communs", 'subtitle': "Sous-chapitre 2 • Leçon 17/50", 'explanation': "Un nom désigne une personne, un lieu, une chose ou une idée. En anglais, un nom peut être précédé d’un article ou d’un déterminant.", 'example': "teacher = professeur ; city = ville ; book = livre.", 'french': "professeur ; city = ville ; book = livre.", 'question': "Lequel est un nom ?", 'options': <String>["quickly", "teacher", "beautiful"], 'answer': 1, 'correction': "Teacher désigne une personne ; quickly est un adverbe et beautiful un adjectif.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L18", 'level': 'A1', 'title': "Singulier et pluriel", 'subtitle': "Sous-chapitre 2 • Leçon 18/50", 'explanation': "Le singulier désigne une seule chose ; le pluriel en désigne plusieurs. Beaucoup de noms prennent -s au pluriel, mais il existe des exceptions.", 'example': "one book = un livre ; two books = deux livres.", 'french': "un livre ; two books = deux livres.", 'question': "Quel est le pluriel de book ?", 'options': <String>["bookes", "books", "book"], 'answer': 1, 'correction': "On ajoute généralement -s à book.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L19", 'level': 'A1', 'title': "Pluriels réguliers en -s", 'subtitle': "Sous-chapitre 2 • Leçon 19/50", 'explanation': "Pour de nombreux noms, ajoute simplement -s au pluriel. Le nom reste identique à l’oral ou change légèrement selon sa terminaison.", 'example': "cat → cats ; student → students.", 'french': "cat → cats ; student → students.", 'question': "Choisis le pluriel de student.", 'options': <String>["studentes", "students", "student"], 'answer': 1, 'correction': "La règle régulière ajoute -s.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L20", 'level': 'A1', 'title': "Pluriels en -es", 'subtitle': "Sous-chapitre 2 • Leçon 20/50", 'explanation': "Les noms terminés par certains sons, notamment s, sh, ch, x ou z, prennent souvent -es pour faciliter la prononciation.", 'example': "bus → buses ; box → boxes ; watch → watches.", 'french': "bus → buses ; box → boxes ; watch → watches.", 'question': "Quel est le pluriel de box ?", 'options': <String>["boxs", "boxes", "boxies"], 'answer': 1, 'correction': "On ajoute -es après x.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L21", 'level': 'A1', 'title': "Pluriels irréguliers fréquents", 'subtitle': "Sous-chapitre 2 • Leçon 21/50", 'explanation': "Certains pluriels ne suivent pas la règle -s : man → men, woman → women, child → children, person → people.", 'example': "one child = un enfant ; two children = deux enfants.", 'french': "un enfant ; two children = deux enfants.", 'question': "Quel est le pluriel de child ?", 'options': <String>["childs", "children", "childes"], 'answer': 1, 'correction': "Children est un pluriel irrégulier à mémoriser.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L22", 'level': 'A1', 'title': "Article a devant un son consonne", 'subtitle': "Sous-chapitre 2 • Leçon 22/50", 'explanation': "A signifie un ou une devant un nom singulier dénombrable qui commence par un son consonne. Le choix dépend du son, pas seulement de la lettre écrite.", 'example': "a book = un livre ; a university = une université (le début se prononce /juː/).", 'french': "a book = un livre ; a university = une université (le début se prononce /juː/).", 'question': "Choisis la bonne forme : ___ book.", 'options': <String>["a", "an", "the"], 'answer': 0, 'correction': "Book commence par un son consonne.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L23", 'level': 'A1', 'title': "Article an devant un son voyelle", 'subtitle': "Sous-chapitre 2 • Leçon 23/50", 'explanation': "An s’utilise devant un nom singulier dénombrable qui commence par un son voyelle. Il faut écouter le son initial.", 'example': "an apple = une pomme ; an hour = une heure (h muet).", 'french': "une pomme ; an hour = une heure (h muet).", 'question': "Choisis la bonne forme : ___ apple.", 'options': <String>["a", "an", "the"], 'answer': 1, 'correction': "Apple commence par un son voyelle.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L24", 'level': 'A1', 'title': "Choisir a ou an selon le son", 'subtitle': "Sous-chapitre 2 • Leçon 24/50", 'explanation': "A ou an dépend du premier son du mot suivant. C’est le son qui compte : a university mais an umbrella.", 'example': "a car ; an orange ; a uniform ; an hour.", 'french': "a car ; an orange ; a uniform ; an hour.", 'question': "Quelle expression est correcte ?", 'options': <String>["a orange", "an orange", "the orange (si l’on parle d’une orange quelconque)"], 'answer': 1, 'correction': "Orange commence par un son voyelle ; on utilise an.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L25", 'level': 'A1', 'title': "Comprendre the", 'subtitle': "Sous-chapitre 2 • Leçon 25/50", 'explanation': "The désigne une chose précise ou déjà connue dans le contexte. A/an présente souvent une chose pour la première fois ; the peut la reprendre ensuite.", 'example': "I see a dog. The dog is small. = Je vois un chien. Le chien est petit.", 'french': "Je vois un chien. Le chien est petit.", 'question': "Dans la deuxième phrase, pourquoi dit-on the dog ?", 'options': <String>["Le chien est maintenant identifié", "Le mot est toujours pluriel", "The signifie toujours un"], 'answer': 0, 'correction': "Le chien a déjà été introduit dans le discours.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L26", 'level': 'A1', 'title': "Distinguer a/an et the", 'subtitle': "Sous-chapitre 2 • Leçon 26/50", 'explanation': "A/an présente généralement un nom singulier dénombrable non spécifique ; the identifie quelque chose de précis. Le contexte décide souvent du choix.", 'example': "I need a pen. = J’ai besoin d’un stylo. Where is the pen? = Où est le stylo ?", 'french': "J’ai besoin d’un stylo. Where is the pen? = Où est le stylo ?", 'question': "Tu demandes un stylo quelconque. Quel article convient ?", 'options': <String>["a", "the", "an toujours"], 'answer': 0, 'correction': "A présente un stylo non spécifique ; the renverrait à un stylo identifié.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L27", 'level': 'A1', 'title': "Utiliser this", 'subtitle': "Sous-chapitre 2 • Leçon 27/50", 'explanation': "This signifie « ce/cette…-ci » et sert pour une chose singulière proche du locuteur. Il s’emploie avec is dans une phrase simple.", 'example': "This is my book. = C’est mon livre-ci.", 'french': "C’est mon livre-ci.", 'question': "Complète : This ___ my bag.", 'options': <String>["are", "is", "am"], 'answer': 1, 'correction': "This est singulier ; on utilise is.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L28", 'level': 'A1', 'title': "Utiliser that", 'subtitle': "Sous-chapitre 2 • Leçon 28/50", 'explanation': "That signifie « ce/cette…-là » et désigne une chose singulière plus éloignée ou mise à distance dans le discours.", 'example': "That is your school. = C’est ton école là-bas.", 'french': "C’est ton école là-bas.", 'question': "Quel mot désigne une chose singulière éloignée ?", 'options': <String>["These", "That", "Those"], 'answer': 1, 'correction': "That est singulier ; those est pluriel.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L29", 'level': 'A1', 'title': "Utiliser these", 'subtitle': "Sous-chapitre 2 • Leçon 29/50", 'explanation': "These signifie « ces…-ci » et désigne plusieurs choses proches. Il s’emploie avec un nom pluriel ou avec are dans These are…", 'example': "These are my books. = Ce sont mes livres-ci.", 'french': "Ce sont mes livres-ci.", 'question': "Complète : These ___ my shoes.", 'options': <String>["is", "am", "are"], 'answer': 2, 'correction': "These est pluriel et s’accorde avec are.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L30", 'level': 'A1', 'title': "Utiliser those", 'subtitle': "Sous-chapitre 2 • Leçon 30/50", 'explanation': "Those désigne plusieurs choses éloignées : « ces…-là ». Ne le confonds pas avec these, qui indique la proximité.", 'example': "Those are tall buildings. = Ce sont de grands bâtiments là-bas.", 'french': "Ce sont de grands bâtiments là-bas.", 'question': "Quel mot convient pour plusieurs objets éloignés ?", 'options': <String>["This", "These", "Those"], 'answer': 2, 'correction': "Those est le démonstratif pluriel éloigné.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L31", 'level': 'A1', 'title': "Choisir this is ou these are", 'subtitle': "Sous-chapitre 2 • Leçon 31/50", 'explanation': "This is accompagne une seule chose proche ; these are accompagne plusieurs choses proches. Le verbe doit correspondre au nombre.", 'example': "This is a pen. = C’est un stylo. / These are pens. = Ce sont des stylos.", 'french': "Ce sont des stylos.", 'question': "Quelle phrase est correcte pour plusieurs livres ?", 'options': <String>["This is books.", "These are books.", "These is books."], 'answer': 1, 'correction': "These est pluriel et s’utilise avec are.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L32", 'level': 'A1', 'title': "Possessif my", 'subtitle': "Sous-chapitre 2 • Leçon 32/50", 'explanation': "My signifie mon, ma ou mes. Il se place devant le nom et ne change pas selon le genre ou le nombre du nom possédé.", 'example': "my phone = mon téléphone ; my friends = mes amis.", 'french': "mon téléphone ; my friends = mes amis.", 'question': "Comment dire « mon livre » ?", 'options': <String>["I book", "my book", "me book"], 'answer': 1, 'correction': "My est un déterminant possessif placé devant le nom.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L33", 'level': 'A1', 'title': "Possessif your", 'subtitle': "Sous-chapitre 2 • Leçon 33/50", 'explanation': "Your signifie ton, ta, tes ou votre/vos. Il ne change pas selon le genre du nom.", 'example': "your name = ton nom ; your books = tes livres.", 'french': "ton nom ; your books = tes livres.", 'question': "Complète : What is ___ name?", 'options': <String>["you", "your", "yours name"], 'answer': 1, 'correction': "Your précède le nom name.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L34", 'level': 'A1', 'title': "Possessifs his et her", 'subtitle': "Sous-chapitre 2 • Leçon 34/50", 'explanation': "His signifie son/sa/ses pour un possesseur masculin dans l’usage de base ; her pour un possesseur féminin. Le possessif s’accorde avec le possesseur, pas avec l’objet.", 'example': "His phone = son téléphone à lui ; her bag = son sac à elle.", 'french': "son téléphone à lui ; her bag = son sac à elle.", 'question': "Quel possessif convient à « son sac à elle » ?", 'options': <String>["his bag", "her bag", "she bag"], 'answer': 1, 'correction': "Her indique ici que la propriétaire est une femme ou une fille.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L35", 'level': 'A1', 'title': "Possessifs our et their", 'subtitle': "Sous-chapitre 2 • Leçon 35/50", 'explanation': "Our signifie notre/nos ; their signifie leur/leurs. Ces mots se placent avant le nom.", 'example': "our class = notre classe ; their house = leur maison.", 'french': "notre classe ; their house = leur maison.", 'question': "Comment dire « leur école » ?", 'options': <String>["our school", "their school", "they school"], 'answer': 1, 'correction': "Their est le possessif de they.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L36", 'level': 'A1', 'title': "Question What is this?", 'subtitle': "Sous-chapitre 2 • Leçon 36/50", 'explanation': "What is this? signifie « Qu’est-ce que c’est ? » ou « Qu’est-ce que ceci ? ». La réponse commence souvent par This is… ou It is….", 'example': "What is this? — It’s a key. = Qu’est-ce que c’est ? — C’est une clé.", 'french': "Qu’est-ce que c’est ? — C’est une clé.", 'question': "Quelle question demande l’identité d’un objet proche ?", 'options': <String>["Who is this?", "What is this?", "Where is this?"], 'answer': 1, 'correction': "What demande une chose ou une information ; who demande une personne.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L37", 'level': 'A1', 'title': "Répondre It is a…", 'subtitle': "Sous-chapitre 2 • Leçon 37/50", 'explanation': "Pour identifier un objet, réponds It is a… ou It’s a… suivi d’un nom singulier. Utilise an si le nom commence par un son voyelle.", 'example': "It’s a pen. = C’est un stylo ; It’s an apple. = C’est une pomme.", 'french': "C’est un stylo ; It’s an apple. = C’est une pomme.", 'question': "Complète : It’s ___ apple.", 'options': <String>["a", "an", "are"], 'answer': 1, 'correction': "Apple commence par un son voyelle ; on utilise an.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L38", 'level': 'A1', 'title': "Question What are these?", 'subtitle': "Sous-chapitre 2 • Leçon 38/50", 'explanation': "What are these? signifie « Qu’est-ce que c’est, ceux-ci ? ». These indique plusieurs objets proches, donc la réponse utilise souvent These are…", 'example': "What are these? — These are keys. = Qu’est-ce que c’est ? — Ce sont des clés.", 'french': "Qu’est-ce que c’est ? — Ce sont des clés.", 'question': "Quelle question convient à plusieurs objets proches ?", 'options': <String>["What is this?", "What are these?", "Who are this?"], 'answer': 1, 'correction': "These est pluriel ; on utilise are.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L39", 'level': 'A1', 'title': "Adjectifs avant un nom", 'subtitle': "Sous-chapitre 2 • Leçon 39/50", 'explanation': "En anglais, l’adjectif se place généralement avant le nom qu’il décrit. Il ne prend pas de -s au pluriel dans cette position.", 'example': "a small house = une petite maison ; two small houses = deux petites maisons.", 'french': "une petite maison ; two small houses = deux petites maisons.", 'question': "Quel ordre est correct ?", 'options': <String>["a car red", "a red car", "a reds car"], 'answer': 1, 'correction': "L’adjectif red précède le nom car.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L40", 'level': 'A1', 'title': "Adjectifs après to be", 'subtitle': "Sous-chapitre 2 • Leçon 40/50", 'explanation': "Un adjectif peut suivre le verbe be pour décrire le sujet. Contrairement au français, il ne change généralement pas selon le genre ou le nombre.", 'example': "The room is clean. = La pièce est propre ; They are happy. = Ils sont contents.", 'french': "La pièce est propre ; They are happy. = Ils sont contents.", 'question': "Complète : The room is ___.", 'options': <String>["clean", "cleanly room", "cleans"], 'answer': 0, 'correction': "Après is, on utilise ici l’adjectif clean.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L41", 'level': 'A1', 'title': "Construire une phrase négative", 'subtitle': "Sous-chapitre 2 • Leçon 41/50", 'explanation': "Pour nier une phrase avec be, ajoute not après am, is ou are. Pour les autres verbes au présent simple, on utilise généralement don’t/doesn’t ; ne mélange pas les deux structures.", 'example': "He is not tired. = Il n’est pas fatigué ; I don’t like tea. = Je n’aime pas le thé.", 'french': "Il n’est pas fatigué ; I don’t like tea. = Je n’aime pas le thé.", 'question': "Quelle négation est correcte avec be ?", 'options': <String>["She not is happy.", "She is not happy.", "She doesn’t happy."], 'answer': 1, 'correction': "Avec be, not vient après le verbe.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L42", 'level': 'A1', 'title': "Mots interrogatifs what et who", 'subtitle': "Sous-chapitre 2 • Leçon 42/50", 'explanation': "What demande une chose ou une information ; who demande une personne. Le mot interrogatif se place généralement au début de la question.", 'example': "What is your name? = Comment t’appelles-tu ? ; Who is she? = Qui est-elle ?", 'french': "Comment t’appelles-tu ? ; Who is she? = Qui est-elle ?", 'question': "Quel mot sert à demander l’identité d’une personne ?", 'options': <String>["What", "Who", "Where"], 'answer': 1, 'correction': "Who signifie qui.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L43", 'level': 'A1', 'title': "Poser une question avec where", 'subtitle': "Sous-chapitre 2 • Leçon 43/50", 'explanation': "Where signifie où. Avec be, place le verbe avant le sujet : Where are you? Pour une question avec un autre verbe au présent simple, la structure sera différente et sera étudiée plus tard.", 'example': "Where is my bag? = Où est mon sac ?", 'french': "Où est mon sac ?", 'question': "Quelle question signifie « Où est mon sac ? »", 'options': <String>["What is my bag?", "Where is my bag?", "Who is my bag?"], 'answer': 1, 'correction': "Where demande un lieu.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L44", 'level': 'A1', 'title': "Répondre par une phrase complète", 'subtitle': "Sous-chapitre 2 • Leçon 44/50", 'explanation': "Une phrase complète aide l’interlocuteur à comprendre le contexte. Quand on te demande où est un objet, réponds avec sujet, verbe et lieu plutôt qu’un mot isolé si tu en es capable.", 'example': "Where is the book? — It is on the table. = Où est le livre ? — Il est sur la table.", 'french': "Où est le livre ? — Il est sur la table.", 'question': "Quelle réponse est une phrase complète ?", 'options': <String>["On table.", "It is on the table.", "Table."], 'answer': 1, 'correction': "La réponse complète contient le sujet it, le verbe is et le lieu.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L45", 'level': 'A1', 'title': "Prépositions in et on", 'subtitle': "Sous-chapitre 2 • Leçon 45/50", 'explanation': "In indique souvent qu’une chose se trouve à l’intérieur ; on indique qu’elle est sur une surface. Le contexte peut modifier les usages, mais cette distinction est une bonne base.", 'example': "The keys are in the bag. = Les clés sont dans le sac ; The book is on the table. = Le livre est sur la table.", 'french': "Les clés sont dans le sac ; The book is on the table. = Le livre est sur la table.", 'question': "Le livre est posé sur la table. Quelle préposition convient ?", 'options': <String>["in", "on", "under"], 'answer': 1, 'correction': "On indique ici la surface de la table.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L46", 'level': 'A1', 'title': "Utiliser at pour l’heure", 'subtitle': "Sous-chapitre 2 • Leçon 46/50", 'explanation': "At s’utilise souvent pour indiquer une heure précise : at seven o’clock. Il sera également étudié dans les lieux et expressions figées.", 'example': "The class starts at eight. = Le cours commence à huit heures.", 'french': "Le cours commence à huit heures.", 'question': "Complète : The bus leaves ___ 7:30.", 'options': <String>["in", "on", "at"], 'answer': 2, 'correction': "At indique une heure précise.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L47", 'level': 'A1', 'title': "Distinguer question et affirmation à l’oral", 'subtitle': "Sous-chapitre 2 • Leçon 47/50", 'explanation': "À l’écrit, le point d’interrogation aide à reconnaître une question. À l’oral, l’ordre des mots et l’intonation contribuent au sens ; une question avec be commence souvent par am/is/are.", 'example': "You are ready. = Tu es prêt. / Are you ready? = Es-tu prêt ?", 'french': "Es-tu prêt ?", 'question': "Laquelle est une question avec be ?", 'options': <String>["She is happy.", "Is she happy?", "She happy is."], 'answer': 1, 'correction': "Le verbe is précède le sujet she dans la question.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L48", 'level': 'A1', 'title': "Corriger l’ordre des mots", 'subtitle': "Sous-chapitre 2 • Leçon 48/50", 'explanation': "En anglais, respecte l’ordre sujet-verbe-complément dans une affirmation. Pour les questions avec be, inverse le verbe et le sujet.", 'example': "Correct: I am happy. Incorrect: I happy am.", 'french': "Correct: I am happy. Incorrect: I happy am.", 'question': "Choisis la phrase correctement ordonnée.", 'options': <String>["I happy am.", "I am happy.", "Am happy I."], 'answer': 1, 'correction': "Le sujet I vient avant am dans une affirmation.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L49", 'level': 'A1', 'title': "Lire une mini-description", 'subtitle': "Sous-chapitre 2 • Leçon 49/50", 'explanation': "Pour comprendre une description, repère le sujet, le verbe be, les adjectifs et les noms. Lis d’abord l’idée générale, puis les détails.", 'example': "This is Ben. He is tall and friendly. = Voici Ben. Il est grand et amical.", 'french': "Voici Ben. Il est grand et amical.", 'question': "Dans la phrase, comment est Ben ?", 'options': <String>["Tall and friendly", "Short and angry", "Tired and sad"], 'answer': 0, 'correction': "Tall signifie grand et friendly signifie amical.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U02-L50", 'level': 'A1', 'title': "Révision : dix phrases correctes", 'subtitle': "Sous-chapitre 2 • Leçon 50/50", 'explanation': "Réutilise les pronoms, be, les articles, les démonstratifs, les possessifs et les prépositions dans des phrases courtes. Vérifie l’ordre des mots avant de valider.", 'example': "This is my book. It is on the table. These are my pens. They are blue. = C’est mon livre. Il est sur la table. Ce sont mes stylos. Ils sont bleus.", 'french': "C’est mon livre. Il est sur la table. Ce sont mes stylos. Ils sont bleus.", 'question': "Quelle phrase est correcte ?", 'options': <String>["These is my pen.", "This is my book.", "I am student a."], 'answer': 1, 'correction': "This est singulier ; la phrase respecte sujet + be + nom.", 'unit': 2, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L01", 'level': 'A1', 'title': "Comprendre ce qu’est un verbe", 'subtitle': "Sous-chapitre 3 • Leçon 1/50", 'explanation': "Un verbe exprime une action, un état ou un événement. Dans une phrase, il indique ce que fait le sujet ou comment il est.", 'example': "Run is a verb. = Run est un verbe.", 'french': "Run est un verbe.", 'question': "Which word is a verb?", 'options': <String>["run", "blue", "table"], 'answer': 0, 'correction': "Run exprime une action.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L02", 'level': 'A1', 'title': "Distinguer verbe et nom", 'subtitle': "Sous-chapitre 3 • Leçon 2/50", 'explanation': "Un même mot peut avoir des rôles différents. Dans « I work every day », work est un verbe ; dans « my work », work est un nom.", 'example': "I work every day. = Je travaille chaque jour.", 'french': "Je travaille chaque jour.", 'question': "In “I work”, work is…", 'options': <String>["a verb", "an adjective", "a pronoun"], 'answer': 0, 'correction': "Dans cette phrase, work exprime l’action de travailler.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L03", 'level': 'A1', 'title': "Be : am, is, are", 'subtitle': "Sous-chapitre 3 • Leçon 3/50", 'explanation': "To be signifie être. Au présent, les formes sont am avec I, is avec he/she/it et are avec you/we/they.", 'example': "I am ready. / She is happy. / They are here.", 'french': "I am ready. / She is happy. / They are here.", 'question': "Complete: We ___ ready.", 'options': <String>["is", "am", "are"], 'answer': 2, 'correction': "We est suivi de are.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L04", 'level': 'A1', 'title': "Have et has", 'subtitle': "Sous-chapitre 3 • Leçon 4/50", 'explanation': "Have signifie avoir. Utilise have avec I/you/we/they et has avec he/she/it au présent simple.", 'example': "I have a book. / She has a bike.", 'french': "I have a book. / She has a bike.", 'question': "Complete: He ___ a phone.", 'options': <String>["have", "has", "haves"], 'answer': 1, 'correction': "Avec he, on utilise has.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L05", 'level': 'A1', 'title': "Do comme verbe principal", 'subtitle': "Sous-chapitre 3 • Leçon 5/50", 'explanation': "Do signifie faire dans « do homework ». Il sert aussi d’auxiliaire dans les questions et les négations au présent simple.", 'example': "I do my homework. = Je fais mes devoirs.", 'french': "Je fais mes devoirs.", 'question': "Here, do means…", 'options': <String>["do / faire", "be / être", "eat / manger"], 'answer': 0, 'correction': "Ici, do est le verbe principal.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L06", 'level': 'A1', 'title': "Do et does pour les questions", 'subtitle': "Sous-chapitre 3 • Leçon 6/50", 'explanation': "Pour les questions au présent simple, do accompagne I/you/we/they et does accompagne he/she/it. Après does, le verbe reste à la base.", 'example': "Do you like music? / Does she play football?", 'french': "Do you like music? / Does she play football?", 'question': "___ he speak English?", 'options': <String>["Do", "Does", "Is"], 'answer': 1, 'correction': "Avec he, on utilise does dans une question au présent simple.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L07", 'level': 'A1', 'title': "Go et ses usages", 'subtitle': "Sous-chapitre 3 • Leçon 7/50", 'explanation': "Go signifie aller. On dit souvent go to school, mais les expressions go home et go there ne prennent normalement pas to.", 'example': "I go to school. / We go home.", 'french': "I go to school. / We go home.", 'question': "Choose the correct sentence.", 'options': <String>["I go to home.", "I go home.", "I goes home."], 'answer': 1, 'correction': "On dit go home sans to.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L08", 'level': 'A1', 'title': "Come dans les invitations", 'subtitle': "Sous-chapitre 3 • Leçon 8/50", 'explanation': "Come signifie venir. Come here demande à quelqu’un de venir ici ; come with me l’invite à t’accompagner.", 'example': "Come with me. = Viens avec moi.", 'french': "Viens avec moi.", 'question': "“Come with me” means…", 'options': <String>["Go without me", "Come with me", "Stay here"], 'answer': 1, 'correction': "Come signifie venir.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L09", 'level': 'A1', 'title': "Eat avec des aliments", 'subtitle': "Sous-chapitre 3 • Leçon 9/50", 'explanation': "Eat signifie manger. Au présent, he/she/it prennent eats ; le passé simple est ate.", 'example': "I eat rice. / She eats an apple.", 'french': "I eat rice. / She eats an apple.", 'question': "He ___ breakfast at seven.", 'options': <String>["eat", "eats", "eating"], 'answer': 1, 'correction': "Avec he au présent simple, on ajoute -s.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L10", 'level': 'A1', 'title': "Drink avec des boissons", 'subtitle': "Sous-chapitre 3 • Leçon 10/50", 'explanation': "Drink signifie boire. Ses formes irrégulières sont drink, drank et drunk ; mémorise-les avec des exemples.", 'example': "I drink water. / Yesterday, I drank tea.", 'french': "I drink water. / Yesterday, I drank tea.", 'question': "Past simple of drink?", 'options': <String>["drinked", "drank", "drunked"], 'answer': 1, 'correction': "Drink est irrégulier : drink–drank–drunk.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L11", 'level': 'A1', 'title': "Want pour exprimer un désir", 'subtitle': "Sous-chapitre 3 • Leçon 11/50", 'explanation': "Want signifie vouloir. Utilise want + nom ou want to + verbe de base pour parler d’un désir ou d’un projet.", 'example': "I want water. / I want to learn English.", 'french': "I want water. / I want to learn English.", 'question': "I want ___ study.", 'options': <String>["to", "for", "at"], 'answer': 0, 'correction': "Pour une action souhaitée : want to + verbe.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L12", 'level': 'A1', 'title': "Need pour exprimer un besoin", 'subtitle': "Sous-chapitre 3 • Leçon 12/50", 'explanation': "Need signifie avoir besoin de. Utilise need + nom ou need to + verbe pour exprimer une nécessité.", 'example': "I need help. / I need to study.", 'french': "I need help. / I need to study.", 'question': "How do you say « J’ai besoin d’aide »?", 'options': <String>["I need help.", "I need helping.", "I am need help."], 'answer': 0, 'correction': "Need peut être suivi directement d’un nom.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L13", 'level': 'A1', 'title': "Like pour les goûts", 'subtitle': "Sous-chapitre 3 • Leçon 13/50", 'explanation': "Like signifie aimer ou apprécier. Il peut être suivi d’un nom ou d’un verbe en -ing pour parler d’une activité.", 'example': "I like football. / I like reading.", 'french': "I like football. / I like reading.", 'question': "I ___ music.", 'options': <String>["likes", "like", "am like"], 'answer': 1, 'correction': "Avec I, on utilise like.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L14", 'level': 'A1', 'title': "Love et intensité de préférence", 'subtitle': "Sous-chapitre 3 • Leçon 14/50", 'explanation': "Love exprime un goût très fort ou l’amour. Pour une activité, on peut utiliser love + nom ou love + verbe en -ing.", 'example': "I love music. / She loves dancing.", 'french': "I love music. / She loves dancing.", 'question': "Which verb often expresses a strong preference?", 'options': <String>["love", "need", "ask"], 'answer': 0, 'correction': "Love exprime ici un goût très fort.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L15", 'level': 'A1', 'title': "Know pour les informations connues", 'subtitle': "Sous-chapitre 3 • Leçon 15/50", 'explanation': "Know signifie savoir ou connaître. Know how to signifie savoir faire quelque chose, comme I know how to swim.", 'example': "I know his name. / I know how to swim.", 'french': "I know his name. / I know how to swim.", 'question': "“I know his name” means…", 'options': <String>["I know his name", "I say his name", "I write his name"], 'answer': 0, 'correction': "Know exprime une connaissance.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L16", 'level': 'A1', 'title': "Understand dans une conversation", 'subtitle': "Sous-chapitre 3 • Leçon 16/50", 'explanation': "Understand signifie comprendre. La négation courante est I don’t understand ; au passé, on utilise understood.", 'example': "I understand the question. / I didn’t understand.", 'french': "I understand the question. / I didn’t understand.", 'question': "How do you say « Je ne comprends pas »?", 'options': <String>["I not understand.", "I don’t understand.", "I doesn’t understand."], 'answer': 1, 'correction': "Avec I, la négation au présent utilise don’t.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L17", 'level': 'A1', 'title': "Speak pour les langues", 'subtitle': "Sous-chapitre 3 • Leçon 17/50", 'explanation': "Speak signifie parler, notamment une langue. Au présent simple, he/she/it prennent speaks ; les autres sujets utilisent speak.", 'example': "I speak English. / He speaks French.", 'french': "I speak English. / He speaks French.", 'question': "She ___ Swahili.", 'options': <String>["speak", "speaks", "speaking"], 'answer': 1, 'correction': "Avec she, le verbe prend -s au présent simple.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L18", 'level': 'A1', 'title': "Say pour les paroles", 'subtitle': "Sous-chapitre 3 • Leçon 18/50", 'explanation': "Say met l’accent sur les mots prononcés : say hello, say something, say a word.", 'example': "Say hello to your teacher.", 'french': "Say hello to your teacher.", 'question': "Please ___ your name.", 'options': <String>["say", "tell me", "speak a name"], 'answer': 0, 'correction': "Say met l’accent sur les paroles prononcées.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L19", 'level': 'A1', 'title': "Tell pour transmettre une information", 'subtitle': "Sous-chapitre 3 • Leçon 19/50", 'explanation': "Tell signifie dire à quelqu’un ou raconter. Il est souvent suivi directement de la personne : tell me, tell her, tell us.", 'example': "Tell me your name. / She told me a story.", 'french': "Tell me your name. / She told me a story.", 'question': "Choose the correct expression.", 'options': <String>["tell me", "say me", "speak me"], 'answer': 0, 'correction': "Tell est suivi directement de la personne dans cette structure.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L20", 'level': 'A1', 'title': "Ask pour poser une question", 'subtitle': "Sous-chapitre 3 • Leçon 20/50", 'explanation': "Ask signifie demander ou poser une question. On dit ask a question, ask for help ou ask someone.", 'example': "I ask a question. / She asked for help.", 'french': "I ask a question. / She asked for help.", 'question': "“Ask for help” means…", 'options': <String>["give help", "ask for help", "refuse help"], 'answer': 1, 'correction': "Ask for help signifie demander de l’aide.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L21", 'level': 'A1', 'title': "Answer pour répondre", 'subtitle': "Sous-chapitre 3 • Leçon 21/50", 'explanation': "Answer signifie répondre comme verbe, et réponse comme nom. Il s’utilise souvent avec question, call ou message selon le contexte.", 'example': "Please answer the question.", 'french': "Please answer the question.", 'question': "Which verb means « répondre »?", 'options': <String>["ask", "answer", "listen"], 'answer': 1, 'correction': "Answer est le verbe répondre.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L22", 'level': 'A1', 'title': "Listen et listen to", 'subtitle': "Sous-chapitre 3 • Leçon 22/50", 'explanation': "Listen signifie écouter attentivement. Devant l’objet écouté, utilise normalement listen to ; hear signifie entendre.", 'example': "Listen to the teacher. / Listen to music.", 'french': "Listen to the teacher. / Listen to music.", 'question': "Choose the correct phrase.", 'options': <String>["listen music", "listen to music", "hear to music"], 'answer': 1, 'correction': "Listen est suivi de to devant l’objet écouté.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L23", 'level': 'A1', 'title': "Hear comme perception", 'subtitle': "Sous-chapitre 3 • Leçon 23/50", 'explanation': "Hear signifie entendre un son, parfois sans chercher à l’écouter. Listen insiste sur l’attention portée au son.", 'example': "I can hear music. = J’entends de la musique.", 'french': "J’entends de la musique.", 'question': "You hear a sound unexpectedly. Use…", 'options': <String>["hear", "listen to", "speak"], 'answer': 0, 'correction': "Hear met l’accent sur la perception du son.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L24", 'level': 'A1', 'title': "See et look at", 'subtitle': "Sous-chapitre 3 • Leçon 24/50", 'explanation': "See signifie voir ; look at signifie regarder volontairement vers quelque chose. Look at est suivi de l’objet regardé.", 'example': "I can see a bird. / Look at this picture.", 'french': "I can see a bird. / Look at this picture.", 'question': "Tell a friend to look at a photo.", 'options': <String>["See this picture!", "Look at this picture!", "Look this picture!"], 'answer': 1, 'correction': "L’expression correcte est look at + objet.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L25", 'level': 'A1', 'title': "Watch pour regarder un contenu", 'subtitle': "Sous-chapitre 3 • Leçon 25/50", 'explanation': "Watch s’utilise souvent pour regarder un contenu qui dure ou bouge, comme un film, une vidéo ou un match.", 'example': "I watch a video. / We watch football.", 'french': "I watch a video. / We watch football.", 'question': "Which verb fits watching a movie?", 'options': <String>["watch", "hear", "ask"], 'answer': 0, 'correction': "Watch s’utilise avec films, vidéos et matchs.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L26", 'level': 'A1', 'title': "Read avec livres et messages", 'subtitle': "Sous-chapitre 3 • Leçon 26/50", 'explanation': "Read signifie lire. Son orthographe est identique au présent et au passé, mais sa prononciation change au passé.", 'example': "I read books. / Yesterday, I read a story.", 'french': "I read books. / Yesterday, I read a story.", 'question': "Which verb means « lire »?", 'options': <String>["write", "read", "ride"], 'answer': 1, 'correction': "Read signifie lire ; write signifie écrire.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L27", 'level': 'A1', 'title': "Write avec mots et phrases", 'subtitle': "Sous-chapitre 3 • Leçon 27/50", 'explanation': "Write signifie écrire. Ses formes sont write, wrote et written ; apprends-les en phrases.", 'example': "Write your name. / I wrote a message.", 'french': "Write your name. / I wrote a message.", 'question': "Past simple of write?", 'options': <String>["writed", "wrote", "written"], 'answer': 1, 'correction': "Write est irrégulier : write–wrote–written.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L28", 'level': 'A1', 'title': "Learn et study : différence", 'subtitle': "Sous-chapitre 3 • Leçon 28/50", 'explanation': "Learn signifie apprendre ou acquérir une compétence ; study signifie étudier une matière ou travailler pour apprendre.", 'example': "I study English. / I learn new words.", 'french': "I study English. / I learn new words.", 'question': "Which verb fits a school subject?", 'options': <String>["study", "sleep", "drink"], 'answer': 0, 'correction': "Study s’utilise souvent avec une matière scolaire.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L29", 'level': 'A1', 'title': "Teach avec l’école", 'subtitle': "Sous-chapitre 3 • Leçon 29/50", 'explanation': "Teach signifie enseigner. Ses formes irrégulières sont teach, taught et taught ; teacher désigne la personne qui enseigne.", 'example': "She teaches English. / He taught me.", 'french': "She teaches English. / He taught me.", 'question': "Past simple of teach?", 'options': <String>["teached", "taught", "teaching"], 'answer': 1, 'correction': "Teach est irrégulier : teach–taught–taught.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L30", 'level': 'A1', 'title': "Work avec les métiers", 'subtitle': "Sous-chapitre 3 • Leçon 30/50", 'explanation': "Work signifie travailler ou travail selon la phrase. Pour un métier, on peut dire work as a teacher ou work as a nurse.", 'example': "I work at a school. / She works as a nurse.", 'french': "I work at a school. / She works as a nurse.", 'question': "Which sentence describes a job?", 'options': <String>["She works as a nurse.", "She is work nurse.", "She work nurse yesterday."], 'answer': 0, 'correction': "Avec she au présent simple, work prend -s.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L31", 'level': 'A1', 'title': "Live pour le lieu d’habitation", 'subtitle': "Sous-chapitre 3 • Leçon 31/50", 'explanation': "Live signifie habiter ou vivre. Utilise généralement live in avec une ville ou un pays.", 'example': "I live in a city. / They live in Canada.", 'french': "I live in a city. / They live in Canada.", 'question': "Live ___ Canada.", 'options': <String>["at", "in", "on"], 'answer': 1, 'correction': "On utilise généralement in avec une ville ou un pays.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L32", 'level': 'A1', 'title': "Stay pour une durée ou un séjour", 'subtitle': "Sous-chapitre 3 • Leçon 32/50", 'explanation': "Stay signifie rester ou séjourner, souvent temporairement. Live décrit plutôt le lieu où l’on habite habituellement.", 'example': "I’m staying with my aunt. / Stay here, please.", 'french': "I’m staying with my aunt. / Stay here, please.", 'question': "Which verb fits a temporary visit?", 'options': <String>["stay", "know", "sleep"], 'answer': 0, 'correction': "Stay met l’accent sur la durée ou la situation temporaire.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L33", 'level': 'A1', 'title': "Make dans les expressions simples", 'subtitle': "Sous-chapitre 3 • Leçon 33/50", 'explanation': "Make signifie fabriquer, créer ou produire. Apprends les expressions make breakfast, make a cake et make a mistake.", 'example': "make breakfast; make a cake; make a mistake.", 'french': "make breakfast; make a cake; make a mistake.", 'question': "Which phrase means « faire une erreur »?", 'options': <String>["make a mistake", "do a mistake", "make mistake a"], 'answer': 0, 'correction': "L’expression habituelle est make a mistake.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L34", 'level': 'A1', 'title': "Take dans les usages courants", 'subtitle': "Sous-chapitre 3 • Leçon 34/50", 'explanation': "Take signifie prendre et apparaît dans des expressions comme take a seat, take a photo et take a bus.", 'example': "Take a seat. / Take a photo.", 'french': "Take a seat. / Take a photo.", 'question': "How do you say « prendre une photo »?", 'options': <String>["do a photo", "take a photo", "make photo always"], 'answer': 1, 'correction': "Take a photo est l’expression courante.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L35", 'level': 'A1', 'title': "Give et receive", 'subtitle': "Sous-chapitre 3 • Leçon 35/50", 'explanation': "Give signifie donner ; receive signifie recevoir. Ces verbes décrivent les deux côtés d’un échange.", 'example': "Give me the book. / I received a message.", 'french': "Give me the book. / I received a message.", 'question': "Which verb means « recevoir »?", 'options': <String>["give", "receive", "take"], 'answer': 1, 'correction': "Receive signifie recevoir.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L36", 'level': 'A1', 'title': "Get dans les phrases fréquentes", 'subtitle': "Sous-chapitre 3 • Leçon 36/50", 'explanation': "Get a plusieurs sens selon le contexte : obtenir, recevoir, devenir ou arriver. Apprends-le dans des expressions complètes.", 'example': "I get a message. / I get tired.", 'french': "I get a message. / I get tired.", 'question': "In “I get a message”, get means…", 'options': <String>["receive", "sleep", "teach"], 'answer': 0, 'correction': "Le sens de get dépend de l’expression ; ici, il signifie recevoir.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L37", 'level': 'A1', 'title': "Put et place", 'subtitle': "Sous-chapitre 3 • Leçon 37/50", 'explanation': "Put signifie mettre ou poser ; place signifie placer. Put est très courant dans les instructions quotidiennes.", 'example': "Put the book on the table.", 'french': "Put the book on the table.", 'question': "Which verb fits a simple instruction to place something?", 'options': <String>["put", "sleep", "know"], 'answer': 0, 'correction': "Put est très courant pour dire mettre ou poser.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L38", 'level': 'A1', 'title': "Open et close", 'subtitle': "Sous-chapitre 3 • Leçon 38/50", 'explanation': "Open signifie ouvrir ; close signifie fermer. On les utilise avec des portes, fenêtres, livres et applications.", 'example': "Open the door. / Close your book.", 'french': "Open the door. / Close your book.", 'question': "Opposite of open?", 'options': <String>["close", "start", "read"], 'answer': 0, 'correction': "Close signifie fermer.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L39", 'level': 'A1', 'title': "Start et finish", 'subtitle': "Sous-chapitre 3 • Leçon 39/50", 'explanation': "Start signifie commencer ; finish signifie finir ou terminer. Ils peuvent accompagner une activité ou un objet.", 'example': "The class starts at eight. / I finish my homework.", 'french': "The class starts at eight. / I finish my homework.", 'question': "Which verb means « terminer »?", 'options': <String>["start", "finish", "come"], 'answer': 1, 'correction': "Finish signifie finir ou terminer.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L40", 'level': 'A1', 'title': "Play avec jeux et sports", 'subtitle': "Sous-chapitre 3 • Leçon 40/50", 'explanation': "Play signifie jouer. On l’utilise avec de nombreux sports et jeux, par exemple play football et play chess.", 'example': "I play football. / They play chess.", 'french': "I play football. / They play chess.", 'question': "Choose the usual phrase.", 'options': <String>["play football", "do football", "make football"], 'answer': 0, 'correction': "Play s’utilise avec football et de nombreux jeux.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L41", 'level': 'A1', 'title': "Run et walk", 'subtitle': "Sous-chapitre 3 • Leçon 41/50", 'explanation': "Run signifie courir ; walk signifie marcher. Au présent simple, he/she/it prennent runs et walks.", 'example': "I run fast. / I walk to school.", 'french': "I run fast. / I walk to school.", 'question': "Which verb means « marcher »?", 'options': <String>["run", "walk", "sleep"], 'answer': 1, 'correction': "Walk signifie marcher.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L42", 'level': 'A1', 'title': "Sit et stand", 'subtitle': "Sous-chapitre 3 • Leçon 42/50", 'explanation': "Sit signifie s’asseoir ou être assis ; stand signifie se tenir debout. Leurs passés sont sat et stood.", 'example': "Sit down, please. / Stand here.", 'french': "Sit down, please. / Stand here.", 'question': "Which verb means « se tenir debout »?", 'options': <String>["sit", "stand", "sleep"], 'answer': 1, 'correction': "Stand signifie se tenir debout.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L43", 'level': 'A1', 'title': "Sleep et wake up", 'subtitle': "Sous-chapitre 3 • Leçon 43/50", 'explanation': "Sleep signifie dormir ; wake up signifie se réveiller. Get up signifie se lever du lit, une action différente.", 'example': "I sleep at night. / I wake up at six.", 'french': "I sleep at night. / I wake up at six.", 'question': "Wake up means…", 'options': <String>["fall asleep", "wake from sleep", "go to bed"], 'answer': 1, 'correction': "Wake up signifie se réveiller ; get up signifie se lever.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L44", 'level': 'A1', 'title': "Get up et go to bed", 'subtitle': "Sous-chapitre 3 • Leçon 44/50", 'explanation': "Get up signifie se lever du lit ; go to bed signifie aller se coucher. Fall asleep signifie s’endormir.", 'example': "I get up at seven. / I go to bed at ten.", 'french': "I get up at seven. / I go to bed at ten.", 'question': "Which phrase means « aller se coucher »?", 'options': <String>["get up", "go to bed", "wake up"], 'answer': 1, 'correction': "Go to bed signifie aller au lit pour dormir.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L45", 'level': 'A1', 'title': "Buy et pay", 'subtitle': "Sous-chapitre 3 • Leçon 45/50", 'explanation': "Buy signifie acheter ; pay signifie payer. Le passé de buy est bought et celui de pay est paid.", 'example': "I buy bread. / I paid yesterday.", 'french': "I buy bread. / I paid yesterday.", 'question': "Past simple of buy?", 'options': <String>["buyed", "bought", "buying"], 'answer': 1, 'correction': "Buy est irrégulier : buy–bought–bought.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L46", 'level': 'A1', 'title': "Help et use", 'subtitle': "Sous-chapitre 3 • Leçon 46/50", 'explanation': "Help signifie aider ; use signifie utiliser. Help peut être suivi d’une personne ; use est suivi d’un objet ou d’un outil.", 'example': "Can you help me? / I use my phone.", 'french': "Can you help me? / I use my phone.", 'question': "Which verb means « utiliser »?", 'options': <String>["help", "use", "eat"], 'answer': 1, 'correction': "Use signifie utiliser.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L47", 'level': 'A1', 'title': "Call et text", 'subtitle': "Sous-chapitre 3 • Leçon 47/50", 'explanation': "Call signifie appeler, souvent au téléphone ; text signifie envoyer un message écrit ou un SMS.", 'example': "I’ll call you. / Text me later.", 'french': "I’ll call you. / Text me later.", 'question': "Which verb fits sending an SMS?", 'options': <String>["text", "call", "sleep"], 'answer': 0, 'correction': "Text peut signifier envoyer un message écrit.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L48", 'level': 'A1', 'title': "Think et feel", 'subtitle': "Sous-chapitre 3 • Leçon 48/50", 'explanation': "Think signifie penser ; feel signifie ressentir ou se sentir. Think introduit souvent une opinion ; feel décrit une sensation ou un état.", 'example': "I think it’s good. / I feel happy.", 'french': "I think it’s good. / I feel happy.", 'question': "Which verb introduces an opinion?", 'options': <String>["think", "feel", "sleep"], 'answer': 0, 'correction': "Think introduit souvent une pensée ou une opinion.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L49", 'level': 'A1', 'title': "Try et practise", 'subtitle': "Sous-chapitre 3 • Leçon 49/50", 'explanation': "Try signifie essayer. Practice est l’orthographe américaine du verbe s’entraîner ; try again encourage à faire une nouvelle tentative.", 'example': "Try again. / Practice English every day.", 'french': "Try again. / Practice English every day.", 'question': "“Try again” means…", 'options': <String>["try once only", "try one more time", "stop now"], 'answer': 1, 'correction': "Try again encourage à faire une nouvelle tentative.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U03-L50", 'level': 'A1', 'title': "Révision : base verbale et phrase complète", 'subtitle': "Sous-chapitre 3 • Leçon 50/50", 'explanation': "Révise les verbes en phrases complètes. Vérifie le sujet, le temps et les mots qui accompagnent le verbe ; ne mémorise pas uniquement une traduction isolée.", 'example': "Which sentence is correct?", 'french': "Which sentence is correct?", 'question': "She speak English.", 'options': <String>["She speak English.", "I want to learn English.", "He have a book."], 'answer': 1, 'correction': "Écris trois phrases avec des verbes différents.", 'unit': 3, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L01", 'level': 'A1', 'title': "Mother et father", 'subtitle': "Sous-chapitre 4 • Leçon 1/50", 'explanation': "Mother = mère ; father = père. Ce sont des noms de membres de la famille.", 'example': "My mother is kind. = Ma mère est gentille.", 'french': "Ma mère est gentille.", 'question': "Que signifie father ?", 'options': <String>["Père", "Frère", "Oncle"], 'answer': 0, 'correction': "Father signifie père.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L02", 'level': 'A1', 'title': "Parents et children", 'subtitle': "Sous-chapitre 4 • Leçon 2/50", 'explanation': "Parents signifie parents ; children signifie enfants. Child est le singulier, children le pluriel irrégulier.", 'example': "The parents have two children. = Les parents ont deux enfants.", 'french': "Les parents ont deux enfants.", 'question': "Quel mot désigne plusieurs enfants en anglais ?", 'options': <String>["childs", "children", "childes"], 'answer': 1, 'correction': "Children est le pluriel irrégulier de child.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L03", 'level': 'A1', 'title': "Sister et brother", 'subtitle': "Sous-chapitre 4 • Leçon 3/50", 'explanation': "Sister signifie sœur ; brother signifie frère. Ces mots permettent de présenter les membres de sa famille.", 'example': "I have one sister and one brother. = J’ai une sœur et un frère.", 'french': "J’ai une sœur et un frère.", 'question': "Brother signifie…", 'options': <String>["Sœur", "Frère", "Cousin"], 'answer': 1, 'correction': "Brother signifie frère.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L04", 'level': 'A1', 'title': "Grandmother et grandfather", 'subtitle': "Sous-chapitre 4 • Leçon 4/50", 'explanation': "Grandmother signifie grand-mère ; grandfather signifie grand-père. Grandma et grandpa sont des formes familières.", 'example': "My grandfather is funny. = Mon grand-père est drôle.", 'french': "Mon grand-père est drôle.", 'question': "Grandmother signifie…", 'options': <String>["Grand-mère", "Tante", "Mère"], 'answer': 0, 'correction': "Grandmother désigne la mère de ton père ou de ta mère.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L05", 'level': 'A1', 'title': "Aunt et uncle", 'subtitle': "Sous-chapitre 4 • Leçon 5/50", 'explanation': "Aunt signifie tante ; uncle signifie oncle. Le mot cousin peut désigner un cousin ou une cousine.", 'example': "My aunt lives in a city. = Ma tante habite dans une ville.", 'french': "Ma tante habite dans une ville.", 'question': "Quel mot signifie tante ?", 'options': <String>["aunt", "uncle", "cousin"], 'answer': 0, 'correction': "Aunt signifie tante.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L06", 'level': 'A1', 'title': "Cousin et relatives", 'subtitle': "Sous-chapitre 4 • Leçon 6/50", 'explanation': "Cousin signifie cousin ou cousine. Relatives signifie parents au sens de membres de la famille élargie.", 'example': "My cousins are friendly. = Mes cousins sont amicaux.", 'french': "Mes cousins sont amicaux.", 'question': "Relatives signifie ici…", 'options': <String>["Voisins", "Membres de la famille", "Professeurs"], 'answer': 1, 'correction': "Relatives désigne les membres de la famille.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L07", 'level': 'A1', 'title': "Présenter sa famille", 'subtitle': "Sous-chapitre 4 • Leçon 7/50", 'explanation': "Utilise This is my… pour présenter un membre de la famille. Utilise he/she pour continuer à parler de la personne.", 'example': "This is my sister. She is funny. = Voici ma sœur. Elle est drôle.", 'french': "Voici ma sœur. Elle est drôle.", 'question': "Complète : This is my ___.", 'options': <String>["sister", "are sister", "my is sister"], 'answer': 0, 'correction': "This is my + nom présente une personne.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L08", 'level': 'A1', 'title': "Parler d’un friend", 'subtitle': "Sous-chapitre 4 • Leçon 8/50", 'explanation': "Friend signifie ami ou amie. Pour parler de plusieurs amis, ajoute généralement -s : friends.", 'example': "He is my friend. = C’est mon ami.", 'french': "C’est mon ami.", 'question': "Friend signifie…", 'options': <String>["Ami", "Enfant", "Voisinage"], 'answer': 0, 'correction': "Friend désigne une personne avec laquelle on est ami.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L09", 'level': 'A1', 'title': "Parler d’un best friend", 'subtitle': "Sous-chapitre 4 • Leçon 9/50", 'explanation': "Best friend signifie meilleur ami ou meilleure amie. Best est la forme superlative de good dans cette expression.", 'example': "Mia is my best friend. = Mia est ma meilleure amie.", 'french': "Mia est ma meilleure amie.", 'question': "Best friend signifie…", 'options': <String>["Un collègue", "Un meilleur ami", "Un professeur"], 'answer': 1, 'correction': "Best friend désigne la personne que l’on considère comme son meilleur ami.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L10", 'level': 'A1', 'title': "Man, woman, boy et girl", 'subtitle': "Sous-chapitre 4 • Leçon 10/50", 'explanation': "Man signifie homme ; woman signifie femme ; boy signifie garçon ; girl signifie fille. Au pluriel : men, women, boys, girls.", 'example': "The girl is happy. = La fille est contente.", 'french': "La fille est contente.", 'question': "Quel mot signifie garçon ?", 'options': <String>["boy", "woman", "man"], 'answer': 0, 'correction': "Boy signifie garçon.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L11", 'level': 'A1', 'title': "Baby et adult", 'subtitle': "Sous-chapitre 4 • Leçon 11/50", 'explanation': "Baby signifie bébé ; adult signifie adulte. Ce sont des mots utiles pour parler de l’âge et des étapes de la vie.", 'example': "The baby is sleeping. = Le bébé dort.", 'french': "Le bébé dort.", 'question': "Adult signifie…", 'options': <String>["Bébé", "Adulte", "Adolescent uniquement"], 'answer': 1, 'correction': "Adult désigne une personne adulte.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L12", 'level': 'A1', 'title': "Person et people", 'subtitle': "Sous-chapitre 4 • Leçon 12/50", 'explanation': "Person signifie personne au singulier ; people est le pluriel courant. Persons existe dans des contextes officiels, mais people est le plus naturel au quotidien.", 'example': "One person, two people. = Une personne, deux personnes.", 'french': "Une personne, deux personnes.", 'question': "Quel est le pluriel courant de person ?", 'options': <String>["persons toujours", "people", "persones"], 'answer': 1, 'correction': "People est le pluriel courant de person.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L13", 'level': 'A1', 'title': "Question Who is he?", 'subtitle': "Sous-chapitre 4 • Leçon 13/50", 'explanation': "Who signifie qui. Who is he? demande l’identité d’un homme ou d’un garçon dans le contexte.", 'example': "Who is he? He is my brother. = Qui est-il ? C’est mon frère.", 'french': "Qui est-il ? C’est mon frère.", 'question': "Quelle question signifie « Qui est-il ? »", 'options': <String>["Who is he?", "What is he?", "Where is he?"], 'answer': 0, 'correction': "Who demande l’identité d’une personne.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L14", 'level': 'A1', 'title': "Question Who is she?", 'subtitle': "Sous-chapitre 4 • Leçon 14/50", 'explanation': "Who is she? demande l’identité d’une femme ou d’une fille dans le contexte. La réponse peut commencer par She is…", 'example': "Who is she? She is my teacher. = Qui est-elle ? C’est ma professeure.", 'french': "Qui est-elle ? C’est ma professeure.", 'question': "Comment demander « Qui est-elle ? »", 'options': <String>["Who is she?", "Where she?", "What she is?"], 'answer': 0, 'correction': "La structure est Who + is + she.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L15", 'level': 'A1', 'title': "Décrire avec tall et short", 'subtitle': "Sous-chapitre 4 • Leçon 15/50", 'explanation': "Tall signifie grand en taille ; short signifie petit ou de petite taille. Le contexte aide à comprendre le sens.", 'example': "He is tall. = Il est grand. / She is short. = Elle est petite.", 'french': "Elle est petite.", 'question': "Quel est le contraire de tall ?", 'options': <String>["long", "short", "wide"], 'answer': 1, 'correction': "Short est l’opposé de tall pour la taille d’une personne.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L16", 'level': 'A1', 'title': "Décrire avec young et old", 'subtitle': "Sous-chapitre 4 • Leçon 16/50", 'explanation': "Young signifie jeune ; old signifie vieux/âgé pour une personne ou ancien pour un objet. Le contexte est important.", 'example': "The boy is young. = Le garçon est jeune.", 'french': "Le garçon est jeune.", 'question': "Young signifie…", 'options': <String>["Jeune", "Grand", "Rapide"], 'answer': 0, 'correction': "Young décrit un âge jeune.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L17", 'level': 'A1', 'title': "Décrire avec kind et friendly", 'subtitle': "Sous-chapitre 4 • Leçon 17/50", 'explanation': "Kind signifie gentil ou bienveillant ; friendly signifie amical. Ces adjectifs décrivent le comportement d’une personne.", 'example': "My teacher is kind. = Mon professeur est gentil.", 'french': "Mon professeur est gentil.", 'question': "Friendly signifie…", 'options': <String>["Amical", "Cher", "Fatigué"], 'answer': 0, 'correction': "Friendly décrit quelqu’un de sympathique ou amical.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L18", 'level': 'A1', 'title': "Décrire avec happy et sad", 'subtitle': "Sous-chapitre 4 • Leçon 18/50", 'explanation': "Happy signifie heureux ou content ; sad signifie triste. Ces adjectifs peuvent suivre le verbe be.", 'example': "I’m happy. = Je suis content. / He is sad. = Il est triste.", 'french': "Il est triste.", 'question': "Quel est le contraire de happy ?", 'options': <String>["sad", "tall", "kind"], 'answer': 0, 'correction': "Sad signifie triste.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L19", 'level': 'A1', 'title': "Décrire avec tired et excited", 'subtitle': "Sous-chapitre 4 • Leçon 19/50", 'explanation': "Tired signifie fatigué ; excited signifie enthousiaste ou très content à l’idée de quelque chose. Ces adjectifs décrivent un état.", 'example': "I’m tired after school. = Je suis fatigué après l’école.", 'french': "Je suis fatigué après l’école.", 'question': "Excited signifie…", 'options': <String>["En colère", "Enthousiaste", "Endormi uniquement"], 'answer': 1, 'correction': "Excited décrit un état d’enthousiasme.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L20", 'level': 'A1', 'title': "Décrire avec quiet et funny", 'subtitle': "Sous-chapitre 4 • Leçon 20/50", 'explanation': "Quiet signifie calme ou silencieux ; funny signifie drôle. Funny peut décrire une personne ou une situation amusante.", 'example': "My brother is funny. = Mon frère est drôle.", 'french': "Mon frère est drôle.", 'question': "Funny signifie…", 'options': <String>["Drôle", "Triste", "Silencieux"], 'answer': 0, 'correction': "Funny signifie drôle ; quiet signifie calme ou silencieux.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L21", 'level': 'A1', 'title': "Couleurs principales", 'subtitle': "Sous-chapitre 4 • Leçon 21/50", 'explanation': "Apprends les couleurs courantes : red, blue, yellow, green, black, white, orange, pink, purple et brown.", 'example': "The bag is blue. = Le sac est bleu.", 'french': "Le sac est bleu.", 'question': "Quelle couleur signifie green ?", 'options': <String>["Vert", "Gris", "Rouge"], 'answer': 0, 'correction': "Green signifie vert.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L22", 'level': 'A1', 'title': "Light blue et dark blue", 'subtitle': "Sous-chapitre 4 • Leçon 22/50", 'explanation': "Light blue signifie bleu clair ; dark blue signifie bleu foncé. Light et dark peuvent précéder plusieurs couleurs.", 'example': "My shirt is light blue. = Ma chemise est bleu clair.", 'french': "Ma chemise est bleu clair.", 'question': "Dark blue signifie…", 'options': <String>["Bleu clair", "Bleu foncé", "Vert foncé"], 'answer': 1, 'correction': "Dark signifie foncé dans ce contexte.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L23", 'level': 'A1', 'title': "Décrire la couleur d’un objet", 'subtitle': "Sous-chapitre 4 • Leçon 23/50", 'explanation': "Pour indiquer une couleur, utilise sujet + be + couleur ou couleur + nom : The car is red ; a red car.", 'example': "The car is red. = La voiture est rouge.", 'french': "La voiture est rouge.", 'question': "Comment dire que la voiture est rouge ?", 'options': <String>["The red is car.", "The car is red.", "The car red are."], 'answer': 1, 'correction': "L’adjectif couleur peut suivre be ou précéder le nom.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L24", 'level': 'A1', 'title': "Formes simples", 'subtitle': "Sous-chapitre 4 • Leçon 24/50", 'explanation': "Les formes courantes sont circle (cercle), square (carré), triangle (triangle) et rectangle (rectangle).", 'example': "The sign is a circle. = Le panneau est un cercle.", 'french': "Le panneau est un cercle.", 'question': "Triangle signifie…", 'options': <String>["Cercle", "Triangle", "Carré"], 'answer': 1, 'correction': "Triangle désigne une forme à trois côtés.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L25", 'level': 'A1', 'title': "Tailles small, medium et large", 'subtitle': "Sous-chapitre 4 • Leçon 25/50", 'explanation': "Small signifie petit ; medium signifie moyen ; large signifie grand ou large selon l’objet. Ces mots décrivent la taille.", 'example': "I need a small shirt. = J’ai besoin d’un petit T-shirt.", 'french': "J’ai besoin d’un petit T-shirt.", 'question': "Medium signifie…", 'options': <String>["Petit", "Moyen", "Très grand"], 'answer': 1, 'correction': "Medium signifie moyen.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L26", 'level': 'A1', 'title': "Décrire la taille d’un objet", 'subtitle': "Sous-chapitre 4 • Leçon 26/50", 'explanation': "Pour décrire un objet, place l’adjectif avant le nom ou après be. L’adjectif ne prend pas de -s au pluriel dans ces exemples.", 'example': "a large bag = un grand sac ; The bags are large. = Les sacs sont grands.", 'french': "un grand sac ; The bags are large. = Les sacs sont grands.", 'question': "Comment décrire correctement deux grands sacs ?", 'options': <String>["two larges bags", "two large bags", "two bag large"], 'answer': 1, 'correction': "L’adjectif large reste invariable.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L27", 'level': 'A1', 'title': "Objets de la classe", 'subtitle': "Sous-chapitre 4 • Leçon 27/50", 'explanation': "Les objets courants comprennent book, pen, pencil, notebook, desk, chair et board. Apprends-les avec une image ou en les montrant autour de toi.", 'example': "This is a pencil. = C’est un crayon.", 'french': "C’est un crayon.", 'question': "Pencil signifie…", 'options': <String>["Stylo", "Crayon", "Cahier"], 'answer': 1, 'correction': "Pencil signifie crayon.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L28", 'level': 'A1', 'title': "Objets portables du quotidien", 'subtitle': "Sous-chapitre 4 • Leçon 28/50", 'explanation': "Les objets personnels incluent phone, keys, wallet, bag et bottle. Utilise my/your pour indiquer à qui ils appartiennent.", 'example': "My phone is here. = Mon téléphone est ici.", 'french': "Mon téléphone est ici.", 'question': "Keys signifie…", 'options': <String>["Clés", "Chaussures", "Livres"], 'answer': 0, 'correction': "Keys est le pluriel de key.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L29", 'level': 'A1', 'title': "Objets dans un sac", 'subtitle': "Sous-chapitre 4 • Leçon 29/50", 'explanation': "Pour décrire ce qu’il y a dans un sac, utilise There is pour un élément et There are pour plusieurs ; cette structure sera approfondie plus tard.", 'example': "There is a book in my bag. = Il y a un livre dans mon sac.", 'french': "Il y a un livre dans mon sac.", 'question': "Quel objet peut-on trouver in a bag ?", 'options': <String>["book", "sky", "mountain"], 'answer': 0, 'correction': "Book signifie livre.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L30", 'level': 'A1', 'title': "Dire This is my phone", 'subtitle': "Sous-chapitre 4 • Leçon 30/50", 'explanation': "This is my… présente un objet proche et indique qu’il appartient au locuteur avec my.", 'example': "This is my phone. = Voici mon téléphone.", 'french': "Voici mon téléphone.", 'question': "Que signifie This is my phone ?", 'options': <String>["Voici mon téléphone", "Où est mon téléphone ?", "Je téléphone maintenant"], 'answer': 0, 'correction': "This is présente l’objet ; my indique la possession.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L31", 'level': 'A1', 'title': "Vêtements de base", 'subtitle': "Sous-chapitre 4 • Leçon 31/50", 'explanation': "Les vêtements courants incluent shirt, T-shirt, trousers, jeans, dress, skirt et jacket.", 'example': "I have a blue jacket. = J’ai une veste bleue.", 'french': "J’ai une veste bleue.", 'question': "Jacket signifie…", 'options': <String>["Veste", "Chapeau", "Chaussette"], 'answer': 0, 'correction': "Jacket désigne une veste.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L32", 'level': 'A1', 'title': "Shirt et T-shirt", 'subtitle': "Sous-chapitre 4 • Leçon 32/50", 'explanation': "Shirt désigne une chemise ; T-shirt désigne un tee-shirt. En anglais américain, shirt peut être utilisé plus largement, mais ces distinctions sont utiles aux débutants.", 'example': "He is wearing a white shirt. = Il porte une chemise blanche.", 'french': "Il porte une chemise blanche.", 'question': "T-shirt signifie…", 'options': <String>["Tee-shirt", "Pantalon", "Chaussure"], 'answer': 0, 'correction': "T-shirt est un vêtement à manches courtes en général.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L33", 'level': 'A1', 'title': "Trousers et jeans", 'subtitle': "Sous-chapitre 4 • Leçon 33/50", 'explanation': "Trousers signifie pantalon en anglais britannique ; pants est le mot habituel en anglais américain. Jeans désigne un jean.", 'example': "I’m wearing jeans. = Je porte un jean.", 'french': "Je porte un jean.", 'question': "Quel mot est très courant en anglais américain pour « pantalon » ?", 'options': <String>["pants", "trousers only", "shorts always"], 'answer': 0, 'correction': "Pants est le mot américain courant pour pantalon.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L34", 'level': 'A1', 'title': "Shoes et socks", 'subtitle': "Sous-chapitre 4 • Leçon 34/50", 'explanation': "Shoes signifie chaussures ; socks signifie chaussettes. Ces noms sont souvent utilisés au pluriel en anglais.", 'example': "My shoes are black. = Mes chaussures sont noires.", 'french': "Mes chaussures sont noires.", 'question': "Socks signifie…", 'options': <String>["Chaussettes", "Chaussures", "Gants"], 'answer': 0, 'correction': "Socks signifie chaussettes.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L35", 'level': 'A1', 'title': "Jacket et coat", 'subtitle': "Sous-chapitre 4 • Leçon 35/50", 'explanation': "Jacket désigne une veste ; coat désigne généralement un manteau plus couvrant. L’usage dépend du vêtement et de la météo.", 'example': "Wear your coat. = Mets ton manteau.", 'french': "Mets ton manteau.", 'question': "Coat signifie le plus souvent…", 'options': <String>["Manteau", "Chemise", "Short"], 'answer': 0, 'correction': "Coat est un manteau.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L36", 'level': 'A1', 'title': "Dire I’m wearing", 'subtitle': "Sous-chapitre 4 • Leçon 36/50", 'explanation': "I’m wearing signifie « je porte » un vêtement maintenant. La structure est be + wearing, forme en -ing de wear.", 'example': "I’m wearing a blue shirt. = Je porte une chemise bleue.", 'french': "Je porte une chemise bleue.", 'question': "Complète : I’m ___ a jacket.", 'options': <String>["wear", "wearing", "wore"], 'answer': 1, 'correction': "Après am, la forme continue est wearing.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L37", 'level': 'A1', 'title': "Décrire les cheveux", 'subtitle': "Sous-chapitre 4 • Leçon 37/50", 'explanation': "Pour décrire les cheveux, on peut dire long hair, short hair, curly hair ou straight hair. Hair est généralement indénombrable dans cet usage.", 'example': "She has curly hair. = Elle a les cheveux bouclés.", 'french': "Elle a les cheveux bouclés.", 'question': "Curly hair signifie…", 'options': <String>["Cheveux bouclés", "Cheveux courts", "Cheveux gris"], 'answer': 0, 'correction': "Curly signifie bouclé.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L38", 'level': 'A1', 'title': "Parties du visage", 'subtitle': "Sous-chapitre 4 • Leçon 38/50", 'explanation': "Les parties du visage incluent eyes, ears, nose, mouth et teeth. Les images aident à mémoriser le vocabulaire.", 'example': "He has brown eyes. = Il a les yeux marron.", 'french': "Il a les yeux marron.", 'question': "Nose signifie…", 'options': <String>["Nez", "Oreille", "Bouche"], 'answer': 0, 'correction': "Nose signifie nez.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L39", 'level': 'A1', 'title': "Head, hand et foot", 'subtitle': "Sous-chapitre 4 • Leçon 39/50", 'explanation': "Head signifie tête ; hand signifie main ; foot signifie pied. Au pluriel, foot devient feet et tooth devient teeth.", 'example': "My foot hurts. = Mon pied me fait mal. / Wash your hands. = Lave-toi les mains.", 'french': "Lave-toi les mains.", 'question': "Quel est le pluriel de foot ?", 'options': <String>["foots", "feet", "footes"], 'answer': 1, 'correction': "Foot est irrégulier : foot–feet.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L40", 'level': 'A1', 'title': "Parties du corps avec images", 'subtitle': "Sous-chapitre 4 • Leçon 40/50", 'explanation': "Associe les mots aux parties du corps : arm, leg, knee, shoulder, back et stomach. Les illustrations doivent être anatomiquement claires et adaptées aux débutants.", 'example': "My arm hurts. = J’ai mal au bras.", 'french': "J’ai mal au bras.", 'question': "Leg signifie…", 'options': <String>["Jambe", "Bras", "Tête"], 'answer': 0, 'correction': "Leg signifie jambe.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L41", 'level': 'A1', 'title': "Possessif ’s", 'subtitle': "Sous-chapitre 4 • Leçon 41/50", 'explanation': "On ajoute souvent ’s après le nom d’une personne pour indiquer la possession : Anna’s bag signifie le sac d’Anna.", 'example': "This is Anna’s bag. = C’est le sac d’Anna.", 'french': "C’est le sac d’Anna.", 'question': "Anna’s bag signifie…", 'options': <String>["Le sac d’Anna", "Anna est dans un sac", "Le sac des Anna"], 'answer': 0, 'correction': "’s indique ici la possession.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L42", 'level': 'A1', 'title': "Distinguer his bag et her bag", 'subtitle': "Sous-chapitre 4 • Leçon 42/50", 'explanation': "His bag signifie son sac à lui ; her bag signifie son sac à elle. Le possessif dépend du possesseur, pas du sac.", 'example': "His bag is black. / Her bag is blue. = Son sac à lui est noir. / Son sac à elle est bleu.", 'french': "His bag is black. / Her bag is blue. = Son sac à lui est noir. / Son sac à elle est bleu.", 'question': "Pour parler du sac d’une fille, choisis…", 'options': <String>["his bag", "her bag", "she bag"], 'answer': 1, 'correction': "Her indique le possesseur féminin dans cet exemple.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L43", 'level': 'A1', 'title': "Question Whose is this?", 'subtitle': "Sous-chapitre 4 • Leçon 43/50", 'explanation': "Whose signifie à qui. Whose is this? demande à qui appartient un objet singulier proche.", 'example': "Whose is this? It’s my pen. = À qui est-ce ? C’est mon stylo.", 'french': "À qui est-ce ? C’est mon stylo.", 'question': "Whose demande…", 'options': <String>["À qui appartient cet objet", "Où est l’objet", "Quelle couleur est-ce"], 'answer': 0, 'correction': "Whose est le mot interrogatif de possession.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L44", 'level': 'A1', 'title': "Répondre It’s mine", 'subtitle': "Sous-chapitre 4 • Leçon 44/50", 'explanation': "Mine signifie le mien ou la mienne ; il remplace my + nom. On dit It’s mine, pas It’s my quand le nom n’est pas répété.", 'example': "Whose book is this? It’s mine. = À qui est ce livre ? Il est à moi.", 'french': "À qui est ce livre ? Il est à moi.", 'question': "Que signifie It’s mine ?", 'options': <String>["C’est mon livre (nom toujours nécessaire)", "C’est à moi", "C’est à toi"], 'answer': 1, 'correction': "Mine remplace le nom possédé dans la réponse.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L45", 'level': 'A1', 'title': "Mine et yours dans les objets", 'subtitle': "Sous-chapitre 4 • Leçon 45/50", 'explanation': "Mine signifie le mien/la mienne ; yours signifie le tien/la tienne ou le vôtre/la vôtre. Ces formes sont autonomes, sans nom après elles.", 'example': "This pen is mine. That pen is yours. = Ce stylo est à moi. Celui-là est à toi.", 'french': "Ce stylo est à moi. Celui-là est à toi.", 'question': "Yours signifie…", 'options': <String>["Le mien", "Le tien / le vôtre", "Le leur uniquement"], 'answer': 1, 'correction': "Yours est un possessif autonome.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L46", 'level': 'A1', 'title': "Décrire deux objets", 'subtitle': "Sous-chapitre 4 • Leçon 46/50", 'explanation': "Pour comparer ou décrire deux objets, réutilise les couleurs, tailles et noms. And relie deux éléments dans la même phrase.", 'example': "The bag is small and blue. The book is large and red. = Le sac est petit et bleu. Le livre est grand et rouge.", 'french': "Le sac est petit et bleu. Le livre est grand et rouge.", 'question': "And signifie…", 'options': <String>["Mais", "Et", "Ou"], 'answer': 1, 'correction': "And relie des mots ou des idées.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L47", 'level': 'A1', 'title': "Relier des descriptions avec and", 'subtitle': "Sous-chapitre 4 • Leçon 47/50", 'explanation': "And signifie et. Il relie des mots ou des phrases de même rôle. Il ne change pas la forme des adjectifs.", 'example': "She is kind and funny. = Elle est gentille et drôle.", 'french': "Elle est gentille et drôle.", 'question': "Quel mot signifie « et » ?", 'options': <String>["but", "and", "because"], 'answer': 1, 'correction': "And relie les deux adjectifs.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L48", 'level': 'A1', 'title': "Opposer des descriptions avec but", 'subtitle': "Sous-chapitre 4 • Leçon 48/50", 'explanation': "But signifie mais et sert à opposer deux idées. Il aide à créer des phrases plus naturelles et précises.", 'example': "He is young but very tall. = Il est jeune mais très grand.", 'french': "Il est jeune mais très grand.", 'question': "But signifie…", 'options': <String>["Parce que", "Mais", "Alors"], 'answer': 1, 'correction': "But introduit un contraste.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L49", 'level': 'A1', 'title': "Lire une carte de profil", 'subtitle': "Sous-chapitre 4 • Leçon 49/50", 'explanation': "Une carte de profil peut indiquer name, age, country, languages et hobbies. Lis les étiquettes puis repère les informations clés.", 'example': "Name: Alex. Age: 15. Country: Canada. Hobby: football.", 'french': "Name: Alex. Age: 15. Country: Canada. Hobby: football.", 'question': "Hobby signifie…", 'options': <String>["Passeport", "Loisir", "Adresse"], 'answer': 1, 'correction': "Hobby signifie loisir ou activité favorite.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U04-L50", 'level': 'A1', 'title': "Révision : décrire trois personnes", 'subtitle': "Sous-chapitre 4 • Leçon 50/50", 'explanation': "Réutilise les membres de famille, les pronoms, les adjectifs, les vêtements et les couleurs. Évite les phrases isolées : relie-les pour décrire clairement.", 'example': "This is Mia. She is young and friendly. She has curly hair. She is wearing a red shirt. = Voici Mia. Elle est jeune et amicale. Elle a les cheveux bouclés. Elle porte une chemise rouge.", 'french': "Voici Mia. Elle est jeune et amicale. Elle a les cheveux bouclés. Elle porte une chemise rouge.", 'question': "Quelle phrase décrit correctement Mia avec le verbe to be ?", 'options': <String>["She are friendly.", "She is friendly.", "She friendly is."], 'answer': 1, 'correction': "Avec she, on utilise is avant l’adjectif.", 'unit': 4, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L01", 'level': 'A1', 'title': "Sept jours de la semaine", 'subtitle': "Sous-chapitre 5 • Leçon 1/50", 'explanation': "Les jours sont Monday, Tuesday, Wednesday, Thursday, Friday, Saturday et Sunday. En anglais, le nom des jours commence par une majuscule.", 'example': "Monday = lundi ; Sunday = dimanche.", 'french': "lundi ; Sunday = dimanche.", 'question': "Which day means « lundi »?", 'options': <String>["Monday", "Sunday", "Friday"], 'answer': 0, 'correction': "Monday signifie lundi.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L02", 'level': 'A1', 'title': "Douze mois", 'subtitle': "Sous-chapitre 5 • Leçon 2/50", 'explanation': "Les mois commencent par une majuscule : January, February, March, April, May, June, July, August, September, October, November, December.", 'example': "January = janvier ; December = décembre.", 'french': "janvier ; December = décembre.", 'question': "Which month means « août »?", 'options': <String>["April", "August", "October"], 'answer': 1, 'correction': "August signifie août.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L03", 'level': 'A1', 'title': "Saisons de l’année", 'subtitle': "Sous-chapitre 5 • Leçon 3/50", 'explanation': "Les saisons sont spring (printemps), summer (été), fall ou autumn (automne) et winter (hiver). Fall est courant en anglais américain.", 'example': "Summer is hot. = L’été est chaud.", 'french': "L’été est chaud.", 'question': "Fall signifie…", 'options': <String>["Printemps", "Automne", "Hiver"], 'answer': 1, 'correction': "Fall est le mot américain courant pour automne.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L04", 'level': 'A1', 'title': "Question What day is it?", 'subtitle': "Sous-chapitre 5 • Leçon 4/50", 'explanation': "What day is it? demande quel jour nous sommes. On répond It’s Monday ou Today is Monday.", 'example': "What day is it? — It’s Tuesday. = Quel jour sommes-nous ? — Mardi.", 'french': "Quel jour sommes-nous ? — Mardi.", 'question': "Quelle question demande le jour de la semaine ?", 'options': <String>["What day is it?", "What time is it?", "What month is it?"], 'answer': 0, 'correction': "Day signifie jour.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L05", 'level': 'A1', 'title': "Dire la date simplement", 'subtitle': "Sous-chapitre 5 • Leçon 5/50", 'explanation': "Pour donner une date, on peut dire It’s October 26th ou Today is October 26th. Les dates américaines placent souvent le mois avant le jour.", 'example': "Today is May 5th. = Nous sommes le 5 mai.", 'french': "Nous sommes le 5 mai.", 'question': "Dans une date américaine courante, qu’est-ce qui vient souvent en premier ?", 'options': <String>["Le mois", "L’année seulement", "Le jour de la semaine"], 'answer': 0, 'correction': "Le format courant américain place le mois avant le jour.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L06", 'level': 'A1', 'title': "Nombres ordinaux dans les dates", 'subtitle': "Sous-chapitre 5 • Leçon 6/50", 'explanation': "Les dates utilisent des nombres ordinaux : first, second, third, fourth, fifth. Les abréviations sont 1st, 2nd, 3rd, 4th, 5th.", 'example': "May first = le premier mai.", 'french': "le premier mai.", 'question': "Comment dit-on 2nd ?", 'options': <String>["second", "two", "twoth"], 'answer': 0, 'correction': "Second est l’ordinal de two.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L07", 'level': 'A1', 'title': "Dire l’heure pile", 'subtitle': "Sous-chapitre 5 • Leçon 7/50", 'explanation': "Pour l’heure pile, utilise It’s + heure + o’clock. O’clock s’utilise quand on indique une heure entière.", 'example': "It’s seven o’clock. = Il est sept heures.", 'french': "Il est sept heures.", 'question': "Comment dire « Il est huit heures » ?", 'options': <String>["It’s eight o’clock.", "It has eight hour.", "Eight clock it."], 'answer': 0, 'correction': "La structure est It’s + nombre + o’clock.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L08", 'level': 'A1', 'title': "Dire l’heure et les minutes", 'subtitle': "Sous-chapitre 5 • Leçon 8/50", 'explanation': "Pour une heure numérique, on peut lire les chiffres : It’s three fifteen ou It’s 3:15. Quarter past et half past sont d’autres formes courantes.", 'example': "It’s 6:30. = Il est 6 h 30.", 'french': "Il est 6 h 30.", 'question': "3:15 peut se dire…", 'options': <String>["three fifteen", "three fifty", "thirty three"], 'answer': 0, 'correction': "Pour les minutes, on peut lire l’heure puis les minutes.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L09", 'level': 'A1', 'title': "Question What time is it?", 'subtitle': "Sous-chapitre 5 • Leçon 9/50", 'explanation': "What time is it? demande l’heure. La réponse commence souvent par It’s…", 'example': "What time is it? — It’s nine o’clock. = Quelle heure est-il ? — Il est neuf heures.", 'french': "Quelle heure est-il ? — Il est neuf heures.", 'question': "Quelle question demande l’heure ?", 'options': <String>["What time is it?", "What day is it?", "Where is it?"], 'answer': 0, 'correction': "Time signifie heure ou temps selon le contexte.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L10", 'level': 'A1', 'title': "Utiliser at avec une heure", 'subtitle': "Sous-chapitre 5 • Leçon 10/50", 'explanation': "At sert souvent à indiquer une heure précise : at seven, at 8:30, at noon. Il faut apprendre cette préposition avec les expressions de temps.", 'example': "My bus leaves at seven. = Mon bus part à sept heures.", 'french': "Le cours commence à huit heures.", 'question': "The bus leaves ___ 7:30.", 'options': <String>["in", "on", "at"], 'answer': 2, 'correction': "At s’utilise pour une heure précise.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L11", 'level': 'A1', 'title': "In the morning", 'subtitle': "Sous-chapitre 5 • Leçon 11/50", 'explanation': "In the morning signifie le matin. On dit in the morning, in the afternoon et in the evening pour les parties de la journée.", 'example': "I study in the morning. = J’étudie le matin.", 'french': "J’étudie le matin.", 'question': "Comment dire « le matin » ?", 'options': <String>["at the morning", "in the morning", "on morning"], 'answer': 1, 'correction': "La préposition courante est in.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L12", 'level': 'A1', 'title': "In the afternoon", 'subtitle': "Sous-chapitre 5 • Leçon 12/50", 'explanation': "In the afternoon signifie l’après-midi. Utilise cette expression pour situer une activité dans la journée.", 'example': "I play football in the afternoon. = Je joue au football l’après-midi.", 'french': "Je joue au football l’après-midi.", 'question': "Comment dire « l’après-midi » ?", 'options': <String>["in the afternoon", "on the afternoon", "at afternoon"], 'answer': 0, 'correction': "On utilise in the afternoon.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L13", 'level': 'A1', 'title': "In the evening", 'subtitle': "Sous-chapitre 5 • Leçon 13/50", 'explanation': "In the evening signifie le soir, pour parler d’une période de la journée. Good evening est une salutation, ce qui est un usage différent.", 'example': "I read in the evening. = Je lis le soir.", 'french': "Je lis le soir.", 'question': "Quel groupe de mots signifie « le soir » ?", 'options': <String>["at evening", "in the evening", "on evening"], 'answer': 1, 'correction': "On dit in the evening pour la période de la journée.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L14", 'level': 'A1', 'title': "Distinguer at night et in the night", 'subtitle': "Sous-chapitre 5 • Leçon 14/50", 'explanation': "At night est la formule générale pour parler de la nuit. In the night insiste souvent sur quelque chose qui arrive pendant la nuit.", 'example': "I sleep at night. = Je dors la nuit.", 'french': "Je dors la nuit.", 'question': "Quelle expression est la plus naturelle pour une habitude générale ?", 'options': <String>["at night", "on night", "in nights"], 'answer': 0, 'correction': "At night est l’expression courante pour une habitude nocturne.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L15", 'level': 'A1', 'title': "Today, tomorrow et yesterday", 'subtitle': "Sous-chapitre 5 • Leçon 15/50", 'explanation': "Today signifie aujourd’hui, tomorrow demain et yesterday hier. Ces mots permettent de situer une action dans le temps.", 'example': "I’m busy today. = Je suis occupé aujourd’hui.", 'french': "Je suis occupé aujourd’hui.", 'question': "Tomorrow signifie…", 'options': <String>["Hier", "Demain", "Aujourd’hui"], 'answer': 1, 'correction': "Tomorrow signifie demain.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L16", 'level': 'A1', 'title': "This week et next week", 'subtitle': "Sous-chapitre 5 • Leçon 16/50", 'explanation': "This week signifie cette semaine ; next week signifie la semaine prochaine. Last week signifie la semaine dernière.", 'example': "I have an exam next week. = J’ai un examen la semaine prochaine.", 'french': "J’ai un examen la semaine prochaine.", 'question': "Next week signifie…", 'options': <String>["La semaine dernière", "Cette semaine", "La semaine prochaine"], 'answer': 2, 'correction': "Next indique ici la période suivante.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L17", 'level': 'A1', 'title': "Last week et next month", 'subtitle': "Sous-chapitre 5 • Leçon 17/50", 'explanation': "Last week signifie la semaine dernière ; next month signifie le mois prochain. Last renvoie à la période passée et next à la suivante.", 'example': "I travelled last week. = J’ai voyagé la semaine dernière.", 'french': "J’ai voyagé la semaine dernière.", 'question': "Next month signifie…", 'options': <String>["Le mois dernier", "Le mois prochain", "Ce mois-ci"], 'answer': 1, 'correction': "Next month désigne le mois suivant.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L18", 'level': 'A1', 'title': "Parler d’un anniversaire", 'subtitle': "Sous-chapitre 5 • Leçon 18/50", 'explanation': "Birthday signifie anniversaire de naissance. Pour demander la date, utilise When is your birthday? Pour répondre, dis My birthday is in May ou My birthday is on May 5th.", 'example': "My birthday is in June. = Mon anniversaire est en juin.", 'french': "Mon anniversaire est en juin.", 'question': "Birthday signifie…", 'options': <String>["Anniversaire de naissance", "Mariage", "Vacances"], 'answer': 0, 'correction': "Birthday désigne l’anniversaire de naissance.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L19", 'level': 'A1', 'title': "Question When is your birthday?", 'subtitle': "Sous-chapitre 5 • Leçon 19/50", 'explanation': "When demande quand. Pour la date d’anniversaire, demande When is your birthday? La réponse peut donner un mois ou une date précise.", 'example': "When is your birthday? — It’s in April. = Quand est ton anniversaire ? — En avril.", 'french': "Quand est ton anniversaire ? — En avril.", 'question': "Quelle question demande la date d’anniversaire ?", 'options': <String>["When is your birthday?", "Where is your birthday?", "Who is your birthday?"], 'answer': 0, 'correction': "When signifie quand.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L20", 'level': 'A1', 'title': "Prendre un rendez-vous simple", 'subtitle': "Sous-chapitre 5 • Leçon 20/50", 'explanation': "Pour proposer un rendez-vous, tu peux demander Are you free on Friday? ou Can we meet at three? Utilise at pour l’heure et on pour le jour.", 'example': "Can we meet at three? = Peut-on se voir à trois heures ?", 'french': "Peut-on se voir à trois heures ?", 'question': "Quelle préposition convient avant Friday ?", 'options': <String>["on", "at", "in"], 'answer': 0, 'correction': "On s’utilise couramment avec les jours.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L21", 'level': 'A1', 'title': "Wake up dans une routine", 'subtitle': "Sous-chapitre 5 • Leçon 21/50", 'explanation': "Wake up signifie se réveiller. Pour parler d’une habitude, utilise le présent simple : I wake up at six.", 'example': "I wake up at six every day. = Je me réveille à six heures chaque jour.", 'french': "Je me réveille à six heures chaque jour.", 'question': "Wake up signifie…", 'options': <String>["Se coucher", "Se réveiller", "Déjeuner"], 'answer': 1, 'correction': "Wake up décrit le passage du sommeil à l’éveil.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L22", 'level': 'A1', 'title': "Get up dans une routine", 'subtitle': "Sous-chapitre 5 • Leçon 22/50", 'explanation': "Get up signifie se lever du lit. Wake up signifie se réveiller ; les deux actions peuvent arriver à des moments différents.", 'example': "I wake up at six and get up at six fifteen. = Je me réveille à six heures et je me lève à six heures quinze.", 'french': "Je me réveille à six heures et je me lève à six heures quinze.", 'question': "Get up signifie…", 'options': <String>["Se lever du lit", "Se réveiller seulement", "S’endormir"], 'answer': 0, 'correction': "Get up décrit le fait de se lever.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L23", 'level': 'A1', 'title': "Parler du petit-déjeuner", 'subtitle': "Sous-chapitre 5 • Leçon 23/50", 'explanation': "Breakfast signifie petit-déjeuner. On dit have breakfast pour prendre le petit-déjeuner ; on ne traduit pas chaque mot séparément.", 'example': "I have breakfast at seven. = Je prends le petit-déjeuner à sept heures.", 'french': "Je prends le petit-déjeuner à sept heures.", 'question': "Comment dire « prendre le petit-déjeuner » ?", 'options': <String>["make breakfast always", "have breakfast", "eat morning"], 'answer': 1, 'correction': "Have breakfast est l’expression courante.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L24", 'level': 'A1', 'title': "Partir à l’école ou au travail", 'subtitle': "Sous-chapitre 5 • Leçon 24/50", 'explanation': "Go to school signifie aller à l’école ; go to work signifie aller au travail. On utilise go to + lieu dans ces expressions.", 'example': "I go to school at seven. = Je vais à l’école à sept heures.", 'french': "Je vais à l’école à sept heures.", 'question': "Comment dire « aller au travail » ?", 'options': <String>["go to work", "go work to", "go at work"], 'answer': 0, 'correction': "La structure est go to + lieu.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L25", 'level': 'A1', 'title': "Rentrer à la maison", 'subtitle': "Sous-chapitre 5 • Leçon 25/50", 'explanation': "Go home signifie rentrer ou aller à la maison. Dans cette expression, on n’utilise normalement pas to avant home.", 'example': "I go home after class. = Je rentre à la maison après les cours.", 'french': "Je rentre à la maison après les cours.", 'question': "Quelle phrase indique qu’on rentre chez soi après les cours ?", 'options': <String>["I go to home.", "I go home.", "I goes home."], 'answer': 1, 'correction': "Home fonctionne ici comme un adverbe de direction.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L26", 'level': 'A1', 'title': "Parler du dîner", 'subtitle': "Sous-chapitre 5 • Leçon 26/50", 'explanation': "Dinner désigne le dîner ou le repas principal du soir selon le contexte. On dit have dinner pour prendre le dîner.", 'example': "We have dinner at seven. = Nous dînons à sept heures.", 'french': "Nous dînons à sept heures.", 'question': "Quelle expression signifie « dîner » comme activité ?", 'options': <String>["have dinner", "make night", "do dinner always"], 'answer': 0, 'correction': "Have dinner est l’expression naturelle.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L27", 'level': 'A1', 'title': "Décrire la routine du soir", 'subtitle': "Sous-chapitre 5 • Leçon 27/50", 'explanation': "Pour raconter la routine du soir, enchaîne des verbes au présent simple et des expressions de temps : have dinner, study, relax, go to bed.", 'example': "I study, relax and go to bed at ten. = J’étudie, je me détends et je me couche à dix heures.", 'french': "J’étudie, je me détends et je me couche à dix heures.", 'question': "Quelle expression signifie « se coucher » ?", 'options': <String>["go to bed", "get up", "wake up"], 'answer': 0, 'correction': "Go to bed signifie aller se coucher.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L28", 'level': 'A1', 'title': "First, then et finally", 'subtitle': "Sous-chapitre 5 • Leçon 28/50", 'explanation': "First signifie d’abord ; then signifie ensuite ; finally signifie enfin. Ces mots organisent les étapes d’une routine ou d’une histoire.", 'example': "First, I eat. Then, I study. Finally, I sleep. = D’abord je mange. Ensuite j’étudie. Enfin je dors.", 'french': "D’abord je mange. Ensuite j’étudie. Enfin je dors.", 'question': "Finally signifie…", 'options': <String>["D’abord", "Ensuite", "Enfin"], 'answer': 2, 'correction': "Finally introduit la dernière étape.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L29", 'level': 'A1', 'title': "Every day pour une habitude", 'subtitle': "Sous-chapitre 5 • Leçon 29/50", 'explanation': "Every day signifie chaque jour. On l’utilise souvent avec le présent simple pour parler d’une habitude répétée.", 'example': "I practise English every day. = Je pratique l’anglais chaque jour.", 'french': "Je pratique l’anglais chaque jour.", 'question': "Every day signifie…", 'options': <String>["Chaque jour", "Hier", "La semaine prochaine"], 'answer': 0, 'correction': "Every day indique une répétition quotidienne.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L30", 'level': 'A1', 'title': "Usually dans une routine", 'subtitle': "Sous-chapitre 5 • Leçon 30/50", 'explanation': "Usually signifie habituellement. Il se place souvent avant le verbe principal, mais après be : I usually study ; I am usually busy.", 'example': "I usually walk to school. = Je vais habituellement à l’école à pied.", 'french': "Je vais habituellement à l’école à pied.", 'question': "Usually signifie…", 'options': <String>["Jamais", "Habituellement", "Demain"], 'answer': 1, 'correction': "Usually exprime une fréquence habituelle.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L31", 'level': 'A1', 'title': "Sometimes pour la fréquence", 'subtitle': "Sous-chapitre 5 • Leçon 31/50", 'explanation': "Sometimes signifie parfois. Il se place souvent avant le verbe principal ou au début/à la fin de la phrase.", 'example': "I sometimes play basketball. = Je joue parfois au basket.", 'french': "Je joue parfois au basket.", 'question': "Sometimes signifie…", 'options': <String>["Toujours", "Parfois", "Jamais"], 'answer': 1, 'correction': "Sometimes indique que l’action arrive certaines fois.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L32", 'level': 'A1', 'title': "Never dans une phrase", 'subtitle': "Sous-chapitre 5 • Leçon 32/50", 'explanation': "Never signifie jamais. Il a déjà un sens négatif ; dans une phrase standard, on n’ajoute généralement pas don’t devant le même verbe pour exprimer la même négation.", 'example': "I never smoke. = Je ne fume jamais.", 'french': "Je ne fume jamais.", 'question': "Never signifie…", 'options': <String>["Toujours", "Parfois", "Jamais"], 'answer': 2, 'correction': "Never exprime une fréquence nulle.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L33", 'level': 'A1', 'title': "Always avec les routines", 'subtitle': "Sous-chapitre 5 • Leçon 33/50", 'explanation': "Always signifie toujours. Avec un verbe principal, il se place souvent avant ce verbe ; avec be, il vient généralement après be.", 'example': "I always brush my teeth. = Je me brosse toujours les dents.", 'french': "Je me brosse toujours les dents.", 'question': "Always signifie…", 'options': <String>["Toujours", "Parfois", "Rarement"], 'answer': 0, 'correction': "Always indique une fréquence constante.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L34", 'level': 'A1', 'title': "Placer often dans une phrase", 'subtitle': "Sous-chapitre 5 • Leçon 34/50", 'explanation': "Often signifie souvent. Il se place généralement avant le verbe principal, mais après be.", 'example': "I often read at night. = Je lis souvent la nuit.", 'french': "Je lis souvent la nuit.", 'question': "Complète : I ___ play football.", 'options': <String>["often", "am often play", "play often am"], 'answer': 0, 'correction': "Often précède généralement le verbe principal.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L35", 'level': 'A1', 'title': "Question How often?", 'subtitle': "Sous-chapitre 5 • Leçon 35/50", 'explanation': "How often? signifie à quelle fréquence ? On peut répondre avec always, usually, often, sometimes ou never.", 'example': "How often do you study? — Every day. = À quelle fréquence étudies-tu ? — Chaque jour.", 'french': "À quelle fréquence étudies-tu ? — Chaque jour.", 'question': "Quelle question demande la fréquence ?", 'options': <String>["How often?", "How old?", "How much?"], 'answer': 0, 'correction': "How often demande la fréquence d’une action.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L36", 'level': 'A1', 'title': "Before et after avec des activités", 'subtitle': "Sous-chapitre 5 • Leçon 36/50", 'explanation': "Before signifie avant ; after signifie après. Ils permettent d’ordonner des activités ou des moments.", 'example': "I study before dinner. = J’étudie avant le dîner.", 'french': "J’étudie avant le dîner.", 'question': "After signifie…", 'options': <String>["Avant", "Après", "Pendant"], 'answer': 1, 'correction': "After signifie après.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L37", 'level': 'A1', 'title': "Activité du week-end", 'subtitle': "Sous-chapitre 5 • Leçon 37/50", 'explanation': "Weekend signifie week-end. On dit on the weekend en anglais américain courant ; at the weekend est plus courant en anglais britannique.", 'example': "I play football on the weekend. = Je joue au football le week-end.", 'french': "Je joue au football le week-end.", 'question': "Quelle expression est courante en anglais américain ?", 'options': <String>["on the weekend", "in weekend", "at weekend only"], 'answer': 0, 'correction': "On the weekend est courant en anglais américain.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L38", 'level': 'A1', 'title': "Dire I’m early et I’m late", 'subtitle': "Sous-chapitre 5 • Leçon 38/50", 'explanation': "Early signifie en avance ou tôt ; late signifie en retard ou tard. Utilise be + early/late pour décrire une arrivée ou une heure.", 'example': "I’m early. = Je suis en avance. / I’m late. = Je suis en retard.", 'french': "Je suis en retard.", 'question': "Late signifie…", 'options': <String>["En avance", "En retard", "Prêt"], 'answer': 1, 'correction': "Late signifie en retard dans ce contexte.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L39", 'level': 'A1', 'title': "Dire l’heure d’un cours", 'subtitle': "Sous-chapitre 5 • Leçon 39/50", 'explanation': "Pour annoncer l’heure d’un cours, utilise The class starts at… ou My class is at…. At introduit l’heure précise.", 'example': "My class starts at nine. = Mon cours commence à neuf heures.", 'french': "Mon cours commence à neuf heures.", 'question': "Quelle préposition précède nine o’clock ?", 'options': <String>["at", "in", "on"], 'answer': 0, 'correction': "At introduit une heure précise.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L40", 'level': 'A1', 'title': "Lire un horaire quotidien", 'subtitle': "Sous-chapitre 5 • Leçon 40/50", 'explanation': "Un horaire indique les heures et les activités. Repère les verbes d’action, puis associe chaque activité à son heure.", 'example': "7:00 wake up; 8:00 class; 4:00 study. = 7 h réveil ; 8 h cours ; 16 h étude.", 'french': "7 h réveil ; 8 h cours ; 16 h étude.", 'question': "À 8:00, que fait la personne dans l’exemple ?", 'options': <String>["Wake up", "Class", "Study"], 'answer': 1, 'correction': "L’horaire associe 8:00 à class.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L41", 'level': 'A1', 'title': "Comprendre un calendrier simple", 'subtitle': "Sous-chapitre 5 • Leçon 41/50", 'explanation': "Un calendrier présente les jours et les dates. Repère le nom du mois, le jour de la semaine et le numéro de la date.", 'example': "The meeting is on Tuesday, May 12th. = La réunion est mardi 12 mai.", 'french': "La réunion est mardi 12 mai.", 'question': "Quel élément indique le jour de la semaine ?", 'options': <String>["Tuesday", "May", "12th"], 'answer': 0, 'correction': "Tuesday est le jour de la semaine.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L42", 'level': 'A1', 'title': "Dire la durée d’une activité", 'subtitle': "Sous-chapitre 5 • Leçon 42/50", 'explanation': "Pour parler de durée, utilise for + durée : for ten minutes, for two hours. Since indique plutôt le point de départ d’une durée qui continue.", 'example': "I study for one hour. = J’étudie pendant une heure.", 'french': "J’étudie pendant une heure.", 'question': "Quelle expression signifie « pendant deux heures » ?", 'options': <String>["for two hours", "at two hours", "in two hour"], 'answer': 0, 'correction': "For introduit une durée.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L43", 'level': 'A1', 'title': "From…to… pour une plage horaire", 'subtitle': "Sous-chapitre 5 • Leçon 43/50", 'explanation': "From…to… indique un début et une fin : from nine to ten. On l’utilise pour les cours, les horaires et les activités.", 'example': "I study from six to seven. = J’étudie de six à sept heures.", 'french': "J’étudie de six à sept heures.", 'question': "Comment dire « de neuf à dix heures » ?", 'options': <String>["from nine to ten", "at nine and ten", "in nine to ten"], 'answer': 0, 'correction': "From indique le début et to la fin.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L44", 'level': 'A1', 'title': "Inviter quelqu’un à une heure", 'subtitle': "Sous-chapitre 5 • Leçon 44/50", 'explanation': "Pour proposer une rencontre, dis Are you free at six? ou Let’s meet at six. At précède l’heure.", 'example': "Let’s meet at six. = Retrouvons-nous à six heures.", 'french': "Retrouvons-nous à six heures.", 'question': "Quelle préposition convient avant six o’clock ?", 'options': <String>["on", "at", "in"], 'answer': 1, 'correction': "At introduit l’heure du rendez-vous.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L45", 'level': 'A1', 'title': "Confirmer une heure", 'subtitle': "Sous-chapitre 5 • Leçon 45/50", 'explanation': "Pour confirmer, tu peux dire Yes, six works for me ou That’s fine. Pour demander une confirmation, dis Is six okay?", 'example': "Six works for me. = Six heures me conviennent.", 'french': "Six heures me conviennent.", 'question': "Quelle phrase confirme que l’heure convient ?", 'options': <String>["Six works for me.", "I six work.", "Six is yesterday."], 'answer': 0, 'correction': "Cette expression signifie que l’heure convient.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L46", 'level': 'A1', 'title': "Modifier un rendez-vous", 'subtitle': "Sous-chapitre 5 • Leçon 46/50", 'explanation': "Pour modifier l’heure, demande Can we meet later? ou Can we make it seven? Il est utile de proposer une nouvelle heure clairement.", 'example': "Can we meet at seven instead? = Peut-on se voir à sept heures à la place ?", 'french': "Peut-on se voir à sept heures à la place ?", 'question': "Instead signifie ici…", 'options': <String>["À la place", "Hier", "Toujours"], 'answer': 0, 'correction': "Instead indique une alternative.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L47", 'level': 'A1', 'title': "Dire I’m busy et I’m free", 'subtitle': "Sous-chapitre 5 • Leçon 47/50", 'explanation': "Busy signifie occupé ; free signifie libre ou disponible. Pour accepter une invitation, tu peux dire I’m free at six.", 'example': "I’m free this afternoon. = Je suis libre cet après-midi.", 'french': "Je suis occupé aujourd’hui.", 'question': "Free signifie dans ce contexte…", 'options': <String>["Libre / disponible", "Cher", "Fatigué"], 'answer': 0, 'correction': "I’m free indique la disponibilité.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L48", 'level': 'A1', 'title': "Raconter une journée au présent simple", 'subtitle': "Sous-chapitre 5 • Leçon 48/50", 'explanation': "Le présent simple sert à parler d’habitudes. Utilise un sujet, un verbe et des marqueurs de fréquence ou de temps.", 'example': "I wake up at six, go to school and study in the evening. = Je me réveille à six heures, vais à l’école et étudie le soir.", 'french': "Je me réveille à six heures, vais à l’école et étudie le soir.", 'question': "Quel temps décrit une routine habituelle ?", 'options': <String>["Present simple", "Past continuous", "Future perfect"], 'answer': 0, 'correction': "Le présent simple sert notamment aux habitudes.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L49", 'level': 'A1', 'title': "Écouter et ordonner une routine", 'subtitle': "Sous-chapitre 5 • Leçon 49/50", 'explanation': "Pour remettre une routine en ordre, repère les mots de temps et la logique des activités : wake up, have breakfast, go to school, come home, go to bed.", 'example': "First I wake up. Then I have breakfast. Finally I go to school.", 'french': "First I wake up. Then I have breakfast. Finally I go to school.", 'question': "Quel mot indique la première étape ?", 'options': <String>["First", "Finally", "Yesterday"], 'answer': 0, 'correction': "First signifie d’abord.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U05-L50", 'level': 'A1', 'title': "Révision : raconter sa journée", 'subtitle': "Sous-chapitre 5 • Leçon 50/50", 'explanation': "Réutilise les heures, les routines, les marqueurs de fréquence et les connecteurs temporels. Une bonne description contient plusieurs phrases reliées.", 'example': "I usually wake up at six. Then I have breakfast. I go to school at seven. = Je me réveille habituellement à six heures. Ensuite je prends le petit-déjeuner. Je vais à l’école à sept heures.", 'french': "Je me réveille habituellement à six heures. Ensuite je prends le petit-déjeuner. Je vais à l’école à sept heures.", 'question': "Quelle phrase décrit une routine quotidienne dans le bon ordre des mots ?", 'options': <String>["I usually wake up at six.", "I wake usually up six at.", "I am wake up every day."], 'answer': 0, 'correction': "Usually précède le verbe principal ; at introduit l’heure.", 'unit': 5, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L01", 'level': 'A1', 'title': "House et apartment", 'subtitle': "Sous-chapitre 6 • Leçon 1/50", 'explanation': "House signifie maison ; apartment signifie appartement. En anglais américain, apartment est plus courant que flat.", 'example': "I live in an apartment. = J’habite dans un appartement.", 'french': "J’habite dans un appartement.", 'question': "Apartment signifie…", 'options': <String>["Appartement", "Jardin", "Cuisine"], 'answer': 0, 'correction': "Apartment signifie appartement.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L02", 'level': 'A1', 'title': "Pièces de la maison", 'subtitle': "Sous-chapitre 6 • Leçon 2/50", 'explanation': "Les pièces incluent living room, bedroom, kitchen, bathroom et dining room. Apprends-les en reliant chaque mot à une image.", 'example': "The bedroom is upstairs. = La chambre est à l’étage.", 'french': "La chambre est à l’étage.", 'question': "Bedroom signifie…", 'options': <String>["Cuisine", "Chambre", "Salon"], 'answer': 1, 'correction': "Bedroom est la chambre à coucher.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L03", 'level': 'A1', 'title': "Living room", 'subtitle': "Sous-chapitre 6 • Leçon 3/50", 'explanation': "Living room signifie salon, la pièce où l’on se détend ou reçoit des invités.", 'example': "We watch TV in the living room. = Nous regardons la télévision au salon.", 'french': "Nous regardons la télévision au salon.", 'question': "Living room signifie…", 'options': <String>["Salon", "Salle de bain", "Garage"], 'answer': 0, 'correction': "Living room est la pièce commune de détente.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L04", 'level': 'A1', 'title': "Bedroom", 'subtitle': "Sous-chapitre 6 • Leçon 4/50", 'explanation': "Bedroom signifie chambre à coucher. Bed signifie lit et room signifie pièce.", 'example': "My bedroom is small. = Ma chambre est petite.", 'french': "Ma chambre est petite.", 'question': "Que signifie bedroom lorsqu’on parle des pièces d’une maison ?", 'options': <String>["Chambre", "Cuisine", "Couloir"], 'answer': 0, 'correction': "Bedroom est la pièce où l’on dort.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L05", 'level': 'A1', 'title': "Kitchen", 'subtitle': "Sous-chapitre 6 • Leçon 5/50", 'explanation': "Kitchen signifie cuisine. On y prépare les repas ; kitchen peut être accompagné d’objets comme table, fridge et stove.", 'example': "The kitchen is clean. = La cuisine est propre.", 'french': "La cuisine est propre.", 'question': "Kitchen signifie…", 'options': <String>["Cuisine", "Salon", "Chambre"], 'answer': 0, 'correction': "Kitchen signifie cuisine.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L06", 'level': 'A1', 'title': "Bathroom", 'subtitle': "Sous-chapitre 6 • Leçon 6/50", 'explanation': "Bathroom signifie salle de bain ou toilettes selon le contexte régional. Restroom est aussi courant pour les toilettes publiques aux États-Unis.", 'example': "Where is the bathroom? = Où sont les toilettes ?", 'french': "Où sont les toilettes ?", 'question': "Quelle question demande où sont les toilettes ?", 'options': <String>["Where is the bathroom?", "What is the bathroom?", "Who bathroom?"], 'answer': 0, 'correction': "Where demande un lieu.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L07", 'level': 'A1', 'title': "Meubles essentiels", 'subtitle': "Sous-chapitre 6 • Leçon 7/50", 'explanation': "Furniture signifie meubles. Les meubles courants sont table, chair, bed, sofa, desk et shelf.", 'example': "There is a sofa in the living room. = Il y a un canapé dans le salon.", 'french': "Il y a un canapé dans le salon.", 'question': "Sofa signifie…", 'options': <String>["Canapé", "Lit", "Bureau"], 'answer': 0, 'correction': "Sofa signifie canapé.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L08", 'level': 'A1', 'title': "Table, chair et bed", 'subtitle': "Sous-chapitre 6 • Leçon 8/50", 'explanation': "Table signifie table ; chair signifie chaise ; bed signifie lit. Le contexte aide à distinguer table et desk, qui est un bureau de travail.", 'example': "The book is on the table. = Le livre est sur la table.", 'french': "Le livre est sur la table.", 'question': "Chair signifie…", 'options': <String>["Chaise", "Table", "Lit"], 'answer': 0, 'correction': "Chair signifie chaise.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L09", 'level': 'A1', 'title': "Appareils domestiques courants", 'subtitle': "Sous-chapitre 6 • Leçon 9/50", 'explanation': "Les appareils courants comprennent fridge (réfrigérateur), oven (four), washing machine (machine à laver) et fan (ventilateur).", 'example': "The food is in the fridge. = La nourriture est dans le réfrigérateur.", 'french': "La nourriture est dans le réfrigérateur.", 'question': "Fridge signifie…", 'options': <String>["Réfrigérateur", "Four", "Ventilateur"], 'answer': 0, 'correction': "Fridge est une forme courante de refrigerator.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L10", 'level': 'A1', 'title': "There is avec un objet", 'subtitle': "Sous-chapitre 6 • Leçon 10/50", 'explanation': "There is signifie il y a pour un élément singulier. La structure sert à dire qu’un objet ou une personne se trouve quelque part.", 'example': "There is a book on the table. = Il y a un livre sur la table.", 'french': "Il y a un livre sur la table.", 'question': "___ a chair in the room.", 'options': <String>["There is", "There are", "There am"], 'answer': 0, 'correction': "Un objet singulier prend there is.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L11", 'level': 'A1', 'title': "There are avec plusieurs objets", 'subtitle': "Sous-chapitre 6 • Leçon 11/50", 'explanation': "There are signifie il y a pour plusieurs éléments. Il s’accorde avec un nom pluriel.", 'example': "There are two chairs. = Il y a deux chaises.", 'french': "Il y a deux chaises.", 'question': "___ three books on the desk.", 'options': <String>["There is", "There are", "There am"], 'answer': 1, 'correction': "Three books est pluriel, donc there are.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L12", 'level': 'A1', 'title': "Négation there isn’t", 'subtitle': "Sous-chapitre 6 • Leçon 12/50", 'explanation': "There isn’t signifie il n’y a pas pour un élément singulier. La forme complète est there is not.", 'example': "There isn’t a TV in my room. = Il n’y a pas de télévision dans ma chambre.", 'french': "Il n’y a pas de télévision dans ma chambre.", 'question': "Quelle forme nie un objet singulier ?", 'options': <String>["There isn’t", "There aren’t", "There don’t"], 'answer': 0, 'correction': "There isn’t est la négation de there is.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L13", 'level': 'A1', 'title': "Question Is there…?", 'subtitle': "Sous-chapitre 6 • Leçon 13/50", 'explanation': "Pour demander s’il y a un objet singulier, inverse is et there : Is there a…? La réponse courte est Yes, there is ou No, there isn’t.", 'example': "Is there a bathroom? = Y a-t-il une salle de bain ?", 'french': "Y a-t-il une salle de bain ?", 'question': "Comment demander s’il y a une salle de bain ?", 'options': <String>["There is a bathroom?", "Is there a bathroom?", "Does there a bathroom?"], 'answer': 1, 'correction': "Avec there is, la question commence par Is there.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L14", 'level': 'A1', 'title': "Question Are there…?", 'subtitle': "Sous-chapitre 6 • Leçon 14/50", 'explanation': "Are there…? sert à demander s’il y a plusieurs éléments. La réponse courte est Yes, there are ou No, there aren’t.", 'example': "Are there two bedrooms? = Y a-t-il deux chambres ?", 'french': "Y a-t-il deux chambres ?", 'question': "___ any chairs?", 'options': <String>["Is there", "Are there", "Does there"], 'answer': 1, 'correction': "Chairs est pluriel, donc Are there.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L15", 'level': 'A1', 'title': "In front of", 'subtitle': "Sous-chapitre 6 • Leçon 15/50", 'explanation': "In front of signifie devant. Cette expression de lieu contient trois mots et doit être apprise comme un groupe.", 'example': "The car is in front of the house. = La voiture est devant la maison.", 'french': "La voiture est devant la maison.", 'question': "In front of signifie…", 'options': <String>["Derrière", "Devant", "Entre"], 'answer': 1, 'correction': "In front of signifie devant.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L16", 'level': 'A1', 'title': "Behind", 'subtitle': "Sous-chapitre 6 • Leçon 16/50", 'explanation': "Behind signifie derrière. Il indique qu’un objet se trouve à l’arrière d’un autre.", 'example': "The cat is behind the sofa. = Le chat est derrière le canapé.", 'french': "Le chat est derrière le canapé.", 'question': "Behind signifie…", 'options': <String>["À côté", "Derrière", "Sur"], 'answer': 1, 'correction': "Behind signifie derrière.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L17", 'level': 'A1', 'title': "Next to", 'subtitle': "Sous-chapitre 6 • Leçon 17/50", 'explanation': "Next to signifie à côté de. Cette expression est utile pour localiser des objets ou donner des indications.", 'example': "The bank is next to the store. = La banque est à côté du magasin.", 'french': "La banque est à côté du magasin.", 'question': "Next to signifie…", 'options': <String>["À côté de", "Au-dessus de", "À l’intérieur de"], 'answer': 0, 'correction': "Next to signifie à côté de.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L18", 'level': 'A1', 'title': "Between", 'subtitle': "Sous-chapitre 6 • Leçon 18/50", 'explanation': "Between signifie entre deux éléments. Il est souvent suivi de deux noms reliés par and.", 'example': "The school is between the bank and the park. = L’école est entre la banque et le parc.", 'french': "L’école est entre la banque et le parc.", 'question': "Between signifie…", 'options': <String>["Entre", "Derrière", "Sous"], 'answer': 0, 'correction': "Between indique une position entre des éléments.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L19", 'level': 'A1', 'title': "Under et below", 'subtitle': "Sous-chapitre 6 • Leçon 19/50", 'explanation': "Under signifie sous, souvent directement en dessous ; below signifie plus bas que, sans forcément être directement dessous.", 'example': "The bag is under the table. = Le sac est sous la table.", 'french': "Le sac est sous la table.", 'question': "Under signifie…", 'options': <String>["Sous", "Sur", "Devant"], 'answer': 0, 'correction': "Under indique une position en dessous.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L20", 'level': 'A1', 'title': "Above et over", 'subtitle': "Sous-chapitre 6 • Leçon 20/50", 'explanation': "Above signifie au-dessus de. Over peut aussi signifier au-dessus, parfois avec l’idée de couvrir ou de traverser.", 'example': "The lamp is above the table. = La lampe est au-dessus de la table.", 'french': "La lampe est au-dessus de la table.", 'question': "Above signifie…", 'options': <String>["Au-dessus de", "À l’intérieur", "Entre"], 'answer': 0, 'correction': "Above décrit une position plus haute.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L21", 'level': 'A1', 'title': "Inside et outside", 'subtitle': "Sous-chapitre 6 • Leçon 21/50", 'explanation': "Inside signifie à l’intérieur ; outside signifie à l’extérieur. Ces mots peuvent servir de préposition ou d’adverbe selon la phrase.", 'example': "The children are outside. = Les enfants sont dehors.", 'french': "Les enfants sont dehors.", 'question': "Outside signifie…", 'options': <String>["À l’intérieur", "À l’extérieur", "À côté"], 'answer': 1, 'correction': "Outside signifie dehors ou à l’extérieur.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L22", 'level': 'A1', 'title': "Question Where is the…?", 'subtitle': "Sous-chapitre 6 • Leçon 22/50", 'explanation': "Where is the…? demande où se trouve un objet singulier. Réponds avec It’s… ou The… is… puis une indication de lieu.", 'example': "Where is the key? It’s on the table. = Où est la clé ? Elle est sur la table.", 'french': "Où est la clé ? Elle est sur la table.", 'question': "Quelle question demande où se trouve une clé ?", 'options': <String>["Where is the key?", "What is the key?", "Who is the key?"], 'answer': 0, 'correction': "Where demande un lieu.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L23", 'level': 'A1', 'title': "Répondre It’s on…", 'subtitle': "Sous-chapitre 6 • Leçon 23/50", 'explanation': "It’s on… signifie il/elle est sur… ; on est suivi de la surface ou du support.", 'example': "It’s on the desk. = C’est sur le bureau.", 'french': "C’est sur le bureau.", 'question': "Complète : It’s ___ the table.", 'options': <String>["on", "are", "does"], 'answer': 0, 'correction': "On indique la position sur une surface.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L24", 'level': 'A1', 'title': "Street et road", 'subtitle': "Sous-chapitre 6 • Leçon 24/50", 'explanation': "Street signifie rue ; road signifie route ou voie. Les deux se recoupent, mais street est fréquent pour une rue en ville.", 'example': "My school is on this street. = Mon école est dans cette rue.", 'french': "Mon école est dans cette rue.", 'question': "Street signifie…", 'options': <String>["Rue", "Maison", "Ville"], 'answer': 0, 'correction': "Street signifie rue.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L25", 'level': 'A1', 'title': "Neighborhood et city", 'subtitle': "Sous-chapitre 6 • Leçon 25/50", 'explanation': "Neighborhood signifie quartier ; city signifie ville. Neighborhood est souvent utilisé pour parler de la zone autour de son logement.", 'example': "My neighborhood is quiet. = Mon quartier est calme.", 'french': "Mon quartier est calme.", 'question': "Neighborhood signifie…", 'options': <String>["Quartier", "Pays", "Continent"], 'answer': 0, 'correction': "Neighborhood désigne un quartier.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L26", 'level': 'A1', 'title': "Village et country", 'subtitle': "Sous-chapitre 6 • Leçon 26/50", 'explanation': "Village signifie village ; country signifie pays, mais peut aussi signifier campagne dans certains contextes. La phrase aide à choisir le sens.", 'example': "I live in a village. = J’habite dans un village.", 'french': "J’habite dans un village.", 'question': "Village signifie…", 'options': <String>["Village", "Pays", "Rue"], 'answer': 0, 'correction': "Village signifie village.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L27", 'level': 'A1', 'title': "School et library", 'subtitle': "Sous-chapitre 6 • Leçon 27/50", 'explanation': "School signifie école ; library signifie bibliothèque. Une library est un lieu où l’on peut lire ou emprunter des livres.", 'example': "The library is near the school. = La bibliothèque est près de l’école.", 'french': "La bibliothèque est près de l’école.", 'question': "Library signifie…", 'options': <String>["Librairie", "Bibliothèque", "Laboratoire"], 'answer': 1, 'correction': "Library signifie bibliothèque ; bookstore signifie librairie.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L28", 'level': 'A1', 'title': "Hospital et pharmacy", 'subtitle': "Sous-chapitre 6 • Leçon 28/50", 'explanation': "Hospital signifie hôpital ; pharmacy signifie pharmacie. Ces lieux sont utiles pour demander un renseignement en ville.", 'example': "The pharmacy is near the hospital. = La pharmacie est près de l’hôpital.", 'french': "La pharmacie est près de l’hôpital.", 'question': "Pharmacy signifie…", 'options': <String>["Pharmacie", "Hôpital", "École"], 'answer': 0, 'correction': "Pharmacy signifie pharmacie.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L29", 'level': 'A1', 'title': "Market et supermarket", 'subtitle': "Sous-chapitre 6 • Leçon 29/50", 'explanation': "Market signifie marché ; supermarket signifie supermarché. Les deux sont des lieux où l’on achète des produits.", 'example': "I buy fruit at the market. = J’achète des fruits au marché.", 'french': "J’achète des fruits au marché.", 'question': "Supermarket signifie…", 'options': <String>["Supermarché", "Bibliothèque", "Arrêt de bus"], 'answer': 0, 'correction': "Supermarket désigne un grand magasin alimentaire.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L30", 'level': 'A1', 'title': "Bank et post office", 'subtitle': "Sous-chapitre 6 • Leçon 30/50", 'explanation': "Bank signifie banque ; post office signifie bureau de poste. On peut demander leur emplacement avec Where is…?", 'example': "The bank is across from the post office. = La banque est en face du bureau de poste.", 'french': "La banque est en face du bureau de poste.", 'question': "Post office signifie…", 'options': <String>["Bureau de poste", "Hôpital", "Gare"], 'answer': 0, 'correction': "Post office est le bureau de poste.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L31", 'level': 'A1', 'title': "Park et playground", 'subtitle': "Sous-chapitre 6 • Leçon 31/50", 'explanation': "Park signifie parc ; playground signifie aire de jeux. Ces lieux peuvent apparaître dans une description de quartier.", 'example': "The children are at the playground. = Les enfants sont à l’aire de jeux.", 'french': "Les enfants sont à l’aire de jeux.", 'question': "Playground signifie…", 'options': <String>["Aire de jeux", "Salle de classe", "Parking"], 'answer': 0, 'correction': "Playground est un espace de jeu.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L32", 'level': 'A1', 'title': "Restaurant et café", 'subtitle': "Sous-chapitre 6 • Leçon 32/50", 'explanation': "Restaurant signifie restaurant ; café peut désigner un café ou un petit établissement où l’on prend une boisson ou un repas léger.", 'example': "The café is next to the restaurant. = Le café est à côté du restaurant.", 'french': "Le café est à côté du restaurant.", 'question': "Restaurant signifie…", 'options': <String>["Restaurant", "Magasin", "Gare"], 'answer': 0, 'correction': "Restaurant a le même sens en anglais.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L33", 'level': 'A1', 'title': "Bus stop et train station", 'subtitle': "Sous-chapitre 6 • Leçon 33/50", 'explanation': "Bus stop signifie arrêt de bus ; train station signifie gare ferroviaire. Pour demander l’emplacement, utilise Where is the…?", 'example': "Where is the bus stop? = Où est l’arrêt de bus ?", 'french': "Où est l’arrêt de bus ?", 'question': "Bus stop signifie…", 'options': <String>["Arrêt de bus", "Gare", "Aéroport"], 'answer': 0, 'correction': "Bus stop est le lieu où le bus s’arrête.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L34", 'level': 'A1', 'title': "Demander Where is the bank?", 'subtitle': "Sous-chapitre 6 • Leçon 34/50", 'explanation': "Pour demander une direction, commence poliment par Excuse me, puis Where is the bank?", 'example': "Excuse me, where is the bank? = Excusez-moi, où est la banque ?", 'french': "Excusez-moi, où est la banque ?", 'question': "Quelle formule rend la demande polie ?", 'options': <String>["Excuse me", "Go away", "Never mind"], 'answer': 0, 'correction': "Excuse me attire poliment l’attention.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L35", 'level': 'A1', 'title': "Comprendre Go straight", 'subtitle': "Sous-chapitre 6 • Leçon 35/50", 'explanation': "Go straight signifie allez tout droit. C’est une instruction fréquente pour donner un itinéraire.", 'example': "Go straight for two blocks. = Allez tout droit pendant deux pâtés de maisons.", 'french': "Allez tout droit pendant deux pâtés de maisons.", 'question': "Go straight signifie…", 'options': <String>["Tournez à gauche", "Allez tout droit", "Arrêtez-vous"], 'answer': 1, 'correction': "Straight signifie tout droit.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L36", 'level': 'A1', 'title': "Comprendre Turn left", 'subtitle': "Sous-chapitre 6 • Leçon 36/50", 'explanation': "Turn left signifie tournez à gauche. Turn est le verbe tourner ; left signifie gauche.", 'example': "Turn left at the corner. = Tournez à gauche au coin.", 'french': "Tournez à gauche au coin.", 'question': "Turn left signifie…", 'options': <String>["Tournez à droite", "Tournez à gauche", "Continuez tout droit"], 'answer': 1, 'correction': "Left signifie gauche.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L37", 'level': 'A1', 'title': "Comprendre Turn right", 'subtitle': "Sous-chapitre 6 • Leçon 37/50", 'explanation': "Turn right signifie tournez à droite. Right peut aussi signifier correct ou droit selon le contexte.", 'example': "Turn right after the bank. = Tournez à droite après la banque.", 'french': "Tournez à droite après la banque.", 'question': "Right signifie dans Turn right…", 'options': <String>["Gauche", "Droite", "Derrière"], 'answer': 1, 'correction': "Dans cette instruction, right signifie droite.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L38", 'level': 'A1', 'title': "At the corner", 'subtitle': "Sous-chapitre 6 • Leçon 38/50", 'explanation': "At the corner signifie au coin, souvent au coin d’une rue. Cette expression aide à donner un itinéraire.", 'example': "The store is at the corner. = Le magasin est au coin.", 'french': "Le magasin est au coin.", 'question': "At the corner signifie…", 'options': <String>["Au coin", "Au sous-sol", "Au milieu de la maison"], 'answer': 0, 'correction': "Corner signifie coin.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L39", 'level': 'A1', 'title': "Across from et opposite", 'subtitle': "Sous-chapitre 6 • Leçon 39/50", 'explanation': "Across from et opposite peuvent signifier en face de. Across from est très courant en anglais américain pour localiser un lieu de l’autre côté.", 'example': "The bank is across from the park. = La banque est en face du parc.", 'french': "La banque est en face du parc.", 'question': "Across from signifie…", 'options': <String>["En face de", "Derrière", "À l’intérieur"], 'answer': 0, 'correction': "Across from indique une position en face.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L40", 'level': 'A1', 'title': "Near et far from", 'subtitle': "Sous-chapitre 6 • Leçon 40/50", 'explanation': "Near signifie près de ; far from signifie loin de. Ces expressions indiquent la distance approximative entre deux lieux.", 'example': "The school is near my house. = L’école est près de chez moi.", 'french': "L’école est près de chez moi.", 'question': "Far from signifie…", 'options': <String>["Près de", "Loin de", "À côté de"], 'answer': 1, 'correction': "Far from indique une grande distance.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L41", 'level': 'A1', 'title': "Question Is it far?", 'subtitle': "Sous-chapitre 6 • Leçon 41/50", 'explanation': "Is it far? signifie « Est-ce loin ? ». C’est une question pratique lorsqu’on demande son chemin.", 'example': "Is it far from here? = Est-ce loin d’ici ?", 'french': "Est-ce loin d’ici ?", 'question': "Quelle question demande si un lieu est loin ?", 'options': <String>["Is it far?", "Is it near school?", "What far?"], 'answer': 0, 'correction': "Far signifie loin.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L42", 'level': 'A1', 'title': "Question How can I get to…?", 'subtitle': "Sous-chapitre 6 • Leçon 42/50", 'explanation': "How can I get to the station? demande comment se rendre à la gare. Cette formule est polie et naturelle.", 'example': "How can I get to the hospital? = Comment puis-je aller à l’hôpital ?", 'french': "Comment puis-je aller à l’hôpital ?", 'question': "Quelle question demande un itinéraire ?", 'options': <String>["How can I get to…?", "How old is…?", "How much is…?"], 'answer': 0, 'correction': "Get to signifie arriver à ou se rendre à dans cette question.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L43", 'level': 'A1', 'title': "Comprendre un itinéraire en deux étapes", 'subtitle': "Sous-chapitre 6 • Leçon 43/50", 'explanation': "Un itinéraire peut contenir plusieurs consignes : go straight, then turn left. Écoute l’ordre des actions pour suivre le trajet.", 'example': "Go straight, then turn right. = Allez tout droit, puis tournez à droite.", 'french': "Allez tout droit, puis tournez à droite.", 'question': "Quel mot indique l’étape suivante ?", 'options': <String>["then", "blue", "because"], 'answer': 0, 'correction': "Then signifie ensuite.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L44", 'level': 'A1', 'title': "Bus et taxi", 'subtitle': "Sous-chapitre 6 • Leçon 44/50", 'explanation': "Bus signifie autobus ; taxi signifie taxi. Pour parler du moyen de transport, on dit take the bus ou take a taxi.", 'example': "I take the bus to school. = Je prends le bus pour aller à l’école.", 'french': "Je prends le bus pour aller à l’école.", 'question': "Comment dire « prendre le bus » ?", 'options': <String>["take the bus", "do the bus", "make bus"], 'answer': 0, 'correction': "Take the bus est l’expression naturelle.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L45", 'level': 'A1', 'title': "Car, bicycle et motorcycle", 'subtitle': "Sous-chapitre 6 • Leçon 45/50", 'explanation': "Car signifie voiture ; bicycle ou bike signifie vélo ; motorcycle signifie moto. Bike est très courant à l’oral pour bicycle.", 'example': "I ride a bicycle. = Je fais du vélo.", 'french': "Je fais du vélo.", 'question': "Motorcycle signifie…", 'options': <String>["Voiture", "Moto", "Autobus"], 'answer': 1, 'correction': "Motorcycle signifie moto.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L46", 'level': 'A1', 'title': "By bus et on foot", 'subtitle': "Sous-chapitre 6 • Leçon 46/50", 'explanation': "Pour indiquer un moyen de transport, on utilise by bus, by car, by train. L’expression est on foot pour « à pied ».", 'example': "I go to school by bus. = Je vais à l’école en bus. / I walk on foot. = J’y vais à pied.", 'french': "J’y vais à pied.", 'question': "Comment dire « en bus » ?", 'options': <String>["by bus", "on bus", "with bus"], 'answer': 0, 'correction': "By précède le moyen de transport ; on foot est une exception courante.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L47", 'level': 'A1', 'title': "Question Which bus goes to…?", 'subtitle': "Sous-chapitre 6 • Leçon 47/50", 'explanation': "Which bus goes to…? demande quel bus va à un endroit. Which signifie lequel ou quel parmi un choix.", 'example': "Which bus goes to the market? = Quel bus va au marché ?", 'french': "Quel bus va au marché ?", 'question': "Which bus goes to… demande…", 'options': <String>["Quel bus va à…", "Combien coûte le bus", "Où est le chauffeur"], 'answer': 0, 'correction': "Which sert à choisir parmi plusieurs options.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L48", 'level': 'A1', 'title': "Comprendre une adresse simple", 'subtitle': "Sous-chapitre 6 • Leçon 48/50", 'explanation': "Une adresse peut contenir un numéro, un nom de rue, une ville et un pays. Lis les éléments dans l’ordre et épelle les noms difficiles si nécessaire.", 'example': "12 Main Street, Dallas. = 12, rue Main, Dallas.", 'french': "12, rue Main, Dallas.", 'question': "Quel élément peut apparaître dans une adresse ?", 'options': <String>["Street", "Breakfast", "Happy"], 'answer': 0, 'correction': "Street est un élément fréquent dans une adresse anglophone.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L49", 'level': 'A1', 'title': "Lire une carte de quartier", 'subtitle': "Sous-chapitre 6 • Leçon 49/50", 'explanation': "Sur une carte, repère les symboles et les noms de lieux. Utilise near, next to, across from et between pour expliquer les positions.", 'example': "The school is next to the park. = L’école est à côté du parc.", 'french': "L’école est à côté du parc.", 'question': "Quelle expression indique que deux endroits sont l’un à côté de l’autre ?", 'options': <String>["À côté de", "Au-dessus de", "Loin de"], 'answer': 0, 'correction': "Next to décrit deux lieux voisins.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U06-L50", 'level': 'A1', 'title': "Révision : suivre un itinéraire", 'subtitle': "Sous-chapitre 6 • Leçon 50/50", 'explanation': "Réutilise les lieux, les prépositions et les consignes de direction pour demander puis suivre un itinéraire simple.", 'example': "Excuse me, where is the library? Go straight and turn left. = Excusez-moi, où est la bibliothèque ? Allez tout droit et tournez à gauche.", 'french': "Excusez-moi, où est la bibliothèque ? Allez tout droit et tournez à gauche.", 'question': "Quelle instruction demande de prendre la direction de gauche ?", 'options': <String>["Tournez à droite", "Tournez à gauche", "Allez tout droit"], 'answer': 1, 'correction': "Left signifie gauche.", 'unit': 6, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L01", 'level': 'A1', 'title': "Water et juice", 'subtitle': "Sous-chapitre 7 • Leçon 1/50", 'explanation': "Water signifie eau ; juice signifie jus. Pour commander, on peut dire water, please ou orange juice, please.", 'example': "Can I have water, please? = Puis-je avoir de l’eau, s’il vous plaît ?", 'french': "Puis-je avoir de l’eau, s’il vous plaît ?", 'question': "Juice signifie…", 'options': <String>["Jus", "Soupe", "Pain"], 'answer': 0, 'correction': "Juice signifie jus.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L02", 'level': 'A1', 'title': "Tea et coffee", 'subtitle': "Sous-chapitre 7 • Leçon 2/50", 'explanation': "Tea signifie thé ; coffee signifie café. Pour commander, ajoute please pour être poli.", 'example': "I drink tea in the morning. = Je bois du thé le matin.", 'french': "Je bois du thé le matin.", 'question': "Coffee signifie…", 'options': <String>["Café", "Thé", "Lait"], 'answer': 0, 'correction': "Coffee signifie café.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L03", 'level': 'A1', 'title': "Milk et autres boissons", 'subtitle': "Sous-chapitre 7 • Leçon 3/50", 'explanation': "Milk signifie lait. D’autres boissons courantes sont soda, lemonade et hot chocolate. Les noms de boissons sont utiles au café et au magasin.", 'example': "I’d like a glass of milk. = Je voudrais un verre de lait.", 'french': "Je voudrais un verre de lait.", 'question': "Milk signifie…", 'options': <String>["Lait", "Jus", "Eau"], 'answer': 0, 'correction': "Milk signifie lait.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L04", 'level': 'A1', 'title': "Bread et rice", 'subtitle': "Sous-chapitre 7 • Leçon 4/50", 'explanation': "Bread signifie pain ; rice signifie riz. En anglais, bread et rice sont généralement indénombrables lorsqu’on parle des aliments en général.", 'example': "I eat bread and rice. = Je mange du pain et du riz.", 'french': "Je mange du pain et du riz.", 'question': "Rice signifie…", 'options': <String>["Riz", "Pain", "Pâtes"], 'answer': 0, 'correction': "Rice signifie riz.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L05", 'level': 'A1', 'title': "Pasta et potatoes", 'subtitle': "Sous-chapitre 7 • Leçon 5/50", 'explanation': "Pasta signifie pâtes ; potato signifie pomme de terre, potatoes au pluriel. Attention à l’orthographe du pluriel en -oes.", 'example': "We have pasta for dinner. = Nous mangeons des pâtes au dîner.", 'french': "Nous mangeons des pâtes au dîner.", 'question': "Potatoes signifie…", 'options': <String>["Pommes de terre", "Tomates", "Carottes"], 'answer': 0, 'correction': "Potatoes est le pluriel de potato.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L06", 'level': 'A1', 'title': "Chicken et fish", 'subtitle': "Sous-chapitre 7 • Leçon 6/50", 'explanation': "Chicken signifie poulet ; fish signifie poisson. Chicken peut désigner la viande ou l’animal selon le contexte.", 'example': "I like chicken and fish. = J’aime le poulet et le poisson.", 'french': "J’aime le poulet et le poisson.", 'question': "Fish signifie…", 'options': <String>["Poisson", "Poulet", "Œuf"], 'answer': 0, 'correction': "Fish signifie poisson.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L07", 'level': 'A1', 'title': "Meat et eggs", 'subtitle': "Sous-chapitre 7 • Leçon 7/50", 'explanation': "Meat signifie viande ; egg signifie œuf, eggs au pluriel. Utilise these foods dans une phrase de repas.", 'example': "I eat eggs for breakfast. = Je mange des œufs au petit-déjeuner.", 'french': "Je mange des œufs au petit-déjeuner.", 'question': "Eggs signifie…", 'options': <String>["Œufs", "Pain", "Fruits"], 'answer': 0, 'correction': "Eggs est le pluriel de egg.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L08", 'level': 'A1', 'title': "Beans et vegetables", 'subtitle': "Sous-chapitre 7 • Leçon 8/50", 'explanation': "Beans signifie haricots ; vegetables signifie légumes. Vegetable est le singulier, vegetables le pluriel courant.", 'example': "I eat vegetables every day. = Je mange des légumes chaque jour.", 'french': "Je mange des légumes chaque jour.", 'question': "Vegetables signifie…", 'options': <String>["Légumes", "Boissons", "Desserts"], 'answer': 0, 'correction': "Vegetables signifie légumes.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L09", 'level': 'A1', 'title': "Fruits courants", 'subtitle': "Sous-chapitre 7 • Leçon 9/50", 'explanation': "Fruit est le mot général pour fruit ; les noms courants incluent apple, banana, orange, mango et pineapple.", 'example': "I like mangoes. = J’aime les mangues.", 'french': "J’aime les mangues.", 'question': "Banana signifie…", 'options': <String>["Banane", "Pomme", "Orange"], 'answer': 0, 'correction': "Banana signifie banane.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L10", 'level': 'A1', 'title': "Apple, banana et orange", 'subtitle': "Sous-chapitre 7 • Leçon 10/50", 'explanation': "Apple signifie pomme ; banana banane ; orange orange. Utilise an devant apple et orange, mais a devant banana.", 'example': "an apple, a banana, an orange.", 'french': "an apple, a banana, an orange.", 'question': "Quel article convient devant le mot apple dans cette expression ?", 'options': <String>["a apple", "an apple", "an banana"], 'answer': 1, 'correction': "Apple commence par un son voyelle, donc an.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L11", 'level': 'A1', 'title': "Breakfast foods", 'subtitle': "Sous-chapitre 7 • Leçon 11/50", 'explanation': "Breakfast foods incluent eggs, bread, cereal, fruit et oatmeal. On dit have breakfast pour prendre le petit-déjeuner.", 'example': "I have eggs for breakfast. = Je mange des œufs au petit-déjeuner.", 'french': "Je mange des œufs au petit-déjeuner.", 'question': "Breakfast signifie…", 'options': <String>["Petit-déjeuner", "Dîner", "Goûter"], 'answer': 0, 'correction': "Breakfast est le repas du matin.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L12", 'level': 'A1', 'title': "Lunch et dinner", 'subtitle': "Sous-chapitre 7 • Leçon 12/50", 'explanation': "Lunch signifie déjeuner ; dinner signifie dîner ou repas principal selon le contexte. On dit have lunch et have dinner.", 'example': "We have lunch at noon. = Nous déjeunons à midi.", 'french': "Nous déjeunons à midi.", 'question': "Lunch signifie…", 'options': <String>["Déjeuner", "Petit-déjeuner", "Dîner uniquement"], 'answer': 0, 'correction': "Lunch est le repas du milieu de journée.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L13", 'level': 'A1', 'title': "Snacks et dessert", 'subtitle': "Sous-chapitre 7 • Leçon 13/50", 'explanation': "Snack signifie collation ou petit encas ; dessert signifie dessert. Ces mots sont utiles pour parler des habitudes alimentaires.", 'example': "I eat a snack after school. = Je prends un encas après l’école.", 'french': "Je prends un encas après l’école.", 'question': "Dessert signifie…", 'options': <String>["Dessert", "Dîner", "Petit-déjeuner"], 'answer': 0, 'correction': "Dessert est le dernier plat sucré d’un repas.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L14", 'level': 'A1', 'title': "Hungry et thirsty", 'subtitle': "Sous-chapitre 7 • Leçon 14/50", 'explanation': "Hungry signifie avoir faim ; thirsty signifie avoir soif. On utilise be : I’m hungry, I’m thirsty.", 'example': "I’m thirsty. Can I have water? = J’ai soif. Puis-je avoir de l’eau ?", 'french': "J’ai soif. Puis-je avoir de l’eau ?", 'question': "Thirsty signifie…", 'options': <String>["Avoir faim", "Avoir soif", "Être fatigué"], 'answer': 1, 'correction': "Thirsty signifie avoir soif.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L15", 'level': 'A1', 'title': "Dire I’m hungry et I’m thirsty", 'subtitle': "Sous-chapitre 7 • Leçon 15/50", 'explanation': "Ces expressions décrivent un besoin physique. Utilise I’m + hungry/thirsty, puis demande poliment quelque chose à manger ou à boire.", 'example': "I’m hungry. I’d like a sandwich. = J’ai faim. Je voudrais un sandwich.", 'french': "J’ai faim. Je voudrais un sandwich.", 'question': "Quelle phrase signifie « J’ai faim » ?", 'options': <String>["I’m hungry.", "I have hungry.", "I hungry am."], 'answer': 0, 'correction': "Hungry est un adjectif ; utilise le verbe be.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L16", 'level': 'A1', 'title': "Exprimer ses goûts avec I like", 'subtitle': "Sous-chapitre 7 • Leçon 16/50", 'explanation': "I like + nom sert à exprimer un goût. Pour une activité, on peut dire I like + verbe en -ing.", 'example': "I like apples. = J’aime les pommes.", 'french': "J’aime les pommes.", 'question': "Comment dire « J’aime les pommes » ?", 'options': <String>["I like apples.", "I likes apples.", "I am like apples."], 'answer': 0, 'correction': "Avec I, on utilise like sans -s.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L17", 'level': 'A1', 'title': "Exprimer un dégoût avec I don’t like", 'subtitle': "Sous-chapitre 7 • Leçon 17/50", 'explanation': "I don’t like signifie je n’aime pas. Après don’t, le verbe reste à la base : don’t like, et non don’t likes.", 'example': "I don’t like coffee. = Je n’aime pas le café.", 'french': "Je n’aime pas le café.", 'question': "Complète : I don’t ___ fish.", 'options': <String>["likes", "like", "liking"], 'answer': 1, 'correction': "Après don’t, utilise la base verbale like.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L18", 'level': 'A1', 'title': "Question Do you like…?", 'subtitle': "Sous-chapitre 7 • Leçon 18/50", 'explanation': "Do you like…? demande si quelqu’un aime quelque chose. Réponds Yes, I do ou No, I don’t.", 'example': "Do you like tea? — Yes, I do. = Aimes-tu le thé ? — Oui.", 'french': "Aimes-tu le thé ? — Oui.", 'question': "Quelle question demande si quelqu’un aime le thé ?", 'options': <String>["Do you like tea?", "Are you like tea?", "Does you like tea?"], 'answer': 0, 'correction': "Avec you, on utilise do.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L19", 'level': 'A1', 'title': "Some dans une demande polie", 'subtitle': "Sous-chapitre 7 • Leçon 19/50", 'explanation': "Some signifie un peu de ou quelques. Il est fréquent dans les offres et demandes polies : some water, some bread.", 'example': "Can I have some water, please? = Puis-je avoir de l’eau, s’il vous plaît ?", 'french': "Puis-je avoir de l’eau, s’il vous plaît ?", 'question': "Some water signifie…", 'options': <String>["Un peu d’eau / de l’eau", "Toute l’eau du monde", "Une eau"], 'answer': 0, 'correction': "Some s’utilise naturellement dans cette demande.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L20", 'level': 'A1', 'title': "Noms dénombrables", 'subtitle': "Sous-chapitre 7 • Leçon 20/50", 'explanation': "Un nom dénombrable peut être compté : one apple, two apples. Il a un singulier et un pluriel.", 'example': "three eggs = trois œufs.", 'french': "trois œufs.", 'question': "Lequel est dénombrable ?", 'options': <String>["apple", "water", "rice"], 'answer': 0, 'correction': "On peut compter les pommes une par une.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L21", 'level': 'A1', 'title': "Noms indénombrables courants", 'subtitle': "Sous-chapitre 7 • Leçon 21/50", 'explanation': "Certains noms sont généralement indénombrables : water, rice, bread, milk. On ne dit pas normalement one water pour parler de l’aliment en général.", 'example': "some water = de l’eau ; a glass of water = un verre d’eau.", 'french': "de l’eau ; a glass of water = un verre d’eau.", 'question': "Lequel est généralement indénombrable ?", 'options': <String>["apple", "water", "egg"], 'answer': 1, 'correction': "Water est généralement indénombrable.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L22", 'level': 'A1', 'title': "A piece of", 'subtitle': "Sous-chapitre 7 • Leçon 22/50", 'explanation': "A piece of signifie un morceau de. Cette expression permet de compter certains noms indénombrables comme bread ou cake.", 'example': "a piece of cake = un morceau de gâteau.", 'french': "un morceau de gâteau.", 'question': "Comment dire « un morceau de gâteau » ?", 'options': <String>["a cake of piece", "a piece of cake", "a piece cake"], 'answer': 1, 'correction': "La structure est a piece of + nom.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L23", 'level': 'A1', 'title': "A glass of et a cup of", 'subtitle': "Sous-chapitre 7 • Leçon 23/50", 'explanation': "A glass of s’utilise pour un verre de ; a cup of pour une tasse de. Le récipient permet de quantifier une boisson.", 'example': "a glass of water = un verre d’eau ; a cup of tea = une tasse de thé.", 'french': "un verre d’eau ; a cup of tea = une tasse de thé.", 'question': "Une tasse de thé se dit…", 'options': <String>["a glass tea", "a cup of tea", "a cup tea"], 'answer': 1, 'correction': "Cup signifie tasse et of relie la quantité à la boisson.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L24", 'level': 'A1', 'title': "A bottle of", 'subtitle': "Sous-chapitre 7 • Leçon 24/50", 'explanation': "A bottle of signifie une bouteille de. On peut dire a bottle of water ou a bottle of juice.", 'example': "I need a bottle of water. = J’ai besoin d’une bouteille d’eau.", 'french': "J’ai besoin d’une bouteille d’eau.", 'question': "Comment dire « une bouteille d’eau » ?", 'options': <String>["a bottle water", "a bottle of water", "a water bottle of"], 'answer': 1, 'correction': "La structure est a bottle of + contenu.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L25", 'level': 'A1', 'title': "Question How much…?", 'subtitle': "Sous-chapitre 7 • Leçon 25/50", 'explanation': "How much sert à demander la quantité d’un nom indénombrable ou le prix. Le contexte indique le sens.", 'example': "How much water do you drink? = Quelle quantité d’eau bois-tu ?", 'french': "Quelle quantité d’eau bois-tu ?", 'question': "How much peut demander…", 'options': <String>["Une quantité indénombrable", "Le pluriel d’un nom dénombrable uniquement", "Un jour de la semaine"], 'answer': 0, 'correction': "How much s’utilise avec des noms indénombrables et pour les prix.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L26", 'level': 'A1', 'title': "Question How many…?", 'subtitle': "Sous-chapitre 7 • Leçon 26/50", 'explanation': "How many sert à demander le nombre d’éléments dénombrables au pluriel.", 'example': "How many apples do you want? = Combien de pommes veux-tu ?", 'french': "Combien de pommes veux-tu ?", 'question': "Quelle question demande combien de pommes quelqu’un veut ?", 'options': <String>["How many apples?", "How much apples?", "How many water?"], 'answer': 0, 'correction': "Apples est dénombrable et pluriel, donc how many.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L27", 'level': 'A1', 'title': "Lire un prix simple", 'subtitle': "Sous-chapitre 7 • Leçon 27/50", 'explanation': "Pour lire un prix, repère la devise et les nombres. En dollars américains, \$4.50 se lit four dollars and fifty cents ou four fifty dans un contexte informel.", 'example': "It’s four dollars. = Cela coûte quatre dollars.", 'french': "Cela coûte quatre dollars.", 'question': "\$4.50 signifie…", 'options': <String>["Quatre dollars et cinquante cents", "Quarante-cinq dollars", "Quatre cents"], 'answer': 0, 'correction': "Le point sépare les dollars des cents dans cette notation.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L28", 'level': 'A1', 'title': "Dollars et cents dans les prix", 'subtitle': "Sous-chapitre 7 • Leçon 28/50", 'explanation': "Dollar est l’unité monétaire ; cent est un centième de dollar. Un prix de \$1.25 vaut un dollar et vingt-cinq cents.", 'example': "It costs one dollar and twenty-five cents. = Cela coûte un dollar vingt-cinq.", 'french': "Cela coûte un dollar vingt-cinq.", 'question': "25 cents est…", 'options': <String>["Un quart de dollar", "25 dollars", "Deux dollars"], 'answer': 0, 'correction': "Cent représente un centième de dollar.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L29", 'level': 'A1', 'title': "Question How much is it?", 'subtitle': "Sous-chapitre 7 • Leçon 29/50", 'explanation': "How much is it? demande combien coûte un article. On répond It’s five dollars ou It costs five dollars.", 'example': "How much is it? — It’s five dollars. = Combien ça coûte ? — Cinq dollars.", 'french': "Combien ça coûte ? — Cinq dollars.", 'question': "Quelle question demande le prix ?", 'options': <String>["How much is it?", "How old is it?", "How many is it?"], 'answer': 0, 'correction': "How much is it est une question de prix courante.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L30", 'level': 'A1', 'title': "Question How much are these?", 'subtitle': "Sous-chapitre 7 • Leçon 30/50", 'explanation': "Pour demander le prix de plusieurs objets, on peut dire How much are these? These est pluriel, donc le verbe est are.", 'example': "How much are these apples? = Combien coûtent ces pommes ?", 'french': "Combien coûtent ces pommes ?", 'question': "Quelle forme convient pour plusieurs objets ?", 'options': <String>["How much is these?", "How much are these?", "How many are this?"], 'answer': 1, 'correction': "These est pluriel et prend are.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L31", 'level': 'A1', 'title': "Cheap et expensive", 'subtitle': "Sous-chapitre 7 • Leçon 31/50", 'explanation': "Cheap signifie bon marché ; expensive signifie cher. Ces adjectifs servent à comparer les prix.", 'example': "This phone is expensive. = Ce téléphone est cher.", 'french': "Ce téléphone est cher.", 'question': "Cheap signifie…", 'options': <String>["Cher", "Bon marché", "Gratuit"], 'answer': 1, 'correction': "Cheap signifie bon marché, pas nécessairement gratuit.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L32", 'level': 'A1', 'title': "Demander le prix poliment", 'subtitle': "Sous-chapitre 7 • Leçon 32/50", 'explanation': "Pour demander le prix, utilise How much is this? ou How much does it cost? Ajoute Excuse me pour attirer poliment l’attention.", 'example': "Excuse me, how much is this? = Excusez-moi, combien coûte ceci ?", 'french': "Excusez-moi, combien coûte ceci ?", 'question': "Quelle expression est une demande polie de prix ?", 'options': <String>["How much is this?", "Give me price!", "Price where?"], 'answer': 0, 'correction': "La structure est naturelle et polie.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L33", 'level': 'A1', 'title': "I’d like…", 'subtitle': "Sous-chapitre 7 • Leçon 33/50", 'explanation': "I’d like est la contraction de I would like et signifie je voudrais. C’est une formule polie pour commander ou demander quelque chose.", 'example': "I’d like a sandwich, please. = Je voudrais un sandwich, s’il vous plaît.", 'french': "Je voudrais un sandwich, s’il vous plaît.", 'question': "I’d like signifie…", 'options': <String>["Je voudrais", "J’ai aimé hier", "Je dois"], 'answer': 0, 'correction': "I’d like est plus poli que I want dans de nombreuses commandes.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L34", 'level': 'A1', 'title': "Can I have…?", 'subtitle': "Sous-chapitre 7 • Leçon 34/50", 'explanation': "Can I have…? signifie puis-je avoir…? C’est une formule courante pour demander un objet, une boisson ou un service.", 'example': "Can I have the menu, please? = Puis-je avoir le menu, s’il vous plaît ?", 'french': "Puis-je avoir le menu, s’il vous plaît ?", 'question': "Quelle formule demande poliment un menu ?", 'options': <String>["Can I have the menu, please?", "I menu have.", "Give menu now."], 'answer': 0, 'correction': "Can I have est une demande polie courante.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L35", 'level': 'A1', 'title': "Commander une boisson", 'subtitle': "Sous-chapitre 7 • Leçon 35/50", 'explanation': "Pour commander, dis I’d like a coffee, please ou Can I have some water? Écoute aussi les questions du serveur.", 'example': "I’d like an orange juice, please. = Je voudrais un jus d’orange, s’il vous plaît.", 'french': "Je voudrais un jus d’orange, s’il vous plaît.", 'question': "Quelle phrase commande poliment un café ?", 'options': <String>["I’d like a coffee, please.", "I coffee want now.", "Coffee me."], 'answer': 0, 'correction': "I’d like + article + boisson est une structure naturelle.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L36", 'level': 'A1', 'title': "Commander un repas simple", 'subtitle': "Sous-chapitre 7 • Leçon 36/50", 'explanation': "Au restaurant, utilise I’d like… ou Can I have…? pour commander un plat. Ajoute please et thank you.", 'example': "I’d like the chicken, please. = Je voudrais le poulet, s’il vous plaît.", 'french': "Je voudrais le poulet, s’il vous plaît.", 'question': "Quelle phrase commande un plat poliment ?", 'options': <String>["I’d like the chicken, please.", "I chicken want.", "Give chicken!"], 'answer': 0, 'correction': "I’d like est une demande polie.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L37", 'level': 'A1', 'title': "Demander the menu", 'subtitle': "Sous-chapitre 7 • Leçon 37/50", 'explanation': "The menu signifie le menu. Pour le demander, dis Could I see the menu, please? ou Can I have the menu, please?", 'example': "Could I see the menu, please? = Pourrais-je voir le menu, s’il vous plaît ?", 'french': "Pourrais-je voir le menu, s’il vous plaît ?", 'question': "Menu signifie…", 'options': <String>["Menu", "Facture", "Cuisine"], 'answer': 0, 'correction': "Menu a le même sens en anglais.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L38", 'level': 'A1', 'title': "Demander the bill", 'subtitle': "Sous-chapitre 7 • Leçon 38/50", 'explanation': "The bill signifie l’addition dans un restaurant ; aux États-Unis, check est aussi très courant.", 'example': "Could we have the check, please? = Pourrions-nous avoir l’addition, s’il vous plaît ?", 'french': "Pourrions-nous avoir l’addition, s’il vous plaît ?", 'question': "Dans un restaurant américain, check peut signifier…", 'options': <String>["Addition", "Menu", "Cuisine"], 'answer': 0, 'correction': "Check est un mot américain courant pour l’addition.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L39", 'level': 'A1', 'title': "For here or to go?", 'subtitle': "Sous-chapitre 7 • Leçon 39/50", 'explanation': "Cette question signifie « sur place ou à emporter ? ». For here veut dire sur place ; to go signifie à emporter.", 'example': "For here, please. = Sur place, s’il vous plaît.", 'french': "Sur place, s’il vous plaît.", 'question': "To go signifie…", 'options': <String>["Sur place", "À emporter", "À payer"], 'answer': 1, 'correction': "Dans une commande, to go signifie à emporter.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L40", 'level': 'A1', 'title': "Comprendre Here you go", 'subtitle': "Sous-chapitre 7 • Leçon 40/50", 'explanation': "Here you go est une formule utilisée lorsqu’on remet quelque chose à quelqu’un, comme une boisson ou un ticket. Elle signifie approximativement « voilà ».", 'example': "Here you go. = Voilà.", 'french': "Voilà.", 'question': "Que peut dire le serveur en te donnant ta boisson ?", 'options': <String>["Here you go.", "Where you go?", "Go here now."], 'answer': 0, 'correction': "C’est une formule naturelle pour remettre un objet.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L41", 'level': 'A1', 'title': "Anything else? et réponse", 'subtitle': "Sous-chapitre 7 • Leçon 41/50", 'explanation': "Anything else? signifie « autre chose ? ». On peut répondre No, that’s all, thank you ou Yes, please.", 'example': "Anything else? — No, that’s all, thanks. = Autre chose ? — Non, ce sera tout, merci.", 'french': "Autre chose ? — Non, ce sera tout, merci.", 'question': "Que signifie Anything else?", 'options': <String>["Autre chose ?", "Où est-ce ?", "Combien ça coûte ?"], 'answer': 0, 'correction': "Else signifie autre dans cette question.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L42", 'level': 'A1', 'title': "Demander un plat sans ingrédient", 'subtitle': "Sous-chapitre 7 • Leçon 42/50", 'explanation': "Pour signaler une préférence, dis Can I have this without onions? Pour une allergie, sois clair : I’m allergic to peanuts.", 'example': "Can I have it without onions? = Puis-je l’avoir sans oignons ?", 'french': "Puis-je l’avoir sans oignons ?", 'question': "Without signifie…", 'options': <String>["Avec", "Sans", "Avant"], 'answer': 1, 'correction': "Without indique l’absence d’un ingrédient.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L43", 'level': 'A1', 'title': "Dire I’m allergic to…", 'subtitle': "Sous-chapitre 7 • Leçon 43/50", 'explanation': "I’m allergic to… signifie « Je suis allergique à… ». Cette phrase est importante pour communiquer un risque alimentaire ; indique l’ingrédient précisément.", 'example': "I’m allergic to peanuts. = Je suis allergique aux arachides.", 'french': "Je suis allergique aux arachides.", 'question': "Comment dire « Je suis allergique au lait » ?", 'options': <String>["I’m allergic to milk.", "I allergic milk.", "I’m allergy milk."], 'answer': 0, 'correction': "La structure est I’m allergic to + ingrédient.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L44", 'level': 'A1', 'title': "Store et shop", 'subtitle': "Sous-chapitre 7 • Leçon 44/50", 'explanation': "Store signifie magasin en anglais américain ; shop est aussi courant, notamment pour un type de commerce ou en anglais britannique.", 'example': "I’m going to the store. = Je vais au magasin.", 'french': "Je vais au magasin.", 'question': "Store signifie…", 'options': <String>["Magasin", "École", "Parc"], 'answer': 0, 'correction': "Store est très courant en anglais américain.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L45", 'level': 'A1', 'title': "Lire une liste de courses", 'subtitle': "Sous-chapitre 7 • Leçon 45/50", 'explanation': "Une shopping list contient des produits à acheter. Repère les quantités et les noms d’aliments ; coche chaque article acheté.", 'example': "We need milk, bread and eggs. = Nous avons besoin de lait, de pain et d’œufs.", 'french': "Nous avons besoin de lait, de pain et d’œufs.", 'question': "Shopping list signifie…", 'options': <String>["Liste de courses", "Carte scolaire", "Menu de restaurant"], 'answer': 0, 'correction': "Shopping list est une liste de produits à acheter.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L46", 'level': 'A1', 'title': "Question Where can I find…?", 'subtitle': "Sous-chapitre 7 • Leçon 46/50", 'explanation': "Where can I find…? signifie « Où puis-je trouver… ? ». C’est utile dans un magasin pour demander un produit.", 'example': "Where can I find the rice? = Où puis-je trouver le riz ?", 'french': "Où puis-je trouver le riz ?", 'question': "Quelle question demande où trouver un produit ?", 'options': <String>["Where can I find…?", "How much am I?", "When do I find?"], 'answer': 0, 'correction': "Where demande un lieu ; can I find signifie puis-je trouver.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L47", 'level': 'A1', 'title': "Buy, pay et cost", 'subtitle': "Sous-chapitre 7 • Leçon 47/50", 'explanation': "Buy signifie acheter ; pay signifie payer ; cost signifie coûter. Le passé de buy est bought et celui de pay est paid.", 'example': "I buy fruit. It costs two dollars. I pay cash. = J’achète des fruits. Cela coûte deux dollars. Je paie en espèces.", 'french': "J’achète des fruits. Cela coûte deux dollars. Je paie en espèces.", 'question': "Cost signifie…", 'options': <String>["Acheter", "Payer", "Coûter"], 'answer': 2, 'correction': "Cost signifie coûter.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L48", 'level': 'A1', 'title': "Receipt et change", 'subtitle': "Sous-chapitre 7 • Leçon 48/50", 'explanation': "Receipt signifie reçu ou ticket de caisse ; change signifie monnaie rendue après un paiement, ou changement selon le contexte.", 'example': "Can I have the receipt? = Puis-je avoir le reçu ?", 'french': "Puis-je avoir le reçu ?", 'question': "Receipt signifie…", 'options': <String>["Reçu", "Prix", "Sac"], 'answer': 0, 'correction': "Receipt est le justificatif d’achat.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L49", 'level': 'A1', 'title': "Dialogue client-vendeur", 'subtitle': "Sous-chapitre 7 • Leçon 49/50", 'explanation': "Un dialogue d’achat peut contenir une salutation, une demande de prix, un choix, un paiement et un remerciement. Réutilise les expressions polies.", 'example': "How much is this? — It’s five dollars. — I’ll take it, please. = Combien ça coûte ? — Cinq dollars. — Je le prends, s’il vous plaît.", 'french': "Combien ça coûte ? — Cinq dollars. — Je le prends, s’il vous plaît.", 'question': "Quelle phrase signifie « Je le prends » ?", 'options': <String>["I’ll take it.", "I cost it.", "I pay it tomorrow always."], 'answer': 0, 'correction': "I’ll take it exprime une décision d’achat.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U07-L50", 'level': 'A1', 'title': "Révision : acheter et payer", 'subtitle': "Sous-chapitre 7 • Leçon 50/50", 'explanation': "Réutilise les nombres, les prix, les demandes polies et les expressions de paiement dans une situation complète.", 'example': "Excuse me, how much is this? — It’s three dollars. — I’ll take it. Can I have the receipt, please?", 'french': "Excuse me, how much is this? — It’s three dollars. — I’ll take it. Can I have the receipt, please?", 'question': "Quelle phrase demande le reçu ?", 'options': <String>["Can I have the receipt, please?", "How old is the receipt?", "Where is my price?"], 'answer': 0, 'correction': "Cette structure est une demande polie.", 'unit': 7, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L01", 'level': 'A1', 'title': "Classroom et objets de classe", 'subtitle': "Sous-chapitre 8 • Leçon 1/50", 'explanation': "Classroom signifie salle de classe. Les objets courants sont desk, chair, board, notebook, pencil et eraser.", 'example': "The classroom is big. = La salle de classe est grande.", 'french': "La salle de classe est grande.", 'question': "Classroom signifie…", 'options': <String>["Salle de classe", "Bureau", "Couloir"], 'answer': 0, 'correction': "Classroom est le lieu où les élèves suivent le cours.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L02", 'level': 'A1', 'title': "Teacher et student", 'subtitle': "Sous-chapitre 8 • Leçon 2/50", 'explanation': "Teacher signifie enseignant ou professeur ; student signifie élève ou étudiant selon le contexte.", 'example': "The teacher helps the students. = Le professeur aide les élèves.", 'french': "Le professeur aide les élèves.", 'question': "Student signifie…", 'options': <String>["Élève / étudiant", "Professeur", "Parent"], 'answer': 0, 'correction': "Student désigne une personne qui apprend.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L03", 'level': 'A1', 'title': "Subject et lesson", 'subtitle': "Sous-chapitre 8 • Leçon 3/50", 'explanation': "Subject signifie matière scolaire ; lesson signifie leçon. Subject peut aussi avoir d’autres sens, mais à l’école il désigne une matière.", 'example': "English is my favorite subject. = L’anglais est ma matière préférée.", 'french': "L’anglais est ma matière préférée.", 'question': "Subject signifie à l’école…", 'options': <String>["Matière", "Récréation", "Chaise"], 'answer': 0, 'correction': "Subject désigne une matière scolaire dans cet exemple.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L04", 'level': 'A1', 'title': "English class", 'subtitle': "Sous-chapitre 8 • Leçon 4/50", 'explanation': "English class signifie cours d’anglais. On peut dire I have English class today ou My English class starts at nine.", 'example': "I have English class today. = J’ai cours d’anglais aujourd’hui.", 'french': "J’ai cours d’anglais aujourd’hui.", 'question': "English class signifie…", 'options': <String>["Cours d’anglais", "Livre d’anglais", "Professeur d’anglais uniquement"], 'answer': 0, 'correction': "Class peut signifier classe ou cours.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L05", 'level': 'A1', 'title': "Maths et science", 'subtitle': "Sous-chapitre 8 • Leçon 5/50", 'explanation': "Math signifie mathématiques en anglais américain ; maths est courant en anglais britannique. Science signifie sciences.", 'example': "I like science. = J’aime les sciences.", 'french': "J’aime les sciences.", 'question': "Science signifie…", 'options': <String>["Sciences", "Histoire", "Musique"], 'answer': 0, 'correction': "Science désigne les sciences comme matière.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L06", 'level': 'A1', 'title': "Utiliser have a class", 'subtitle': "Sous-chapitre 8 • Leçon 6/50", 'explanation': "Have a class signifie avoir un cours. Au présent, on utilise have avec I/you/we/they et has avec he/she/it.", 'example': "I have a class at ten. = J’ai un cours à dix heures.", 'french': "J’ai un cours à dix heures.", 'question': "She ___ a class today.", 'options': <String>["have", "has", "having"], 'answer': 1, 'correction': "Avec she au présent simple, on utilise has.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L07", 'level': 'A1', 'title': "Comprendre Open your book", 'subtitle': "Sous-chapitre 8 • Leçon 7/50", 'explanation': "Open your book est une consigne qui signifie « Ouvre ton livre ». L’impératif utilise la base verbale sans sujet exprimé.", 'example': "Open your book, please. = Ouvre ton livre, s’il te plaît.", 'french': "Ouvre ton livre, s’il te plaît.", 'question': "Que signifie Open your book?", 'options': <String>["Ferme ton livre", "Ouvre ton livre", "Lis ton livre"], 'answer': 1, 'correction': "Open signifie ouvrir.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L08", 'level': 'A1', 'title': "Comprendre Close your notebook", 'subtitle': "Sous-chapitre 8 • Leçon 8/50", 'explanation': "Close your notebook signifie « Ferme ton cahier ». Close est la base verbale à l’impératif.", 'example': "Close your notebook. = Ferme ton cahier.", 'french': "Ferme ton cahier.", 'question': "Close signifie…", 'options': <String>["Ouvrir", "Fermer", "Écrire"], 'answer': 1, 'correction': "Close signifie fermer.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L09", 'level': 'A1', 'title': "Comprendre Write your answer", 'subtitle': "Sous-chapitre 8 • Leçon 9/50", 'explanation': "Write your answer signifie « Écris ta réponse ». Write est la base verbale utilisée dans une consigne directe.", 'example': "Write your answer in English. = Écris ta réponse en anglais.", 'french': "Écris ta réponse en anglais.", 'question': "Write your answer signifie…", 'options': <String>["Lis ta réponse", "Écris ta réponse", "Écoute ta réponse"], 'answer': 1, 'correction': "Write signifie écrire.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L10", 'level': 'A1', 'title': "Comprendre Work in pairs", 'subtitle': "Sous-chapitre 8 • Leçon 10/50", 'explanation': "Work in pairs signifie « Travaillez par deux ». Pair signifie paire ou binôme ; in pairs indique la manière de travailler.", 'example': "Work in pairs, please. = Travaillez par deux, s’il vous plaît.", 'french': "Travaillez par deux, s’il vous plaît.", 'question': "Work in pairs signifie…", 'options': <String>["Travaillez seuls", "Travaillez par deux", "Travaillez dehors"], 'answer': 1, 'correction': "Pair signifie une paire de personnes.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L11", 'level': 'A1', 'title': "Demander Can you help me?", 'subtitle': "Sous-chapitre 8 • Leçon 11/50", 'explanation': "Can you help me? signifie « Peux-tu m’aider ? ». C’est une demande courante ; please peut la rendre plus polie.", 'example': "Can you help me, please? = Peux-tu m’aider, s’il te plaît ?", 'french': "Peux-tu m’aider, s’il te plaît ?", 'question': "Quelle phrase demande de l’aide ?", 'options': <String>["Can you help me?", "Can you hear me?", "Can you see me?"], 'answer': 0, 'correction': "Help signifie aider.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L12", 'level': 'A1', 'title': "Demander What page are we on?", 'subtitle': "Sous-chapitre 8 • Leçon 12/50", 'explanation': "What page are we on? demande à quelle page la classe est arrivée. Page signifie page ; on est utilisé dans cette expression.", 'example': "What page are we on? = Nous sommes à quelle page ?", 'french': "Nous sommes à quelle page ?", 'question': "Quelle question demande la page du livre ?", 'options': <String>["What page are we on?", "What book are you?", "Where page it?"], 'answer': 0, 'correction': "Cette expression est naturelle pour suivre une leçon.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L13", 'level': 'A1', 'title': "Dire I have a question", 'subtitle': "Sous-chapitre 8 • Leçon 13/50", 'explanation': "I have a question signifie « J’ai une question ». Have signifie avoir ; cette phrase permet d’intervenir en classe.", 'example': "Excuse me, I have a question. = Excusez-moi, j’ai une question.", 'french': "Excusez-moi, j’ai une question.", 'question': "Question signifie…", 'options': <String>["Question", "Réponse", "Leçon"], 'answer': 0, 'correction': "Question signifie question.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L14", 'level': 'A1', 'title': "Demander How do you spell it?", 'subtitle': "Sous-chapitre 8 • Leçon 14/50", 'explanation': "How do you spell it? demande comment épeler un mot. Spell signifie épeler ; it remplace le mot mentionné.", 'example': "How do you spell “friend”? = Comment épelle-t-on friend ?", 'french': "Comment épelle-t-on friend ?", 'question': "Spell signifie…", 'options': <String>["Épeler", "Prononcer", "Traduire"], 'answer': 0, 'correction': "Spell concerne les lettres du mot.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L15", 'level': 'A1', 'title': "Parler de homework", 'subtitle': "Sous-chapitre 8 • Leçon 15/50", 'explanation': "Homework signifie devoirs à faire à la maison. En anglais, homework est généralement indénombrable : on dit some homework, pas homeworks.", 'example': "I have homework tonight. = J’ai des devoirs ce soir.", 'french': "J’ai des devoirs ce soir.", 'question': "Homework signifie…", 'options': <String>["Devoirs à la maison", "Cours en classe", "Vacances"], 'answer': 0, 'correction': "Homework est généralement indénombrable.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L16", 'level': 'A1', 'title': "Test et exam", 'subtitle': "Sous-chapitre 8 • Leçon 16/50", 'explanation': "Test signifie test ou contrôle ; exam est une forme courte de examination, examen. Le contexte scolaire aide à comprendre le niveau de l’évaluation.", 'example': "I have an exam tomorrow. = J’ai un examen demain.", 'french': "J’ai un examen demain.", 'question': "Exam signifie…", 'options': <String>["Examen", "Exemple", "Explication"], 'answer': 0, 'correction': "Exam est une forme courte courante de examination.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L17", 'level': 'A1', 'title': "Pass et fail avec tact", 'subtitle': "Sous-chapitre 8 • Leçon 17/50", 'explanation': "Pass signifie réussir un examen ; fail signifie échouer. Ces mots décrivent un résultat, pas la valeur d’une personne.", 'example': "I passed the test. = J’ai réussi le test.", 'french': "J’ai réussi le test.", 'question': "Pass signifie dans un examen…", 'options': <String>["Réussir", "Oublier", "Réviser"], 'answer': 0, 'correction': "Passer/réussir un test se dit pass the test.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L18", 'level': 'A1', 'title': "Dire I’m ready", 'subtitle': "Sous-chapitre 8 • Leçon 18/50", 'explanation': "I’m ready signifie « Je suis prêt ». Ready est un adjectif qui suit le verbe be.", 'example': "I’m ready to start. = Je suis prêt à commencer.", 'french': "Je suis prêt à commencer.", 'question': "Ready signifie…", 'options': <String>["Prêt", "En retard", "Triste"], 'answer': 0, 'correction': "Ready décrit l’état d’être prêt.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L19", 'level': 'A1', 'title': "Dire I know et I don’t know", 'subtitle': "Sous-chapitre 8 • Leçon 19/50", 'explanation': "I know signifie je sais ; I don’t know signifie je ne sais pas. Ces expressions sont fréquentes dans les réponses.", 'example': "I don’t know the answer. = Je ne connais pas la réponse.", 'french': "Je ne connais pas la réponse.", 'question': "Comment dire « Je ne sais pas » ?", 'options': <String>["I no know.", "I don’t know.", "I doesn’t know."], 'answer': 1, 'correction': "La négation avec I utilise don’t + know.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L20", 'level': 'A1', 'title': "Parler de hobbies", 'subtitle': "Sous-chapitre 8 • Leçon 20/50", 'explanation': "Hobby signifie loisir ; hobbies est le pluriel. On peut dire My hobbies are music and football.", 'example': "My hobby is drawing. = Mon loisir est le dessin.", 'french': "Mon loisir est le dessin.", 'question': "Hobbies signifie…", 'options': <String>["Loisirs", "Devoirs", "Matières"], 'answer': 0, 'correction': "Hobbies est le pluriel de hobby.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L21", 'level': 'A1', 'title': "Music et singing", 'subtitle': "Sous-chapitre 8 • Leçon 21/50", 'explanation': "Music signifie musique ; singing signifie le chant ou le fait de chanter. On peut dire I like music ou I like singing.", 'example': "I love music. = J’adore la musique.", 'french': "J’adore la musique.", 'question': "Singing signifie…", 'options': <String>["Chanter / le chant", "Danser", "Lire"], 'answer': 0, 'correction': "Singing vient du verbe sing, chanter.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L22", 'level': 'A1', 'title': "Dancing et drawing", 'subtitle': "Sous-chapitre 8 • Leçon 22/50", 'explanation': "Dancing signifie danse ou le fait de danser ; drawing signifie dessin ou le fait de dessiner.", 'example': "I like dancing and drawing. = J’aime danser et dessiner.", 'french': "J’aime danser et dessiner.", 'question': "Drawing signifie…", 'options': <String>["Dessin / dessiner", "Courir", "Dormir"], 'answer': 0, 'correction': "Drawing est lié au verbe draw.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L23", 'level': 'A1', 'title': "Reading for fun", 'subtitle': "Sous-chapitre 8 • Leçon 23/50", 'explanation': "Reading for fun signifie lire pour le plaisir. For fun veut dire pour s’amuser ou par plaisir.", 'example': "I read comics for fun. = Je lis des bandes dessinées pour le plaisir.", 'french': "Je lis des bandes dessinées pour le plaisir.", 'question': "For fun signifie…", 'options': <String>["Pour le plaisir", "Pour l’école seulement", "En retard"], 'answer': 0, 'correction': "For fun décrit une activité faite par plaisir.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L24", 'level': 'A1', 'title': "Movies et TV shows", 'subtitle': "Sous-chapitre 8 • Leçon 24/50", 'explanation': "Movie signifie film ; TV show signifie émission ou série télévisée. Movie est le mot courant en anglais américain pour film.", 'example': "I watch movies on weekends. = Je regarde des films le week-end.", 'french': "Je regarde des films le week-end.", 'question': "Movie signifie…", 'options': <String>["Film", "Musique", "Journal"], 'answer': 0, 'correction': "Movie est le mot courant pour film.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L25", 'level': 'A1', 'title': "Video games", 'subtitle': "Sous-chapitre 8 • Leçon 25/50", 'explanation': "Video games signifie jeux vidéo. On dit play video games pour jouer aux jeux vidéo.", 'example': "They play video games after school. = Ils jouent aux jeux vidéo après l’école.", 'french': "Ils jouent aux jeux vidéo après l’école.", 'question': "Comment dire « jouer aux jeux vidéo » ?", 'options': <String>["play video games", "do video games", "make video games (pour jouer)"], 'answer': 0, 'correction': "On utilise play avec les jeux.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L26", 'level': 'A1', 'title': "Football et basketball", 'subtitle': "Sous-chapitre 8 • Leçon 26/50", 'explanation': "Football signifie soccer en anglais américain ; basketball est le basket-ball. Pour parler du sport pratiqué, on utilise play football ou play basketball.", 'example': "I play football with my friends. = Je joue au football avec mes amis.", 'french': "Je joue au football avec mes amis.", 'question': "Quel verbe utilise-t-on avec football ?", 'options': <String>["play", "do", "make"], 'answer': 0, 'correction': "Play est utilisé avec de nombreux sports d’équipe.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L27", 'level': 'A1', 'title': "Actions sportives de base", 'subtitle': "Sous-chapitre 8 • Leçon 27/50", 'explanation': "Les actions incluent run, jump, kick, throw, catch et swim. Apprends-les avec des images ou des mouvements simples.", 'example': "The player kicks the ball. = Le joueur frappe le ballon du pied.", 'french': "Le joueur frappe le ballon du pied.", 'question': "Kick signifie…", 'options': <String>["Frapper du pied", "Attraper", "Sauter"], 'answer': 0, 'correction': "Kick est l’action de donner un coup de pied.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L28", 'level': 'A1', 'title': "Team et player", 'subtitle': "Sous-chapitre 8 • Leçon 28/50", 'explanation': "Team signifie équipe ; player signifie joueur. Ces mots servent à parler des sports et des jeux.", 'example': "Our team is strong. = Notre équipe est forte.", 'french': "Notre équipe est forte.", 'question': "Player signifie…", 'options': <String>["Joueur", "Entraîneur seulement", "Ballon"], 'answer': 0, 'correction': "Player désigne une personne qui joue.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L29", 'level': 'A1', 'title': "Play football et play basketball", 'subtitle': "Sous-chapitre 8 • Leçon 29/50", 'explanation': "Play + sport est une structure fréquente. Dans une phrase avec he/she/it, on ajoute -s : He plays basketball.", 'example': "She plays basketball. = Elle joue au basket.", 'french': "Elle joue au basket.", 'question': "Complète : He ___ football.", 'options': <String>["play", "plays", "playing"], 'answer': 1, 'correction': "Avec he au présent simple, play devient plays.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L30", 'level': 'A1', 'title': "Go swimming et go running", 'subtitle': "Sous-chapitre 8 • Leçon 30/50", 'explanation': "Pour certaines activités, on utilise go + verbe en -ing : go swimming, go running, go shopping.", 'example': "We go swimming on Sundays. = Nous allons nager le dimanche.", 'french': "Nous allons nager le dimanche.", 'question': "Quelle expression signifie pratiquer la natation comme activité ?", 'options': <String>["go swim", "go swimming", "go to swimming"], 'answer': 1, 'correction': "L’expression est go + activité en -ing.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L31", 'level': 'A1', 'title': "Do exercise", 'subtitle': "Sous-chapitre 8 • Leçon 31/50", 'explanation': "Do exercise signifie faire de l’exercice. Exercise peut être indénombrable quand on parle d’activité physique en général.", 'example': "I do exercise every morning. = Je fais de l’exercice chaque matin.", 'french': "Je fais de l’exercice chaque matin.", 'question': "Comment dire « faire de l’exercice » ?", 'options': <String>["do exercise", "make exercise", "play exercise"], 'answer': 0, 'correction': "Do exercise est une expression courante.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L32", 'level': 'A1', 'title': "Can pour exprimer une capacité", 'subtitle': "Sous-chapitre 8 • Leçon 32/50", 'explanation': "Can signifie pouvoir ou savoir faire quelque chose. Il est suivi de la base verbale sans to : can swim, can speak.", 'example': "I can swim. = Je sais nager.", 'french': "Je sais nager.", 'question': "Complète : I can ___ English.", 'options': <String>["speak", "speaks", "to speak"], 'answer': 0, 'correction': "Après can, utilise la base verbale sans to.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L33", 'level': 'A1', 'title': "Can’t pour une incapacité", 'subtitle': "Sous-chapitre 8 • Leçon 33/50", 'explanation': "Can’t est la contraction de cannot et signifie ne pas pouvoir ou ne pas savoir faire. Il est suivi de la base verbale.", 'example': "I can’t drive. = Je ne sais pas conduire.", 'french': "Je ne sais pas conduire.", 'question': "Can’t signifie…", 'options': <String>["Pouvoir", "Ne pas pouvoir", "Devoir"], 'answer': 1, 'correction': "Can’t est la négation de can.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L34", 'level': 'A1', 'title': "Question Can you swim?", 'subtitle': "Sous-chapitre 8 • Leçon 34/50", 'explanation': "Pour demander une capacité, place can avant le sujet : Can you swim? Réponds Yes, I can ou No, I can’t.", 'example': "Can you swim? — Yes, I can. = Sais-tu nager ? — Oui.", 'french': "Sais-tu nager ? — Oui.", 'question': "Quelle question demande si quelqu’un sait nager ?", 'options': <String>["Can you swim?", "Do you can swim?", "Are you swim?"], 'answer': 0, 'correction': "Can précède le sujet dans une question.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L35", 'level': 'A1', 'title': "Répondre Yes, I can et No, I can’t", 'subtitle': "Sous-chapitre 8 • Leçon 35/50", 'explanation': "Les réponses courtes reprennent can : Yes, I can ; No, I can’t. N’ajoute pas do à cette structure.", 'example': "Can you cook? — No, I can’t. = Sais-tu cuisiner ? — Non.", 'french': "Sais-tu cuisiner ? — Non.", 'question': "Quelle réponse négative est correcte ?", 'options': <String>["No, I don’t can.", "No, I can’t.", "No, I can’t to."], 'answer': 1, 'correction': "La réponse courte reprend can’t.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L36", 'level': 'A1', 'title': "Parler de ses activités préférées", 'subtitle': "Sous-chapitre 8 • Leçon 36/50", 'explanation': "Utilise I like, I love ou My favorite activity is… pour parler des loisirs. Donne un exemple pour rendre ta réponse plus complète.", 'example': "My favorite activity is playing football. = Mon activité préférée est de jouer au football.", 'french': "Mon activité préférée est de jouer au football.", 'question': "Favorite signifie…", 'options': <String>["Préféré", "Difficile", "Nouveau"], 'answer': 0, 'correction': "Favorite signifie préféré en anglais américain.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L37", 'level': 'A1', 'title': "Proposer Let’s…", 'subtitle': "Sous-chapitre 8 • Leçon 37/50", 'explanation': "Let’s + verbe signifie « faisons… » ou « allons… ». C’est une proposition informelle : Let’s play, Let’s go, Let’s study.", 'example': "Let’s play football. = Jouons au football.", 'french': "Jouons au football.", 'question': "Complète : Let’s ___ English.", 'options': <String>["study", "studies", "studying"], 'answer': 0, 'correction': "Après Let’s, utilise la base verbale.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L38", 'level': 'A1', 'title': "Inviter avec Do you want to…?", 'subtitle': "Sous-chapitre 8 • Leçon 38/50", 'explanation': "Do you want to…? signifie « Veux-tu… ? ». La structure est do + sujet + want to + verbe de base.", 'example': "Do you want to play? = Veux-tu jouer ?", 'french': "Veux-tu jouer ?", 'question': "Comment proposer à quelqu’un de jouer ?", 'options': <String>["Do you want play?", "Do you want to play?", "Are you want to play?"], 'answer': 1, 'correction': "Want est suivi de to avant le verbe d’action.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L39", 'level': 'A1', 'title': "Inviter avec Would you like to…?", 'subtitle': "Sous-chapitre 8 • Leçon 39/50", 'explanation': "Would you like to…? est une invitation plus polie que Do you want to…? Elle est utile avec des personnes que l’on connaît peu.", 'example': "Would you like to join us? = Voudrais-tu te joindre à nous ?", 'french': "Voudrais-tu te joindre à nous ?", 'question': "Quelle formule est plus polie ?", 'options': <String>["Would you like to…?", "Give me…", "You come now."], 'answer': 0, 'correction': "Would you like est une formule polie.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L40", 'level': 'A1', 'title': "Accepter une invitation", 'subtitle': "Sous-chapitre 8 • Leçon 40/50", 'explanation': "Pour accepter, dis Sure!, Yes, I’d love to ou That sounds great. La réponse dépend du contexte et de ton enthousiasme.", 'example': "Yes, I’d love to! = Oui, avec plaisir !", 'french': "Oui, avec plaisir !", 'question': "Quelle réponse accepte avec enthousiasme ?", 'options': <String>["No, thanks.", "Yes, I’d love to!", "I don’t know your name."], 'answer': 1, 'correction': "I’d love to signifie avec plaisir / j’aimerais beaucoup.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L41", 'level': 'A1', 'title': "Refuser poliment une invitation", 'subtitle': "Sous-chapitre 8 • Leçon 41/50", 'explanation': "Pour refuser, dis Sorry, I can’t ou Thanks for inviting me, but I’m busy. Une courte explication peut adoucir le refus.", 'example': "Sorry, I can’t. I’m busy tonight. = Désolé, je ne peux pas. Je suis occupé ce soir.", 'french': "Désolé, je ne peux pas. Je suis occupé ce soir.", 'question': "Quelle phrase refuse poliment une invitation sans être impoli ?", 'options': <String>["No!", "Sorry, I can’t.", "Go away."], 'answer': 1, 'correction': "Sorry adoucit le refus ; can’t indique l’impossibilité.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L42", 'level': 'A1', 'title': "Proposer une autre heure", 'subtitle': "Sous-chapitre 8 • Leçon 42/50", 'explanation': "Si tu n’es pas disponible, propose une alternative : Can we meet tomorrow? ou How about Saturday?", 'example': "I’m busy today. How about tomorrow? = Je suis occupé aujourd’hui. Et demain ?", 'french': "Je suis occupé aujourd’hui. Et demain ?", 'question': "How about tomorrow? signifie…", 'options': <String>["Et demain ?", "Où est demain ?", "Combien demain ?"], 'answer': 0, 'correction': "How about sert à proposer une alternative.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L43", 'level': 'A1', 'title': "Question What do you do for fun?", 'subtitle': "Sous-chapitre 8 • Leçon 43/50", 'explanation': "Cette question signifie « Qu’est-ce que tu fais pour t’amuser ? ». Elle sert à parler des loisirs et activités préférées.", 'example': "What do you do for fun? — I play basketball. = Que fais-tu pour t’amuser ? — Je joue au basket.", 'french': "Que fais-tu pour t’amuser ? — Je joue au basket.", 'question': "Que demande What do you do for fun?", 'options': <String>["Les loisirs", "Le nom de famille", "L’heure"], 'answer': 0, 'correction': "For fun signifie pour le plaisir.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L44", 'level': 'A1', 'title': "Plan simple du week-end", 'subtitle': "Sous-chapitre 8 • Leçon 44/50", 'explanation': "Pour parler du week-end, utilise on Saturday, on Sunday, this weekend et next weekend. Ajoute les activités avec le présent simple ou une proposition Let’s.", 'example': "This weekend, I’m going to play football. = Ce week-end, je vais jouer au football.", 'french': "Ce week-end, je vais jouer au football.", 'question': "This weekend signifie…", 'options': <String>["Ce week-end", "Le week-end dernier", "Chaque jour"], 'answer': 0, 'correction': "This indique la période actuelle.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L45", 'level': 'A1', 'title': "With me et with my friends", 'subtitle': "Sous-chapitre 8 • Leçon 45/50", 'explanation': "With signifie avec. On dit with me, with you, with my family ou with my friends.", 'example': "She is coming with my friends. = Elle vient avec mes amis.", 'french': "Viens avec moi.", 'question': "With signifie…", 'options': <String>["Avec", "Sans", "Avant"], 'answer': 0, 'correction': "With indique l’accompagnement.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L46", 'level': 'A1', 'title': "Présenter son école", 'subtitle': "Sous-chapitre 8 • Leçon 46/50", 'explanation': "Pour présenter une école, utilise This is my school, It is big, My teachers are kind. Relie les phrases pour faire une description cohérente.", 'example': "This is my school. It is big and friendly. = Voici mon école. Elle est grande et accueillante.", 'french': "Voici mon école. Elle est grande et accueillante.", 'question': "Quelle phrase présente une école ?", 'options': <String>["This is my school.", "I school my.", "Where school?"], 'answer': 0, 'correction': "This is présente le lieu.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L47", 'level': 'A1', 'title': "Décrire son sport préféré", 'subtitle': "Sous-chapitre 8 • Leçon 47/50", 'explanation': "Utilise My favorite sport is… et explique pourquoi avec because. Les noms de sports sont généralement précédés de play quand on parle de les pratiquer.", 'example': "My favorite sport is football because it’s exciting. = Mon sport préféré est le football parce que c’est passionnant.", 'french': "Mon sport préféré est le football parce que c’est passionnant.", 'question': "Because signifie…", 'options': <String>["Mais", "Parce que", "Ensuite"], 'answer': 1, 'correction': "Because introduit une raison.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L48", 'level': 'A1', 'title': "Réagir avec That sounds fun", 'subtitle': "Sous-chapitre 8 • Leçon 48/50", 'explanation': "That sounds fun signifie « Ça a l’air amusant ». C’est une réaction naturelle à une proposition ou à une activité.", 'example': "Let’s go swimming. — That sounds fun! = Allons nager. — Ça a l’air amusant !", 'french': "Allons nager. — Ça a l’air amusant !", 'question': "Que signifie That sounds fun?", 'options': <String>["Ça a l’air amusant", "Je suis fatigué", "C’est trop cher"], 'answer': 0, 'correction': "Sounds fun est une réaction positive à une idée.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L49", 'level': 'A1', 'title': "Rencontrer un nouvel ami", 'subtitle': "Sous-chapitre 8 • Leçon 49/50", 'explanation': "Une première conversation peut contenir une salutation, un prénom, une question sur les loisirs et une invitation simple.", 'example': "Hi, I’m Alex. What do you do for fun? = Salut, je suis Alex. Qu’est-ce que tu fais pour t’amuser ?", 'french': "Salut, je suis Alex. Qu’est-ce que tu fais pour t’amuser ?", 'question': "Quelle question parle des loisirs ?", 'options': <String>["What do you do for fun?", "What time is it?", "Where is the bus?"], 'answer': 0, 'correction': "Cette question demande les activités de loisir.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U08-L50", 'level': 'A1', 'title': "Révision : organiser une rencontre", 'subtitle': "Sous-chapitre 8 • Leçon 50/50", 'explanation': "Réutilise les loisirs, can, les invitations, les réponses polies et la proposition d’un autre moment.", 'example': "Would you like to play basketball on Saturday? — I’d love to! = Veux-tu jouer au basket samedi ? — Avec plaisir !", 'french': "Veux-tu jouer au basket samedi ? — Avec plaisir !", 'question': "Quelle réponse accepte l’invitation ?", 'options': <String>["I’d love to!", "I can’t yesterday.", "Where is it?"], 'answer': 0, 'correction': "I’d love to est une réponse positive et naturelle.", 'unit': 8, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L01", 'level': 'A1', 'title': "Comprendre le présent continu", 'subtitle': "Sous-chapitre 9 • Leçon 1/50", 'explanation': "Le présent continu décrit une action en cours au moment où l’on parle. Forme : sujet + am/is/are + verbe en -ing.", 'example': "I am studying now. = Je suis en train d’étudier.", 'french': "Je suis en train d’étudier.", 'question': "Quelle structure forme le présent continu ?", 'options': <String>["be + verbe en -ing", "do + nom", "have + adjectif"], 'answer': 0, 'correction': "Le présent continu utilise am/is/are suivi du verbe en -ing.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L02", 'level': 'A1', 'title': "Former be + verb-ing", 'subtitle': "Sous-chapitre 9 • Leçon 2/50", 'explanation': "Choisis am, is ou are selon le sujet, puis ajoute -ing au verbe principal.", 'example': "She is reading. = Elle est en train de lire.", 'french': "Elle est en train de lire.", 'question': "Complète : She ___ reading now.", 'options': <String>["am", "is", "are"], 'answer': 1, 'correction': "Avec she, on utilise is.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L03", 'level': 'A1', 'title': "Ajouter -ing aux verbes réguliers", 'subtitle': "Sous-chapitre 9 • Leçon 3/50", 'explanation': "Pour beaucoup de verbes, ajoute simplement -ing : play → playing, read → reading.", 'example': "He is playing. = Il est en train de jouer.", 'french': "Il est en train de jouer.", 'question': "Quelle est la forme en -ing de play ?", 'options': <String>["playying", "playing", "played"], 'answer': 1, 'correction': "On ajoute simplement -ing à play.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L04", 'level': 'A1', 'title': "Doubler une consonne avant -ing", 'subtitle': "Sous-chapitre 9 • Leçon 4/50", 'explanation': "Certains verbes courts doublent leur consonne finale : run → running, sit → sitting.", 'example': "She is running. = Elle est en train de courir.", 'french': "Elle est en train de courir.", 'question': "Quelle forme est correctement écrite ?", 'options': <String>["runing", "running", "runned"], 'answer': 1, 'correction': "Run double le n avant -ing.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L05", 'level': 'A1', 'title': "Phrase affirmative au présent continu", 'subtitle': "Sous-chapitre 9 • Leçon 5/50", 'explanation': "Au présent continu, utilise le sujet + am/is/are + verbe en -ing pour parler d’une action en cours. Exemple : I am reading.", 'example': "I am reading a book. = Je suis en train de lire un livre.", 'french': "Peux-tu m’aider, s’il te plaît ?", 'question': "Quelle phrase affirmative est correcte ?", 'options': <String>["I listening.", "I am listening.", "I is listening."], 'answer': 1, 'correction': "Avec I, utilise am avant le verbe en -ing.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L06", 'level': 'A1', 'title': "Négation au présent continu", 'subtitle': "Sous-chapitre 9 • Leçon 6/50", 'explanation': "Place not après am, is ou are : I’m not working ; she isn’t sleeping.", 'example': "He isn’t sleeping. = Il n’est pas en train de dormir.", 'french': "Il n’est pas en train de dormir.", 'question': "Quelle est la négation correcte de He is sleeping ?", 'options': <String>["He not sleeping.", "He isn’t sleeping.", "He don’t sleeping."], 'answer': 1, 'correction': "La négation du présent continu place not après is.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L07", 'level': 'A1', 'title': "Question au présent continu", 'subtitle': "Sous-chapitre 9 • Leçon 7/50", 'explanation': "Pour une question, place am/is/are avant le sujet : Are you listening?", 'example': "Are they playing? = Sont-ils en train de jouer ?", 'french': "Sont-ils en train de jouer ?", 'question': "Quelle question est correctement formée ?", 'options': <String>["Are you listening?", "You are listen?", "Do you are listening?"], 'answer': 0, 'correction': "Avec be, place are avant le sujet.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L08", 'level': 'A1', 'title': "Répondre Yes, I am et No, I’m not", 'subtitle': "Sous-chapitre 9 • Leçon 8/50", 'explanation': "Pour répondre brièvement à une question avec be, reprends le sujet et la forme correcte de be : Yes, I am / No, I’m not.", 'example': "Is he at home? — Yes, he is. = Est-il à la maison ? — Oui.", 'french': "Peux-tu m’aider, s’il te plaît ?", 'question': "Réponds à Are you studying? par une réponse courte positive.", 'options': <String>["Yes, I do.", "Yes, I am.", "Yes, I studying."], 'answer': 1, 'correction': "La réponse courte reprend be : Yes, I am.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L09", 'level': 'A1', 'title': "Distinguer present simple et present continuous", 'subtitle': "Sous-chapitre 9 • Leçon 9/50", 'explanation': "Le présent simple décrit souvent une habitude; le présent continu décrit une action en cours ou temporaire.", 'example': "I study every day, but I’m studying now. = J’étudie chaque jour, mais je suis en train d’étudier maintenant.", 'french': "Peux-tu m’aider, s’il te plaît ?", 'question': "Quelle phrase décrit une habitude ?", 'options': <String>["I’m playing now.", "I play every Sunday.", "I am play now."], 'answer': 1, 'correction': "Every Sunday indique une habitude ; le présent simple convient.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L10", 'level': 'A1', 'title': "Décrire une personne sur une image", 'subtitle': "Sous-chapitre 9 • Leçon 10/50", 'explanation': "Décris une action visible avec sujet + am/is/are + verbe en -ing.", 'example': "She is reading a book. = Elle est en train de lire un livre.", 'french': "Elle est en train de lire un livre.", 'question': "Quelle phrase décrit l’action visible sur une image ?", 'options': <String>["She reads every day.", "She is reading a book.", "She read yesterday."], 'answer': 1, 'correction': "Le présent continu décrit l’action visible en cours.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L11", 'level': 'A1', 'title': "Dire I’m studying now", 'subtitle': "Sous-chapitre 9 • Leçon 11/50", 'explanation': "Avec now, le présent continu indique souvent une action en cours : sujet + am/is/are + verbe en -ing.", 'example': "I’m studying now. = Je suis en train d’étudier maintenant.", 'french': "Peux-tu m’aider, s’il te plaît ?", 'question': "Que signifie I’m studying now ?", 'options': <String>["J’étudie en ce moment.", "J’étudiais hier.", "J’étudierai demain."], 'answer': 0, 'correction': "Now signifie maintenant et indique l’action en cours.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L12", 'level': 'A1', 'title': "Dire She is cooking", 'subtitle': "Sous-chapitre 9 • Leçon 12/50", 'explanation': "Avec she, utilise is avant le verbe en -ing pour décrire une action en cours : She is cooking.", 'example': "She is cooking dinner. = Elle prépare le dîner.", 'french': "Peux-tu m’aider, s’il te plaît ?", 'question': "Complète : She ___ cooking dinner.", 'options': <String>["am", "is", "are"], 'answer': 1, 'correction': "Avec she, le verbe be au présent continu est is.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L13", 'level': 'A1', 'title': "Dire They are playing", 'subtitle': "Sous-chapitre 9 • Leçon 13/50", 'explanation': "Avec they, utilise are avant le verbe en -ing pour décrire une action en cours : They are playing.", 'example': "They are playing football. = Ils jouent au football.", 'french': "Peux-tu m’aider, s’il te plaît ?", 'question': "Complète : They ___ playing outside.", 'options': <String>["is", "are", "am"], 'answer': 1, 'correction': "Avec they, on utilise are.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L14", 'level': 'A1', 'title': "Question What are you doing?", 'subtitle': "Sous-chapitre 9 • Leçon 14/50", 'explanation': "Cette question demande ce que la personne fait maintenant. La réponse utilise généralement le présent continu.", 'example': "What are you doing? — I’m reading.", 'french': "What are you doing? — I’m reading.", 'question': "Quelle question demande l’action actuelle ?", 'options': <String>["What do you do every day?", "What are you doing?", "Where are you?"], 'answer': 1, 'correction': "What are you doing? demande ce que tu fais maintenant.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L15", 'level': 'A1', 'title': "Question What is he doing?", 'subtitle': "Sous-chapitre 9 • Leçon 15/50", 'explanation': "Avec he, utilise is dans la question : What is he doing?", 'example': "What is he doing? — He is running.", 'french': "What is he doing? — He is running.", 'question': "Quelle question demande ce qu’il fait en ce moment ?", 'options': <String>["What is he doing?", "What he does?", "What is he do?"], 'answer': 0, 'correction': "La structure correcte est What + is + sujet + verbe-ing.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L16", 'level': 'A1', 'title': "Nommer les actions d’une scène", 'subtitle': "Sous-chapitre 9 • Leçon 16/50", 'explanation': "Pour décrire une scène, nomme les personnes puis utilise be + verbe en -ing pour chaque action visible.", 'example': "The boy is running. The girl is reading. = Le garçon court. La fille lit.", 'french': "Peux-tu m’aider, s’il te plaît ?", 'question': "Quel verbe en -ing signifie courir ?", 'options': <String>["sleeping", "running", "reading"], 'answer': 1, 'correction': "Running est la forme en -ing de run.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L17", 'level': 'A1', 'title': "Décrire une photo en trois phrases", 'subtitle': "Sous-chapitre 9 • Leçon 17/50", 'explanation': "Pour décrire une photo, observe le ciel, les personnes et leurs actions; utilise des phrases courtes au présent.", 'example': "It’s sunny today. = Il fait ensoleillé aujourd’hui.", 'french': "Il fait ensoleillé aujourd’hui.", 'question': "Quelle phrase décrit correctement une photo ?", 'options': <String>["A girl is reading.", "A girl reading yesterday.", "A girl is read."], 'answer': 0, 'correction': "Sujet + is + verbe-ing décrit une action visible.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L18", 'level': 'A1', 'title': "Sunny et rainy", 'subtitle': "Sous-chapitre 9 • Leçon 18/50", 'explanation': "Sunny signifie ensoleillé ; rainy signifie pluvieux.", 'example': "It’s rainy today. = Il pleut aujourd’hui.", 'french': "Il fait ensoleillé aujourd’hui.", 'question': "Sunny signifie…", 'options': <String>["Ensoleillé", "Pluvieux", "Nuageux"], 'answer': 0, 'correction': "Sunny signifie ensoleillé.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L19", 'level': 'A1', 'title': "Cloudy et windy", 'subtitle': "Sous-chapitre 9 • Leçon 19/50", 'explanation': "Cloudy signifie nuageux ; windy signifie venteux.", 'example': "It’s windy today. = Il y a du vent aujourd’hui.", 'french': "Il y a du vent aujourd’hui.", 'question': "Windy signifie…", 'options': <String>["Venteux", "Nuageux", "Neigeux"], 'answer': 0, 'correction': "Windy signifie qu’il y a du vent.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L20", 'level': 'A1', 'title': "Hot et cold", 'subtitle': "Sous-chapitre 9 • Leçon 20/50", 'explanation': "Hot signifie chaud ; cold signifie froid.", 'example': "It’s cold today. = Il fait froid aujourd’hui.", 'french': "Il fait froid aujourd’hui.", 'question': "Quel est le contraire de hot ?", 'options': <String>["cold", "warm", "sunny"], 'answer': 0, 'correction': "Cold signifie froid, l’opposé de hot.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L21", 'level': 'A1', 'title': "Warm et cool", 'subtitle': "Sous-chapitre 9 • Leçon 21/50", 'explanation': "Warm signifie doux ou chaud agréablement ; cool signifie frais selon le contexte.", 'example': "It’s warm today. = Il fait doux aujourd’hui.", 'french': "Il fait doux aujourd’hui.", 'question': "Warm décrit généralement un temps…", 'options': <String>["doux ou agréablement chaud", "très froid", "pluvieux"], 'answer': 0, 'correction': "Warm exprime une chaleur modérée et agréable.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L22", 'level': 'A1', 'title': "Question What’s the weather like?", 'subtitle': "Sous-chapitre 9 • Leçon 22/50", 'explanation': "Cette question demande quel temps il fait. Réponds avec It’s + adjectif météo.", 'example': "What’s the weather like? — It’s cloudy.", 'french': "What’s the weather like? — It’s cloudy.", 'question': "Quelle question demande la météo ?", 'options': <String>["What’s the weather like?", "How old is the weather?", "Where weather?"], 'answer': 0, 'correction': "What’s the weather like? est la question naturelle sur le temps.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L23", 'level': 'A1', 'title': "Parler de la météo aujourd’hui", 'subtitle': "Sous-chapitre 9 • Leçon 23/50", 'explanation': "Utilise It’s + adjectif météo pour décrire les conditions actuelles; today situe l’information dans la journée présente.", 'example': "It’s warm and sunny today. = Il fait doux et ensoleillé aujourd’hui.", 'french': "Il fait ensoleillé aujourd’hui.", 'question': "Comment dire « Il fait froid aujourd’hui » ?", 'options': <String>["It’s cold today.", "It cold today.", "Today has cold."], 'answer': 0, 'correction': "It’s + adjectif météo est la structure courante.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L24", 'level': 'A1', 'title': "Parler de la météo demain", 'subtitle': "Sous-chapitre 9 • Leçon 24/50", 'explanation': "Pour parler de la météo prévue demain, utilise une expression future et le mot tomorrow.", 'example': "It will be sunny tomorrow. = Il fera ensoleillé demain.", 'french': "Il fait ensoleillé aujourd’hui.", 'question': "Quel mot désigne le jour qui vient après aujourd’hui ?", 'options': <String>["Demain", "Hier", "Aujourd’hui"], 'answer': 0, 'correction': "Tomorrow désigne le jour suivant.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L25", 'level': 'A1', 'title': "Choisir des vêtements selon la météo", 'subtitle': "Sous-chapitre 9 • Leçon 25/50", 'explanation': "Relie la météo aux vêtements : It’s cold, so I’m wearing a jacket. So introduit la conséquence.", 'example': "It’s cold, so I’m wearing a jacket. = Il fait froid, alors je porte une veste.", 'french': "Il fait ensoleillé aujourd’hui.", 'question': "Que prends-tu quand il pleut ?", 'options': <String>["An umbrella", "A fan", "Sunglasses only"], 'answer': 0, 'correction': "Un parapluie protège de la pluie.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L26", 'level': 'A1', 'title': "Wear et put on", 'subtitle': "Sous-chapitre 9 • Leçon 26/50", 'explanation': "Wear décrit le vêtement que l’on porte ; put on décrit l’action de mettre un vêtement.", 'example': "I’m wearing a coat. / Put on your coat.", 'french': "I’m wearing a coat. / Put on your coat.", 'question': "Quelle phrase distingue bien wear et put on ?", 'options': <String>["I’m wearing a coat. / Put on your coat.", "I’m put a coat wearing.", "Wear on your coat now."], 'answer': 0, 'correction': "Wear décrit ce que tu portes ; put on décrit l’action de mettre le vêtement.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L27", 'level': 'A1', 'title': "Consigne affirmative à l’impératif", 'subtitle': "Sous-chapitre 9 • Leçon 27/50", 'explanation': "Une consigne directe commence par la base verbale : Sit down, Listen, Open the door.", 'example': "Please wait here. = Attends ici, s’il te plaît.", 'french': "Attends ici, s’il te plaît.", 'question': "Quelle phrase est une consigne affirmative correcte ?", 'options': <String>["Please wait here.", "You waiting here.", "You are wait here."], 'answer': 0, 'correction': "L’impératif commence par la base verbale : wait.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L28", 'level': 'A1', 'title': "Consigne négative avec Don’t", 'subtitle': "Sous-chapitre 9 • Leçon 28/50", 'explanation': "Pour demander de ne pas faire une action, utilise Don’t + base verbale.", 'example': "Don’t run in class. = Ne cours pas en classe.", 'french': "Ne cours pas en classe.", 'question': "Complète : Don’t ___ in class.", 'options': <String>["running", "run", "runs"], 'answer': 1, 'correction': "Après Don’t, utilise la base verbale.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L29", 'level': 'A1', 'title': "Comprendre Wait a minute", 'subtitle': "Sous-chapitre 9 • Leçon 29/50", 'explanation': "Wait a minute et wait a second servent à demander un court délai; ajoute please pour adoucir la demande.", 'example': "Wait a second, please. = Attendez une seconde, s’il vous plaît.", 'french': "Attendez ici, s’il vous plaît.", 'question': "Que signifie Wait a minute, please ?", 'options': <String>["Attends une minute, s’il te plaît.", "Tourne à gauche.", "Ouvre la porte."], 'answer': 0, 'correction': "Wait a minute demande un court délai.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L30", 'level': 'A1', 'title': "Comprendre Be careful", 'subtitle': "Sous-chapitre 9 • Leçon 30/50", 'explanation': "Be careful signifie fais attention. C’est une consigne d’avertissement.", 'example': "Be careful! The floor is wet.", 'french': "Be careful! The floor is wet.", 'question': "Be careful signifie…", 'options': <String>["Fais attention", "À demain", "Assieds-toi"], 'answer': 0, 'correction': "Be careful est un avertissement.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L31", 'level': 'A1', 'title': "Demander Can you show me?", 'subtitle': "Sous-chapitre 9 • Leçon 31/50", 'explanation': "Can you show me...? demande à quelqu’un de montrer un lieu ou une information. Après can, utilise la base verbale.", 'example': "Can you show me the station? = Pouvez-vous m’indiquer la gare ?", 'french': "Excusez-moi, pouvez-vous m’aider ?", 'question': "Que signifie Can you show me the way?", 'options': <String>["Peux-tu me montrer le chemin ?", "Peux-tu m’appeler demain ?", "Peux-tu fermer la porte ?"], 'answer': 0, 'correction': "Show me the way signifie montrer le chemin.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L32", 'level': 'A1', 'title': "Demander Can you say that again?", 'subtitle': "Sous-chapitre 9 • Leçon 32/50", 'explanation': "Cette expression demande à l’interlocuteur de répéter ce qu’il vient de dire.", 'example': "Can you say that again, please? = Peux-tu répéter, s’il te plaît ?", 'french': "Peux-tu répéter, s’il te plaît ?", 'question': "Quelle expression demande de répéter ?", 'options': <String>["Can you say that again?", "Where do you live?", "How much is it?"], 'answer': 0, 'correction': "Say that again signifie redire ce qui vient d’être dit.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L33", 'level': 'A1', 'title': "Demander What do you mean?", 'subtitle': "Sous-chapitre 9 • Leçon 33/50", 'explanation': "Cette question demande une clarification du sens de ce que l’autre vient de dire.", 'example': "What do you mean by that? = Qu’est-ce que tu veux dire par là ?", 'french': "Qu’est-ce que tu veux dire par là ?", 'question': "What do you mean? demande…", 'options': <String>["une clarification", "l’heure", "un prix"], 'answer': 0, 'correction': "What do you mean? signifie « Qu’est-ce que tu veux dire ? ».", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L34", 'level': 'A1', 'title': "Question How do you say… in English?", 'subtitle': "Sous-chapitre 9 • Leçon 34/50", 'explanation': "Cette structure demande comment exprimer un mot ou une phrase en anglais.", 'example': "How do you say “merci” in English?", 'french': "How do you say “merci” in English?", 'question': "Quelle question demande comment traduire un mot en anglais ?", 'options': <String>["How do you say… in English?", "How old are you?", "How much is it?"], 'answer': 0, 'correction': "Cette structure demande comment dire une expression en anglais.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L35", 'level': 'A1', 'title': "Dire I’m looking for…", 'subtitle': "Sous-chapitre 9 • Leçon 35/50", 'explanation': "Cette expression signifie je cherche… ; elle est utile dans un magasin ou en ville.", 'example': "I’m looking for the station. = Je cherche la gare.", 'french': "Je cherche la gare.", 'question': "I’m looking for the station signifie…", 'options': <String>["Je cherche la gare.", "Je ferme la gare.", "Je suis à la gare depuis hier."], 'answer': 0, 'correction': "Look for signifie chercher.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L36", 'level': 'A1', 'title': "Demander Can I use your…?", 'subtitle': "Sous-chapitre 9 • Leçon 36/50", 'explanation': "Cette question demande la permission d’utiliser un objet qui appartient à quelqu’un.", 'example': "Can I use your pen? = Puis-je utiliser ton stylo ?", 'french': "Puis-je utiliser ton stylo ?", 'question': "Quelle phrase demande la permission d’utiliser un stylo ?", 'options': <String>["Can I use your pen?", "Where is your pen?", "I use your pen yesterday."], 'answer': 0, 'correction': "Can I…? sert à demander la permission.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L37", 'level': 'A1', 'title': "Demander May I come in?", 'subtitle': "Sous-chapitre 9 • Leçon 37/50", 'explanation': "Cette formule polie demande la permission d’entrer.", 'example': "May I come in, please? = Puis-je entrer, s’il vous plaît ?", 'french': "Puis-je entrer, s’il vous plaît ?", 'question': "Quelle formule demande poliment la permission d’entrer ?", 'options': <String>["May I come in?", "I come in now.", "Where come in?"], 'answer': 0, 'correction': "May I…? est une formule polie de permission.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L38", 'level': 'A1', 'title': "Dire Just a moment", 'subtitle': "Sous-chapitre 9 • Leçon 38/50", 'explanation': "Cette expression demande un court délai.", 'example': "Just a moment, please. = Un instant, s’il vous plaît.", 'french': "Un instant, s’il vous plaît.", 'question': "Just a moment signifie…", 'options': <String>["Un instant", "À gauche", "Chaque jour"], 'answer': 0, 'correction': "Just a moment demande un court délai.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L39", 'level': 'A1', 'title': "Dire That’s okay", 'subtitle': "Sous-chapitre 9 • Leçon 39/50", 'explanation': "Cette expression peut rassurer quelqu’un après une excuse : ce n’est pas grave.", 'example': "Sorry I’m late. — That’s okay.", 'french': "Sorry I’m late. — That’s okay.", 'question': "Que peut-on répondre à Sorry I’m late ?", 'options': <String>["That’s okay.", "How much is it?", "Turn right."], 'answer': 0, 'correction': "That’s okay peut rassurer la personne après une excuse.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L40", 'level': 'A1', 'title': "Dire No problem", 'subtitle': "Sous-chapitre 9 • Leçon 40/50", 'explanation': "No problem signifie pas de problème ; c’est une réponse informelle à une demande ou un remerciement.", 'example': "Thanks for helping. — No problem!", 'french': "Thanks for helping. — No problem!", 'question': "No problem signifie…", 'options': <String>["Pas de problème", "Je suis perdu", "Bonne nuit"], 'answer': 0, 'correction': "No problem est une réponse informelle rassurante.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L41", 'level': 'A1', 'title': "Sorry et That’s all right", 'subtitle': "Sous-chapitre 9 • Leçon 41/50", 'explanation': "Sorry sert à présenter des excuses; That’s all right rassure l’autre personne et signifie que ce n’est pas grave.", 'example': "Sorry! — That’s all right. = Désolé ! — Ce n’est pas grave.", 'french': "Peux-tu m’aider, s’il te plaît ?", 'question': "Quelle réponse convient à Sorry ?", 'options': <String>["That’s all right.", "Good morning.", "I’m sixteen."], 'answer': 0, 'correction': "That’s all right signifie « ce n’est pas grave ».", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L42", 'level': 'A1', 'title': "Demander de l’aide en public", 'subtitle': "Sous-chapitre 9 • Leçon 42/50", 'explanation': "Pour demander de l’aide à un inconnu, commence par Excuse me puis formule une demande claire et polie.", 'example': "Excuse me, could you help me carry this bag? = Excusez-moi, pourriez-vous m’aider à porter ce sac ?", 'french': "Excusez-moi, pouvez-vous m’aider ?", 'question': "Quelle expression introduit poliment une demande à un inconnu ?", 'options': <String>["Excuse me", "Go away", "Never"], 'answer': 0, 'correction': "Excuse me attire poliment l’attention.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L43", 'level': 'A1', 'title': "Dire I’m lost", 'subtitle': "Sous-chapitre 9 • Leçon 43/50", 'explanation': "I’m lost signifie je suis perdu. Ajoute Can you help me? pour demander de l’aide.", 'example': "I’m lost. Can you help me?", 'french': "I’m lost. Can you help me?", 'question': "I’m lost signifie…", 'options': <String>["Je suis perdu.", "Je suis en avance.", "J’ai faim."], 'answer': 0, 'correction': "Lost signifie perdu.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L44", 'level': 'A1', 'title': "Demander où se trouve un arrêt", 'subtitle': "Sous-chapitre 9 • Leçon 44/50", 'explanation': "Pour demander où se trouve un lieu, utilise Where is the...? et nomme l’endroit recherché.", 'example': "Excuse me, where is the bus stop? = Excusez-moi, où se trouve l’arrêt de bus ?", 'french': "Excusez-moi, pouvez-vous m’aider ?", 'question': "Quelle question demande où se trouve l’arrêt de bus ?", 'options': <String>["Where is the bus stop?", "How old is the bus?", "How much is the bus stop?"], 'answer': 0, 'correction': "Where demande un lieu.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L45", 'level': 'A1', 'title': "Demander à parler à quelqu’un", 'subtitle': "Sous-chapitre 9 • Leçon 45/50", 'explanation': "May I speak to...? est une formule polie, notamment au téléphone, pour demander à parler à une personne.", 'example': "May I speak to Mr. Brown, please? = Puis-je parler à M. Brown, s’il vous plaît ?", 'french': "Excusez-moi, pouvez-vous m’aider ?", 'question': "Quelle formule demande à parler à quelqu’un ?", 'options': <String>["Can I speak to…?", "Can I eat…?", "Where speak?"], 'answer': 0, 'correction': "Speak to introduit la personne à qui l’on veut parler.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L46", 'level': 'A1', 'title': "Comprendre Please wait here", 'subtitle': "Sous-chapitre 9 • Leçon 46/50", 'explanation': "Please wait here est une consigne polie : impératif wait + complément, avec please pour atténuer.", 'example': "Please wait here. = Attendez ici, s’il vous plaît.", 'french': "Attendez ici, s’il vous plaît.", 'question': "Please wait here signifie…", 'options': <String>["Attendez ici, s’il vous plaît.", "Allez à la gare.", "Regardez cette image."], 'answer': 0, 'correction': "Here signifie ici.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L47", 'level': 'A1', 'title': "Donner une instruction en deux étapes", 'subtitle': "Sous-chapitre 9 • Leçon 47/50", 'explanation': "Relie deux impératifs avec and pour donner des instructions successives : Open your book and write your name.", 'example': "Open your book and write your name. = Ouvre ton livre et écris ton nom.", 'french': "Peux-tu m’aider, s’il te plaît ?", 'question': "Quel mot relie deux instructions dans l’ordre ?", 'options': <String>["then", "blue", "because"], 'answer': 0, 'correction': "Then signifie ensuite.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L48", 'level': 'A1', 'title': "Comprendre une annonce pratique", 'subtitle': "Sous-chapitre 9 • Leçon 48/50", 'explanation': "Dans une annonce, repère les verbes d’action et les indications de lieu ou de temps; elles donnent la consigne principale.", 'example': "The train to the airport is now boarding. = L’embarquement pour le train vers l’aéroport commence maintenant.", 'french': "Attendez ici, s’il vous plaît.", 'question': "Delayed signifie…", 'options': <String>["En retard / retardé", "En avance", "Toujours ouvert"], 'answer': 0, 'correction': "Delayed indique qu’un transport ou un événement est retardé.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L49", 'level': 'A1', 'title': "Révision : résoudre une difficulté", 'subtitle': "Sous-chapitre 9 • Leçon 49/50", 'explanation': "Réutilise les demandes de clarification, les consignes et les formules de politesse pour maintenir une conversation.", 'example': "Excuse me, I’m lost. Can you help me? Could you speak more slowly, please?", 'french': "Excuse me, I’m lost. Can you help me? Could you speak more slowly, please?", 'question': "Quelle demande aide à poursuivre une conversation difficile ?", 'options': <String>["Could you speak more slowly, please?", "I’m sixteen years old.", "The bag is blue."], 'answer': 0, 'correction': "Cette phrase demande de parler plus lentement et aide à clarifier la communication.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U09-L50", 'level': 'A1', 'title': "Mini-évaluation de communication A1", 'subtitle': "Sous-chapitre 9 • Leçon 50/50", 'explanation': "Dans une mini-évaluation, combine les structures apprises dans un échange cohérent : identité, lieu et action en cours.", 'example': "I’m at school now. I’m studying English. = Je suis à l’école maintenant. J’étudie l’anglais.", 'french': "Peux-tu m’aider, s’il te plaît ?", 'question': "Quel est le point principal de cette leçon ?", 'options': <String>["Comprendre l’expression et la réutiliser dans une situation", "Décrire une habitude uniquement", "Nommer une couleur sans contexte"], 'answer': 0, 'correction': "Relis l’explication et l’exemple : ils illustrent la structure ou l’expression étudiée. Les autres choix ne correspondent pas à l’objectif de cette leçon.", 'unit': 9, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L01", 'level': 'A1', 'title': "Écouter une première rencontre", 'subtitle': "Sous-chapitre 10 • Leçon 1/50", 'explanation': "Repère les salutations, les prénoms et la formule utilisée quand deux personnes se rencontrent.", 'example': "Hello! I’m Alex. Nice to meet you. = Bonjour ! Je suis Alex. Ravi de te rencontrer.", 'french': "Bonjour ! Je suis Alex. Ravi de te rencontrer.", 'question': "Quelle expression signifie « Ravi de te rencontrer » ?", 'options': <String>["Nice to meet you", "How old are you?", "Where is it?"], 'answer': 0, 'correction': "Nice to meet you est une formule naturelle lors d’une première rencontre.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L02", 'level': 'A1', 'title': "Écouter une présentation et relever l’âge", 'subtitle': "Sous-chapitre 10 • Leçon 2/50", 'explanation': "Dans une présentation, écoute les informations personnelles : prénom, âge, pays et activité.", 'example': "I’m fourteen years old, and I’m from Canada. = J’ai quatorze ans et je viens du Canada.", 'french': "J’ai quatorze ans et je viens du Canada.", 'question': "Quelle phrase donne l’âge ?", 'options': <String>["I’m fourteen years old.", "I’m from Canada.", "I’m a student."], 'answer': 0, 'correction': "I’m … years old sert à donner son âge.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L03", 'level': 'A1', 'title': "Comprendre une conversation familiale", 'subtitle': "Sous-chapitre 10 • Leçon 3/50", 'explanation': "Les mots de parenté permettent d’identifier qui parle de qui dans une famille.", 'example': "This is my sister, Emma. She is twelve. = Voici ma sœur, Emma. Elle a douze ans.", 'french': "Voici ma sœur, Emma. Elle a douze ans.", 'question': "Qui est Emma ?", 'options': <String>["His teacher.", "His sister.", "His mother."], 'answer': 1, 'correction': "Sister signifie sœur.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L04", 'level': 'A1', 'title': "Lire un profil personnel court", 'subtitle': "Sous-chapitre 10 • Leçon 4/50", 'explanation': "Un profil personnel donne souvent le prénom, l’âge, le lieu d’origine et les centres d’intérêt.", 'example': "My name is Mia. I’m sixteen, and I love music. = Je m’appelle Mia. J’ai seize ans et j’adore la musique.", 'french': "Je m’appelle Mia. J’ai seize ans et j’adore la musique.", 'question': "Quel est le passe-temps de Mia ?", 'options': <String>["Music.", "Football.", "Cooking."], 'answer': 0, 'correction': "I love music indique que Mia aime beaucoup la musique.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L05", 'level': 'A1', 'title': "Écrire une présentation guidée", 'subtitle': "Sous-chapitre 10 • Leçon 5/50", 'explanation': "Une présentation simple peut suivre cet ordre : prénom, origine, âge, études et loisirs.", 'example': "Hi! I’m Daniel. I’m from Kenya, and I’m a student. = Salut ! Je suis Daniel. Je viens du Kenya et je suis élève.", 'french': "Salut ! Je suis Daniel. Je viens du Kenya et je suis élève.", 'question': "Quelle phrase présente correctement une personne ?", 'options': <String>["I Daniel from Kenya.", "Hi! I’m Daniel. I’m from Kenya.", "Me is Daniel."], 'answer': 1, 'correction': "I’m + prénom et I’m from + pays sont des structures correctes.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L06", 'level': 'A1', 'title': "Parler de son pays et de ses langues", 'subtitle': "Sous-chapitre 10 • Leçon 6/50", 'explanation': "Utilise I’m from pour l’origine et I speak pour les langues que tu parles.", 'example': "I’m from the DRC, and I speak French and Swahili. = Je viens de la RDC et je parle français et swahili.", 'french': "Je viens de la RDC et je parle français et swahili.", 'question': "Quelle structure indique une langue parlée ?", 'options': <String>["I speak Swahili.", "I am Swahili speak.", "I speaking Swahili."], 'answer': 0, 'correction': "I speak + langue indique la langue parlée.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L07", 'level': 'A1', 'title': "Conversation sur l’école", 'subtitle': "Sous-chapitre 10 • Leçon 7/50", 'explanation': "Pour parler de l’école, mentionne les matières, les horaires et les activités de classe.", 'example': "My favorite subject is science because it’s interesting. = Ma matière préférée est les sciences parce que c’est intéressant.", 'french': "Ma matière préférée est les sciences parce que c’est intéressant.", 'question': "Pourquoi cette personne aime-t-elle les sciences ?", 'options': <String>["Because they are interesting.", "Because it is Monday.", "Because it is expensive."], 'answer': 0, 'correction': "Because introduit la raison.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L08", 'level': 'A1', 'title': "Comprendre un échange sur l’heure", 'subtitle': "Sous-chapitre 10 • Leçon 8/50", 'explanation': "Les questions sur l’heure utilisent What time is it? ou What time do you…? selon le contexte.", 'example': "What time does the class start? — It starts at eight. = À quelle heure le cours commence-t-il ? — Il commence à huit heures.", 'french': "À quelle heure le cours commence-t-il ? — Il commence à huit heures.", 'question': "À quelle heure le cours commence-t-il ?", 'options': <String>["At eight.", "On Friday.", "In the kitchen."], 'answer': 0, 'correction': "At + heure indique l’heure précise.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L09", 'level': 'A1', 'title': "Lire un emploi du temps", 'subtitle': "Sous-chapitre 10 • Leçon 9/50", 'explanation': "Un emploi du temps indique les jours, les heures et les activités prévues.", 'example': "English is on Monday at nine o’clock. = L’anglais est prévu lundi à neuf heures.", 'french': "L’anglais est prévu lundi à neuf heures.", 'question': "Quand a lieu le cours d’anglais ?", 'options': <String>["Monday at nine.", "Tuesday at six.", "Friday at noon."], 'answer': 0, 'correction': "On Monday indique le jour ; at nine indique l’heure.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L10", 'level': 'A1', 'title': "Écrire une routine quotidienne", 'subtitle': "Sous-chapitre 10 • Leçon 10/50", 'explanation': "Pour raconter une routine, utilise le présent simple et des marqueurs comme first, then et finally.", 'example': "First, I get up. Then I have breakfast. Finally, I go to school. = D’abord, je me lève. Ensuite, je prends le petit-déjeuner. Enfin, je vais à l’école.", 'french': "D’abord, je me lève. Ensuite, je prends le petit-déjeuner. Enfin, je vais à l’école.", 'question': "Quel mot signifie « ensuite » ?", 'options': <String>["Then.", "Yesterday.", "Never."], 'answer': 0, 'correction': "Then marque l’étape suivante dans une séquence.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L11", 'level': 'A1', 'title': "Décrire sa maison à l’oral", 'subtitle': "Sous-chapitre 10 • Leçon 11/50", 'explanation': "Décris ton logement en nommant les pièces et en utilisant there is/there are.", 'example': "There are two bedrooms and a small kitchen. = Il y a deux chambres et une petite cuisine.", 'french': "Il y a deux chambres et une petite cuisine.", 'question': "Quelle structure présente plusieurs éléments ?", 'options': <String>["There are two bedrooms.", "There is two bedrooms.", "They is two bedrooms."], 'answer': 0, 'correction': "There are s’emploie avec un nom pluriel.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L12", 'level': 'A1', 'title': "Lire une description de chambre", 'subtitle': "Sous-chapitre 10 • Leçon 12/50", 'explanation': "Une description de chambre précise les meubles et leur position avec des prépositions.", 'example': "The desk is next to the window, and the bed is opposite the door. = Le bureau est à côté de la fenêtre et le lit en face de la porte.", 'french': "Le bureau est à côté de la fenêtre et le lit en face de la porte.", 'question': "Que signifie next to ?", 'options': <String>["À côté de.", "Au-dessus de.", "Derrière."], 'answer': 0, 'correction': "Next to signifie « à côté de ».", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L13", 'level': 'A1', 'title': "Comprendre un itinéraire", 'subtitle': "Sous-chapitre 10 • Leçon 13/50", 'explanation': "Écoute les directions dans l’ordre : avancer, tourner, puis repérer un point de référence.", 'example': "Go straight, turn right, and the bank is on your left. = Va tout droit, tourne à droite et la banque est à ta gauche.", 'french': "Va tout droit, tourne à droite et la banque est à ta gauche.", 'question': "Quelle instruction vient en premier ?", 'options': <String>["Go straight.", "Turn left.", "Cross the bridge."], 'answer': 0, 'correction': "Go straight signifie aller tout droit.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L14", 'level': 'A1', 'title': "Donner des directions", 'subtitle': "Sous-chapitre 10 • Leçon 14/50", 'explanation': "Pour guider quelqu’un, donne des consignes courtes et ajoute un repère facile à reconnaître.", 'example': "Turn left at the traffic lights. The library is beside the park. = Tourne à gauche aux feux. La bibliothèque est à côté du parc.", 'french': "Tourne à gauche aux feux. La bibliothèque est à côté du parc.", 'question': "Où faut-il tourner à gauche ?", 'options': <String>["At the traffic lights.", "At the hospital.", "At the bus stop."], 'answer': 0, 'correction': "At the traffic lights précise le lieu du virage.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L15", 'level': 'A1', 'title': "Commander dans un café", 'subtitle': "Sous-chapitre 10 • Leçon 15/50", 'explanation': "I’d like et Can I have…? sont des formules polies pour commander.", 'example': "I’d like a sandwich and a glass of water, please. = Je voudrais un sandwich et un verre d’eau, s’il vous plaît.", 'french': "Je voudrais un sandwich et un verre d’eau, s’il vous plaît.", 'question': "Quelle commande est polie ?", 'options': <String>["I’d like a sandwich, please.", "Give sandwich now.", "I want sandwich water."], 'answer': 0, 'correction': "I’d like… please est une demande polie.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L16", 'level': 'A1', 'title': "Comprendre un dialogue au supermarché", 'subtitle': "Sous-chapitre 10 • Leçon 16/50", 'explanation': "Dans un magasin, écoute le produit recherché, son prix et la quantité.", 'example': "Excuse me, where can I find the apples? — Aisle three. = Excusez-moi, où puis-je trouver les pommes ? — Rayon trois.", 'french': "Excusez-moi, où puis-je trouver les pommes ? — Rayon trois.", 'question': "Où se trouvent les pommes ?", 'options': <String>["Aisle three.", "At the bus stop.", "On Monday."], 'answer': 0, 'correction': "Aisle désigne une allée ou un rayon de magasin.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L17", 'level': 'A1', 'title': "Repérer les informations d’un ticket de caisse", 'subtitle': "Sous-chapitre 10 • Leçon 17/50", 'explanation': "Un reçu peut contenir le nom du magasin, les articles, le total et la monnaie rendue.", 'example': "The total is twelve dollars. You paid fifteen, so your change is three dollars. = Le total est de douze dollars. Tu as payé quinze dollars, donc on te rend trois dollars.", 'french': "Le total est de douze dollars. Tu as payé quinze dollars, donc on te rend trois dollars.", 'question': "Combien de monnaie doit-on rendre ?", 'options': <String>["Three dollars.", "Twelve dollars.", "Fifteen dollars."], 'answer': 0, 'correction': "Change signifie la monnaie rendue après le paiement.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L18", 'level': 'A1', 'title': "Écrire un message pour inviter un ami", 'subtitle': "Sous-chapitre 10 • Leçon 18/50", 'explanation': "Un message d’invitation indique l’activité, le jour et parfois le lieu.", 'example': "Do you want to play football with us on Saturday? = Veux-tu jouer au football avec nous samedi ?", 'french': "Veux-tu jouer au football avec nous samedi ?", 'question': "Quelle phrase invite quelqu’un ?", 'options': <String>["Do you want to play football with us?", "Where is the football?", "I played football yesterday."], 'answer': 0, 'correction': "Do you want to…? peut servir à inviter quelqu’un.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L19", 'level': 'A1', 'title': "Répondre à une invitation", 'subtitle': "Sous-chapitre 10 • Leçon 19/50", 'explanation': "Accepte avec enthousiasme ou refuse poliment en donnant une raison simple.", 'example': "Thanks for inviting me! I’d love to come. = Merci pour l’invitation ! J’aimerais beaucoup venir.", 'french': "Merci pour l’invitation ! J’aimerais beaucoup venir.", 'question': "Quelle phrase accepte chaleureusement une invitation ?", 'options': <String>["I’d love to come.", "I can’t yesterday.", "Where are you come?"], 'answer': 0, 'correction': "I’d love to… exprime une acceptation enthousiaste.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L20", 'level': 'A1', 'title': "Conversation sur les loisirs", 'subtitle': "Sous-chapitre 10 • Leçon 20/50", 'explanation': "Pour parler de loisirs, utilise play, go ou do selon l’activité.", 'example': "I play basketball after school, and I listen to music at night. = Je joue au basketball après l’école et j’écoute de la musique le soir.", 'french': "Je joue au basketball après l’école et j’écoute de la musique le soir.", 'question': "Quelle activité cette personne fait-elle après l’école ?", 'options': <String>["Plays basketball.", "Watches the news.", "Goes shopping."], 'answer': 0, 'correction': "I play basketball indique une activité sportive.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L21", 'level': 'A1', 'title': "Parler de ses goûts", 'subtitle': "Sous-chapitre 10 • Leçon 21/50", 'explanation': "I like, I don’t like et I prefer permettent d’exprimer ses préférences.", 'example': "I prefer tea to coffee, but I like both. = Je préfère le thé au café, mais j’aime les deux.", 'french': "Je préfère le thé au café, mais j’aime les deux.", 'question': "Que préfère cette personne ?", 'options': <String>["Tea.", "Coffee.", "Neither."], 'answer': 0, 'correction': "Prefer A to B signifie préférer A à B.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L22", 'level': 'A1', 'title': "Décrire une image en phrases complètes", 'subtitle': "Sous-chapitre 10 • Leçon 22/50", 'explanation': "Décris une image avec There is/There are et le présent continu pour les actions visibles.", 'example': "There are three children in the park. Two are playing, and one is reading. = Il y a trois enfants dans le parc. Deux jouent et un lit.", 'french': "Il y a trois enfants dans le parc. Deux jouent et un lit.", 'question': "Combien d’enfants y a-t-il ?", 'options': <String>["Three.", "Two.", "Four."], 'answer': 0, 'correction': "There are three children indique qu’il y a trois enfants.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L23", 'level': 'A1', 'title': "Raconter une action en cours", 'subtitle': "Sous-chapitre 10 • Leçon 23/50", 'explanation': "Le présent continu décrit une action en train de se dérouler au moment où l’on parle.", 'example': "I can’t talk now. I’m doing my homework. = Je ne peux pas parler maintenant. Je fais mes devoirs.", 'french': "Je ne peux pas parler maintenant. Je fais mes devoirs.", 'question': "Pourquoi la personne ne peut-elle pas parler ?", 'options': <String>["Because she is doing homework.", "Because she is sleeping.", "Because she is on a bus."], 'answer': 0, 'correction': "I’m doing indique une action en cours.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L24", 'level': 'A1', 'title': "Comprendre une conversation météo", 'subtitle': "Sous-chapitre 10 • Leçon 24/50", 'explanation': "Les descriptions météo utilisent des adjectifs comme sunny, rainy, cloudy et windy.", 'example': "It’s cloudy now, but it’s going to rain later. = Le ciel est nuageux maintenant, mais il va pleuvoir plus tard.", 'french': "Le ciel est nuageux maintenant, mais il va pleuvoir plus tard.", 'question': "Que prévoit la personne ?", 'options': <String>["Rain later.", "Snow now.", "Strong sunshine all day."], 'answer': 0, 'correction': "Going to rain exprime une prévision fondée sur la situation.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L25", 'level': 'A1', 'title': "Faire une demande polie", 'subtitle': "Sous-chapitre 10 • Leçon 25/50", 'explanation': "Could you…? et Can I…? permettent de demander un service ou une permission poliment.", 'example': "Could you help me carry this bag, please? = Pourriez-vous m’aider à porter ce sac, s’il vous plaît ?", 'french': "Pourriez-vous m’aider à porter ce sac, s’il vous plaît ?", 'question': "Quelle formule rend la demande plus polie ?", 'options': <String>["Could you help me, please?", "Help me now.", "You carry my bag."], 'answer': 0, 'correction': "Could you… please? est une demande polie.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L26", 'level': 'A1', 'title': "S’excuser et expliquer un problème", 'subtitle': "Sous-chapitre 10 • Leçon 26/50", 'explanation': "Excuse-moi/Sorry s’accompagne souvent d’une explication courte du problème.", 'example': "I’m sorry I’m late. The bus didn’t arrive on time. = Je suis désolé d’être en retard. Le bus n’est pas arrivé à l’heure.", 'french': "Je suis désolé d’être en retard. Le bus n’est pas arrivé à l’heure.", 'question': "Pourquoi la personne est-elle en retard ?", 'options': <String>["The bus didn’t arrive on time.", "She missed breakfast.", "The shop was closed."], 'answer': 0, 'correction': "The bus didn’t arrive on time donne la raison du retard.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L27", 'level': 'A1', 'title': "Demander de répéter en conversation", 'subtitle': "Sous-chapitre 10 • Leçon 27/50", 'explanation': "Utilise Could you repeat that? ou Could you speak more slowly? si tu ne comprends pas.", 'example': "Sorry, could you repeat the last sentence? = Désolé, pourriez-vous répéter la dernière phrase ?", 'french': "Désolé, pourriez-vous répéter la dernière phrase ?", 'question': "Quelle phrase demande une répétition ?", 'options': <String>["Could you repeat that?", "What time is it?", "Where is your house?"], 'answer': 0, 'correction': "Repeat that demande de redire ce qui vient d’être dit.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L28", 'level': 'A1', 'title': "Utiliser les contractions naturellement", 'subtitle': "Sous-chapitre 10 • Leçon 28/50", 'explanation': "Les contractions comme I’m, don’t et isn’t sont courantes à l’oral et dans les messages informels.", 'example': "I’m not sure, but I don’t think he’s at home. = Je ne suis pas sûr, mais je ne pense pas qu’il soit à la maison.", 'french': "Je ne suis pas sûr, mais je ne pense pas qu’il soit à la maison.", 'question': "Quelle contraction signifie I am ?", 'options': <String>["I’m.", "Don’t.", "Isn’t."], 'answer': 0, 'correction': "I’m est la contraction de I am.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L29", 'level': 'A1', 'title': "Reconnaître les mots-clés d’un audio lent", 'subtitle': "Sous-chapitre 10 • Leçon 29/50", 'explanation': "Pendant l’écoute, repère les noms, les nombres, les heures et les verbes qui portent l’information principale.", 'example': "The meeting is at half past ten in room four. = La réunion est à dix heures et demie dans la salle quatre.", 'french': "La réunion est à dix heures et demie dans la salle quatre.", 'question': "À quelle heure a lieu la réunion ?", 'options': <String>["At half past ten.", "At ten to four.", "At four thirty."], 'answer': 0, 'correction': "Half past ten signifie dix heures et demie.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L30", 'level': 'A1', 'title': "Lire un message et répondre", 'subtitle': "Sous-chapitre 10 • Leçon 30/50", 'explanation': "Lis d’abord l’objectif du message, puis réponds avec une phrase qui traite directement la demande.", 'example': "Can you meet me at the library at five? — Yes, see you there. = Peux-tu me retrouver à la bibliothèque à cinq heures ? — Oui, à tout à l’heure.", 'french': "Peux-tu me retrouver à la bibliothèque à cinq heures ? — Oui, à tout à l’heure.", 'question': "Où les deux personnes vont-elles se retrouver ?", 'options': <String>["At the library.", "At the supermarket.", "At home."], 'answer': 0, 'correction': "La réponse confirme le lieu mentionné dans le message.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L31", 'level': 'A1', 'title': "Remettre un dialogue en ordre", 'subtitle': "Sous-chapitre 10 • Leçon 31/50", 'explanation': "Un dialogue suit généralement l’ordre salutation, question, réponse et formule de clôture.", 'example': "Hi! How are you? — I’m good, thanks. — See you later! = Salut ! Comment vas-tu ? — Bien, merci. — À plus tard !", 'french': "Salut ! Comment vas-tu ? — Bien, merci. — À plus tard !", 'question': "Quelle expression peut terminer cet échange ?", 'options': <String>["See you later!", "What’s your name?", "How much is it?"], 'answer': 0, 'correction': "See you later est une formule naturelle pour prendre congé.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L32", 'level': 'A1', 'title': "Choisir une réponse conversationnelle", 'subtitle': "Sous-chapitre 10 • Leçon 32/50", 'explanation': "Choisis une réponse qui correspond au sens de la question et permet à l’échange de continuer.", 'example': "Would you like some tea? — Yes, please. = Voudrais-tu du thé ? — Oui, s’il te plaît.", 'french': "Voudrais-tu du thé ? — Oui, s’il te plaît.", 'question': "Quelle réponse accepte l’offre ?", 'options': <String>["Yes, please.", "I’m fourteen.", "It’s next to the bank."], 'answer': 0, 'correction': "Yes, please accepte poliment ce qui est proposé.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L33", 'level': 'A1', 'title': "Corriger les erreurs de pronoms et to be", 'subtitle': "Sous-chapitre 10 • Leçon 33/50", 'explanation': "Le sujet détermine le pronom et la forme de be : I am, she is, they are.", 'example': "They are my friends. They are very kind. = Ce sont mes amis. Ils sont très gentils.", 'french': "Ce sont mes amis. Ils sont très gentils.", 'question': "Quelle phrase associe correctement they et le verbe to be ?", 'options': <String>["They are my friends.", "They is my friends.", "They am my friends."], 'answer': 0, 'correction': "Avec they, la forme correcte est are.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L34", 'level': 'A1', 'title': "Corriger les erreurs d’articles et pluriels", 'subtitle': "Sous-chapitre 10 • Leçon 34/50", 'explanation': "Choisis a/an selon le son initial et ajoute la marque du pluriel lorsque c’est nécessaire.", 'example': "She has an umbrella and two bags. = Elle a un parapluie et deux sacs.", 'french': "Elle a un parapluie et deux sacs.", 'question': "Quelle phrase utilise correctement l’article an et le pluriel bags ?", 'options': <String>["She has an umbrella and two bags.", "She has a umbrella and two bag.", "She have an umbrella and two bags."], 'answer': 0, 'correction': "An précède le son voyelle de umbrella et bags est au pluriel.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L35", 'level': 'A1', 'title': "Corriger les erreurs du présent simple", 'subtitle': "Sous-chapitre 10 • Leçon 35/50", 'explanation': "Au présent simple, he/she/it prennent souvent -s ; les questions utilisent does et la base verbale.", 'example': "He works every day, but he doesn’t work on Sunday. = Il travaille tous les jours, mais il ne travaille pas le dimanche.", 'french': "Il travaille tous les jours, mais il ne travaille pas le dimanche.", 'question': "Quelle phrase négative est correcte ?", 'options': <String>["He doesn’t work on Sunday.", "He doesn’t works on Sunday.", "He not work on Sunday."], 'answer': 0, 'correction': "Après doesn’t, le verbe reste à la base : work.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L36", 'level': 'A1', 'title': "Réviser les verbes dans des phrases inédites", 'subtitle': "Sous-chapitre 10 • Leçon 36/50", 'explanation': "Choisis la forme verbale en fonction du sujet et du temps indiqué par la phrase.", 'example': "Yesterday, Maya went to school and studied English. = Hier, Maya est allée à l’école et a étudié l’anglais.", 'french': "Hier, Maya est allée à l’école et a étudié l’anglais.", 'question': "Quel est le passé de go ?", 'options': <String>["Went.", "Goed.", "Going."], 'answer': 0, 'correction': "Go est irrégulier : son passé simple est went.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L37", 'level': 'A1', 'title': "Réviser les questions et réponses courtes", 'subtitle': "Sous-chapitre 10 • Leçon 37/50", 'explanation': "Les réponses courtes reprennent l’auxiliaire de la question : do, be, can ou have.", 'example': "Can she swim? — Yes, she can. = Sait-elle nager ? — Oui.", 'french': "Sais-tu nager ? — Oui.", 'question': "Quelle est la réponse courte correcte ?", 'options': <String>["Yes, I can.", "Yes, I do.", "Yes, I am."], 'answer': 0, 'correction': "La question utilise can ; la réponse courte reprend can.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L38", 'level': 'A1', 'title': "Réviser les prépositions de lieu", 'subtitle': "Sous-chapitre 10 • Leçon 38/50", 'explanation': "Les prépositions décrivent la position relative des objets : under, behind, between, next to.", 'example': "The cat is under the chair. = Le chat est sous la chaise.", 'french': "Le chat est sous la chaise.", 'question': "Que signifie under ?", 'options': <String>["Sous.", "Derrière.", "Entre."], 'answer': 0, 'correction': "Under signifie sous.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L39", 'level': 'A1', 'title': "Réviser les expressions de politesse", 'subtitle': "Sous-chapitre 10 • Leçon 39/50", 'explanation': "Please, thank you, excuse me et sorry rendent les échanges plus respectueux.", 'example': "Excuse me, could you help me, please? = Excusez-moi, pourriez-vous m’aider, s’il vous plaît ?", 'french': "Excusez-moi, pourriez-vous m’aider, s’il vous plaît ?", 'question': "Quelle expression attire poliment l’attention ?", 'options': <String>["Excuse me.", "Good night.", "Never mind."], 'answer': 0, 'correction': "Excuse me attire l’attention de façon polie.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L40", 'level': 'A1', 'title': "Révision mixte vocabulaire-grammaire", 'subtitle': "Sous-chapitre 10 • Leçon 40/50", 'explanation': "Pour choisir une réponse, vérifie le sens, le sujet, le temps verbal et l’ordre des mots.", 'example': "My brother doesn’t like coffee, but he loves tea. = Mon frère n’aime pas le café, mais il adore le thé.", 'french': "Mon frère n’aime pas le café, mais il adore le thé.", 'question': "Quelle boisson aime-t-il ?", 'options': <String>["Tea.", "Coffee.", "Juice."], 'answer': 0, 'correction': "He loves tea indique qu’il adore le thé.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L41", 'level': 'A1', 'title': "Se présenter sans modèle", 'subtitle': "Sous-chapitre 10 • Leçon 41/50", 'explanation': "Réutilise les formules de présentation sans copier un exemple mot à mot.", 'example': "Hi, I’m Sam. I’m from Ghana, and I’m learning English. = Salut, je suis Sam. Je viens du Ghana et j’apprends l’anglais.", 'french': "Salut, je suis Sam. Je viens du Ghana et j’apprends l’anglais.", 'question': "Quelle phrase indique le pays d’origine ?", 'options': <String>["I’m from Ghana.", "I’m learning English.", "Hi, I’m Sam."], 'answer': 0, 'correction': "I’m from + pays indique l’origine.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L42", 'level': 'A1', 'title': "Parler de sa famille", 'subtitle': "Sous-chapitre 10 • Leçon 42/50", 'explanation': "Présente un membre de ta famille avec son lien de parenté et une description simple.", 'example': "My older sister is a nurse, and she is very friendly. = Ma grande sœur est infirmière et elle est très sympathique.", 'french': "Ma grande sœur est infirmière et elle est très sympathique.", 'question': "Quel est le métier de sa sœur ?", 'options': <String>["A nurse.", "A teacher.", "A student."], 'answer': 0, 'correction': "Nurse signifie infirmière ou infirmier.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L43", 'level': 'A1', 'title': "Commander et payer", 'subtitle': "Sous-chapitre 10 • Leçon 43/50", 'explanation': "Utilise une demande polie, vérifie le prix et remercie après le paiement.", 'example': "Can I have the bill, please? — Certainly. = Puis-je avoir l’addition, s’il vous plaît ? — Bien sûr.", 'french': "Puis-je avoir l’addition, s’il vous plaît ? — Bien sûr.", 'question': "Que demande le client ?", 'options': <String>["The bill.", "The menu.", "A bus ticket."], 'answer': 0, 'correction': "The bill est l’addition au restaurant.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L44", 'level': 'A1', 'title': "Demander son chemin", 'subtitle': "Sous-chapitre 10 • Leçon 44/50", 'explanation': "Commence par Excuse me, pose une question claire, puis vérifie les directions reçues.", 'example': "Excuse me, how can I get to the hospital? = Excusez-moi, comment puis-je aller à l’hôpital ?", 'french': "Excusez-moi, comment puis-je aller à l’hôpital ?", 'question': "Comment demander poliment comment aller jusqu’à l’hôpital ?", 'options': <String>["How can I get to the hospital?", "How much is the hospital?", "What time are you?"], 'answer': 0, 'correction': "How can I get to…? demande comment se rendre à un lieu.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L45", 'level': 'A1', 'title': "Parler de sa journée", 'subtitle': "Sous-chapitre 10 • Leçon 45/50", 'explanation': "Raconte les étapes de ta journée dans l’ordre avec le présent simple et des connecteurs.", 'example': "I go to school in the morning, do homework in the afternoon, and read at night. = Je vais à l’école le matin, fais mes devoirs l’après-midi et lis le soir.", 'french': "Je vais à l’école le matin, fais mes devoirs l’après-midi et lis le soir.", 'question': "Quand la personne lit-elle ?", 'options': <String>["At night.", "In the morning.", "At noon."], 'answer': 0, 'correction': "At night indique le soir ou la nuit.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L46", 'level': 'A1', 'title': "Évaluation de compréhension orale A1", 'subtitle': "Sous-chapitre 10 • Leçon 46/50", 'explanation': "Écoute une courte phrase et identifie l’information essentielle sans traduire chaque mot.", 'example': "The train leaves at six fifteen from platform two. = Le train part à six heures quinze du quai deux.", 'french': "Le train part à six heures quinze du quai deux.", 'question': "De quel quai part le train ?", 'options': <String>["Platform two.", "Platform six.", "Platform fifteen."], 'answer': 0, 'correction': "Platform two indique le quai numéro deux.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L47", 'level': 'A1', 'title': "Évaluation de compréhension écrite A1", 'subtitle': "Sous-chapitre 10 • Leçon 47/50", 'explanation': "Lis un court texte et repère les informations explicites comme le lieu, l’heure et l’activité.", 'example': "Lena works at a café from Monday to Friday. = Lena travaille dans un café du lundi au vendredi.", 'french': "Lena travaille dans un café du lundi au vendredi.", 'question': "Où travaille Lena ?", 'options': <String>["At a café.", "At a school.", "At a hospital."], 'answer': 0, 'correction': "At a café donne le lieu de travail.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L48", 'level': 'A1', 'title': "Évaluation d’expression écrite A1", 'subtitle': "Sous-chapitre 10 • Leçon 48/50", 'explanation': "Écris plusieurs phrases simples reliées par and ou but, en vérifiant le sujet et le verbe.", 'example': "I’m a student, and I study English every evening. = Je suis élève et j’étudie l’anglais chaque soir.", 'french': "Je suis élève et j’étudie l’anglais chaque soir.", 'question': "Quelle phrase est correctement écrite ?", 'options': <String>["I’m a student, and I study English every evening.", "I student and study English every evenings.", "I am student, I studies English."], 'answer': 0, 'correction': "I’m a student et I study respectent la structure correcte.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L49", 'level': 'A1', 'title': "Évaluation orale guidée A1", 'subtitle': "Sous-chapitre 10 • Leçon 49/50", 'explanation': "Réponds à une question simple avec une phrase complète, puis ajoute une information utile.", 'example': "What do you do after school? — I play football with my friends. = Que fais-tu après l’école ? — Je joue au football avec mes amis.", 'french': "Que fais-tu après l’école ? — Je joue au football avec mes amis.", 'question': "Quelle réponse répond directement à la question ?", 'options': <String>["I play football with my friends.", "My name is Daniel.", "It is next to the bank."], 'answer': 0, 'correction': "La question demande une activité après l’école.", 'unit': 10, 'phase': 0},
  <String, dynamic>{'id': "A1-U10-L50", 'level': 'A1', 'title': "Évaluation finale intégrée et bilan A1", 'subtitle': "Sous-chapitre 10 • Leçon 50/50", 'explanation': "Réutilise les salutations, les verbes fréquents, les questions, les directions et les demandes polies dans des situations simples.", 'example': "Hello! Could you tell me where the bus stop is? = Bonjour ! Pourriez-vous me dire où se trouve l’arrêt de bus ?", 'french': "Bonjour ! Pourriez-vous me dire où se trouve l’arrêt de bus ?", 'question': "Quelle phrase demande poliment un lieu ?", 'options': <String>["Could you tell me where the bus stop is?", "I am fourteen years old.", "I like playing football."], 'answer': 0, 'correction': "Could you tell me…? est une demande polie d’information.", 'unit': 10, 'phase': 0},
